// Minimal JSON value / parser / serializer.
#pragma once
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cmath>
#include <stdexcept>

namespace json {

struct Value;
using Object = std::vector<std::pair<std::string, Value>>; // ordered
using Array = std::vector<Value>;

struct Value {
    enum Type { Null, Bool, Int, Double, String, Arr, Obj } type = Null;
    bool b = false;
    int64_t i = 0;
    double d = 0;
    std::string s;
    std::shared_ptr<Array> arr;
    std::shared_ptr<Object> obj;

    Value() {}
    static Value null() { return Value(); }
    static Value boolean(bool v) { Value r; r.type = Bool; r.b = v; return r; }
    static Value integer(int64_t v) { Value r; r.type = Int; r.i = v; return r; }
    static Value number(double v) { Value r; r.type = Double; r.d = v; return r; }
    static Value string(const std::string& v) { Value r; r.type = String; r.s = v; return r; }
    static Value array() { Value r; r.type = Arr; r.arr = std::make_shared<Array>(); return r; }
    static Value object() { Value r; r.type = Obj; r.obj = std::make_shared<Object>(); return r; }

    bool is_null() const { return type == Null; }
    bool is_object() const { return type == Obj; }
    bool is_array() const { return type == Arr; }
    bool is_string() const { return type == String; }
    bool is_number() const { return type == Int || type == Double; }
    bool is_bool() const { return type == Bool; }

    const Value* get(const std::string& key) const {
        if (type != Obj) return nullptr;
        for (auto& kv : *obj) if (kv.first == key) return &kv.second;
        return nullptr;
    }
    Value* get(const std::string& key) {
        if (type != Obj) return nullptr;
        for (auto& kv : *obj) if (kv.first == key) return &kv.second;
        return nullptr;
    }
    Value& set(const std::string& key, const Value& v) {
        if (type != Obj) { type = Obj; obj = std::make_shared<Object>(); }
        for (auto& kv : *obj) if (kv.first == key) { kv.second = v; return kv.second; }
        obj->emplace_back(key, v);
        return obj->back().second;
    }
    void push(const Value& v) {
        if (type != Arr) { type = Arr; arr = std::make_shared<Array>(); }
        arr->push_back(v);
    }
    std::string str_or(const std::string& def) const { return type == String ? s : def; }
    bool bool_or(bool def) const { return type == Bool ? b : def; }
    int64_t int_or(int64_t def) const { return type == Int ? i : (type == Double ? (int64_t) d : def); }
    double num() const { return type == Int ? (double) i : (type == Double ? d : 0.0); }
    size_t size() const { return type == Arr ? arr->size() : (type == Obj ? obj->size() : 0); }
    const Value& operator[](size_t idx) const { return (*arr)[idx]; }
};

struct ParseError : std::runtime_error {
    size_t offset;
    ParseError(const std::string& m, size_t off) : std::runtime_error(m), offset(off) {}
};

class Parser {
public:
    Parser(const char* s, size_t n) : p(s), end(s + n), start(s) {}
    Value parse_document() {
        skip_ws();
        Value v = parse_value();
        skip_ws();
        if (p != end) fail("trailing characters");
        return v;
    }
    // Parse a single value; leaves p after it (used for JSON-lines check)
    Value parse_value() {
        skip_ws();
        if (p >= end) fail("unexpected end");
        switch (*p) {
        case '{': return parse_object();
        case '[': return parse_array();
        case '"': { Value v; v.type = Value::String; v.s = parse_string(); return v; }
        case 't': expect("true"); return Value::boolean(true);
        case 'f': expect("false"); return Value::boolean(false);
        case 'n': expect("null"); return Value();
        default:
            if (*p == '-' || (*p >= '0' && *p <= '9')) return parse_number();
            fail("unexpected character");
        }
        return Value();
    }
    const char* pos() const { return p; }
    void skip_ws() { while (p < end && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++; }
private:
    const char* p; const char* end; const char* start;
    [[noreturn]] void fail(const std::string& m) { throw ParseError(m, p - start); }
    void expect(const char* lit) {
        size_t n = strlen(lit);
        if ((size_t)(end - p) < n || memcmp(p, lit, n) != 0) fail("invalid literal");
        p += n;
    }
    Value parse_object() {
        Value v = Value::object();
        p++; skip_ws();
        if (p < end && *p == '}') { p++; return v; }
        while (true) {
            skip_ws();
            if (p >= end || *p != '"') fail("expected string key");
            std::string key = parse_string();
            skip_ws();
            if (p >= end || *p != ':') fail("expected ':'");
            p++;
            Value val = parse_value();
            v.obj->emplace_back(std::move(key), std::move(val));
            skip_ws();
            if (p >= end) fail("unterminated object");
            if (*p == ',') { p++; continue; }
            if (*p == '}') { p++; return v; }
            fail("expected ',' or '}'");
        }
    }
    Value parse_array() {
        Value v = Value::array();
        p++; skip_ws();
        if (p < end && *p == ']') { p++; return v; }
        while (true) {
            v.arr->push_back(parse_value());
            skip_ws();
            if (p >= end) fail("unterminated array");
            if (*p == ',') { p++; continue; }
            if (*p == ']') { p++; return v; }
            fail("expected ',' or ']'");
        }
    }
    static void append_utf8(std::string& out, uint32_t cp) {
        if (cp < 0x80) out += (char) cp;
        else if (cp < 0x800) { out += (char)(0xC0 | (cp >> 6)); out += (char)(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { out += (char)(0xE0 | (cp >> 12)); out += (char)(0x80 | ((cp >> 6) & 0x3F)); out += (char)(0x80 | (cp & 0x3F)); }
        else { out += (char)(0xF0 | (cp >> 18)); out += (char)(0x80 | ((cp >> 12) & 0x3F)); out += (char)(0x80 | ((cp >> 6) & 0x3F)); out += (char)(0x80 | (cp & 0x3F)); }
    }
    std::string parse_string() {
        p++; // opening quote
        std::string out;
        while (true) {
            if (p >= end) fail("unterminated string");
            char c = *p++;
            if (c == '"') break;
            if (c == '\\') {
                if (p >= end) fail("bad escape");
                char e = *p++;
                switch (e) {
                case '"': out += '"'; break;
                case '\\': out += '\\'; break;
                case '/': out += '/'; break;
                case 'b': out += '\b'; break;
                case 'f': out += '\f'; break;
                case 'n': out += '\n'; break;
                case 'r': out += '\r'; break;
                case 't': out += '\t'; break;
                case 'u': {
                    uint32_t cp = parse_hex4();
                    if (cp >= 0xD800 && cp <= 0xDBFF && end - p >= 6 && p[0] == '\\' && p[1] == 'u') {
                        p += 2;
                        uint32_t lo = parse_hex4();
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    append_utf8(out, cp);
                    break;
                }
                default: fail("bad escape");
                }
            } else {
                out += c;
            }
        }
        return out;
    }
    uint32_t parse_hex4() {
        if (end - p < 4) fail("bad unicode escape");
        uint32_t v = 0;
        for (int k = 0; k < 4; k++) {
            char c = *p++;
            v <<= 4;
            if (c >= '0' && c <= '9') v |= c - '0';
            else if (c >= 'a' && c <= 'f') v |= c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') v |= c - 'A' + 10;
            else fail("bad hex");
        }
        return v;
    }
    Value parse_number() {
        const char* s = p;
        bool is_double = false;
        if (*p == '-') p++;
        while (p < end && *p >= '0' && *p <= '9') p++;
        if (p < end && *p == '.') { is_double = true; p++; while (p < end && *p >= '0' && *p <= '9') p++; }
        if (p < end && (*p == 'e' || *p == 'E')) { is_double = true; p++; if (p < end && (*p == '+' || *p == '-')) p++; while (p < end && *p >= '0' && *p <= '9') p++; }
        std::string tok(s, p - s);
        if (!is_double) {
            errno = 0;
            long long v = strtoll(tok.c_str(), nullptr, 10);
            if (errno == ERANGE) { return Value::number(strtod(tok.c_str(), nullptr)); }
            return Value::integer(v);
        }
        return Value::number(strtod(tok.c_str(), nullptr));
    }
};

inline Value parse(const std::string& s) { Parser p(s.data(), s.size()); return p.parse_document(); }

inline void escape_string(std::string& out, const std::string& s) {
    out += '"';
    for (unsigned char c : s) {
        switch (c) {
        case '"': out += "\\\""; break;
        case '\\': out += "\\\\"; break;
        case '\n': out += "\\n"; break;
        case '\r': out += "\\r"; break;
        case '\t': out += "\\t"; break;
        case '\b': out += "\\b"; break;
        case '\f': out += "\\f"; break;
        default:
            if (c < 0x20) { char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c); out += buf; }
            else out += (char) c;
        }
    }
    out += '"';
}

std::string format_double(double d); // defined in util

inline void serialize(std::string& out, const Value& v, int indent = -1, int level = 0) {
    auto nl = [&](int lvl) { if (indent >= 0) { out += '\n'; out.append(lvl * indent, ' '); } };
    switch (v.type) {
    case Value::Null: out += "null"; break;
    case Value::Bool: out += v.b ? "true" : "false"; break;
    case Value::Int: out += std::to_string(v.i); break;
    case Value::Double: out += format_double(v.d); break;
    case Value::String: escape_string(out, v.s); break;
    case Value::Arr:
        out += '[';
        if (v.arr->empty()) { out += ']'; break; }
        for (size_t k = 0; k < v.arr->size(); k++) {
            if (k) out += ',';
            nl(level + 1);
            serialize(out, (*v.arr)[k], indent, level + 1);
        }
        nl(level);
        out += ']';
        break;
    case Value::Obj:
        out += '{';
        if (v.obj->empty()) { out += '}'; break; }
        for (size_t k = 0; k < v.obj->size(); k++) {
            if (k) out += ',';
            nl(level + 1);
            escape_string(out, (*v.obj)[k].first);
            out += indent >= 0 ? ": " : ":";
            serialize(out, (*v.obj)[k].second, indent, level + 1);
        }
        nl(level);
        out += '}';
        break;
    }
}

inline std::string to_string(const Value& v, int indent = -1) { std::string s; serialize(s, v, indent); return s; }

} // namespace json
