static inline bool is_digit(char c) { return c >= '0' && c <= '9'; }

static bool parse_digits(const char* str, size_t& off, size_t len, int min_digits, int max_digits, int64_t& out)
{
    int64_t v = 0;
    int n = 0;
    while (off < len && n < max_digits && is_digit(str[off])) {
        v = v * 10 + (str[off] - '0');
        off++; n++;
    }
    if (n < min_digits) return false;
    out = v;
    return true;
}

static bool parse_2(const char* str, size_t& off, size_t len, int& out, bool allow_space_pad)
{
    if (off + 2 > len) {
        if (allow_space_pad && off + 1 <= len && is_digit(str[off])) { out = str[off] - '0'; off++; return true; }
        return false;
    }
    char a = str[off], b = str[off + 1];
    if (allow_space_pad && a == ' ' && is_digit(b)) { out = b - '0'; off += 2; return true; }
    if (!is_digit(a)) return false;
    if (!is_digit(b)) {
        if (allow_space_pad) { out = a - '0'; off += 1; return true; }
        return false;
    }
    out = (a - '0') * 10 + (b - '0');
    off += 2;
    return true;
}

// %z : Z | [+-]HH[:]MM
static bool parse_zone_offset(const char* str, size_t& off, size_t len, exttm& tm)
{
    if (off >= len) return false;
    if (str[off] == 'Z' || str[off] == 'z') {
        off++;
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_Z_FOR_UTC;
        return true;
    }
    if (str[off] != '+' && str[off] != '-') return false;
    int sign = str[off] == '-' ? -1 : 1;
    size_t p = off + 1;
    if (p + 2 > len || !is_digit(str[p]) || !is_digit(str[p + 1])) return false;
    int hh = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    bool colon = false;
    if (p < len && str[p] == ':') { colon = true; p++; }
    if (p + 2 > len || !is_digit(str[p]) || !is_digit(str[p + 1])) return false;
    int mm = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    off = p;
    tm.et_gmtoff = sign * (hh * 3600 + mm * 60);
    tm.et_flags |= exttm::ETF_ZONE_SET;
    if (colon) tm.et_flags |= exttm::ETF_Z_COLON;
    return true;
}

// %Z : timezone abbreviation (letters)
static bool parse_zone_name(const char* str, size_t& off, size_t len, exttm& tm)
{
    size_t p = off;
    while (p < len && isalpha((unsigned char) str[p])) p++;
    size_t n = p - off;
    if (n == 0) return false;
    if (n == 1 && (str[off] == 'Z' || str[off] == 'z')) {
        off = p;
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_Z_FOR_UTC;
        return true;
    }
    if (n < 2) return false;
    std::string name(str + off, n);
    long offv = 0;
    if (lookup_zone_abbrev(name, offv)) {
        tm.et_gmtoff = offv;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_ZONE_NAME;
    } else {
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_NAME;
    }
    off = p;
    return true;
}

