            if (v > 23) return false;
            tm.et_tm.tm_hour = v;
            tm.et_flags |= exttm::ETF_HOUR_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'I': case 'l': {
            int v;
            if (!parse_2(str, o, len, v, true)) return false;
            if (v < 1 || v > 12) return false;
            tm.et_tm.tm_hour = v;
            tm.et_flags |= exttm::ETF_HOUR_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'M': {
            int v;
            if (!parse_2(str, o, len, v, false)) return false;
            if (v > 59) return false;
            tm.et_tm.tm_min = v;
            tm.et_flags |= exttm::ETF_MINUTE_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'S': {
            int v;
            if (!parse_2(str, o, len, v, false)) return false;
            if (v > 59) return false;
            tm.et_tm.tm_sec = v;
            tm.et_flags |= exttm::ETF_SECOND_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'p': {
            if (o + 2 > len) return false;
            char a = (char) toupper((unsigned char) str[o]);
            char b = (char) toupper((unsigned char) str[o + 1]);
            if (b != 'M' || (a != 'A' && a != 'P')) return false;
            pm = (a == 'P');
            have_ampm = true;
            o += 2;
            break;
        }
        case 'b': case 'h': case 'B': {
            if (o + 3 > len) return false;
            int found = -1;
            for (int k = 0; k < 12; k++) {
                if (strncasecmp(str + o, MONTHS[k], 3) == 0) { found = k; break; }
            }
            if (found < 0) return false;
            o += 3;
            if (*f == 'B') {
                // consume the rest of the full month name if present
                const char* full = MONTHS_FULL[found];
                size_t fl = strlen(full);
                if (fl > 3 && o + (fl - 3) <= len && strncasecmp(str + o, full + 3, fl - 3) == 0) o += fl - 3;
            }
            tm.et_tm.tm_mon = found;
            tm.et_flags |= exttm::ETF_MONTH_SET;
            break;
        }
        case 'a': case 'A': {
            if (o + 3 > len) return false;
            int found = -1;
            for (int k = 0; k < 7; k++) {
                if (strncasecmp(str + o, DAYS[k], 3) == 0) { found = k; break; }
            }
            if (found < 0) return false;
            o += 3;
            if (*f == 'A') {
                const char* full = DAYS_FULL[found];
                size_t fl = strlen(full);
                if (o + (fl - 3) <= len && strncasecmp(str + o, full + 3, fl - 3) == 0) o += fl - 3;
            }
            tm.et_tm.tm_wday = found;
            break;
        }
        case 'L': {  // milliseconds (3 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 3, 3, v)) return false;
            o = p;
            tm.et_nsec = v * 1000000;
            tm.et_flags |= exttm::ETF_MILLIS_SET;
            break;
        }
        case 'f': {  // microseconds (6 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 6, 6, v)) return false;
            o = p;
            tm.et_nsec = v * 1000;
            tm.et_flags |= exttm::ETF_MICROS_SET;
            break;
        }
        case 'N': {  // nanoseconds (9 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 9, 9, v)) return false;
            o = p;
            tm.et_nsec = v;
            tm.et_flags |= exttm::ETF_NANOS_SET;
            break;
        }
        case 's': {  // seconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) v;
            gmtime_r(&t, &tm.et_tm);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'i': {  // milliseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000) * 1000000;
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_MILLIS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case '6': {  // microseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000000) * 1000;
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_MICROS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case '9': {  // nanoseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000000000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000000000);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_NANOS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'j': {
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 3, 3, v)) return false;
            o = p;
            tm.et_tm.tm_yday = (int) v - 1;
            break;
        }
        case 'z': {
            if (!parse_zone_offset(str, o, len, tm)) return false;
            break;
        }
        case 'Z': {
            if (!parse_zone_name(str, o, len, tm)) return false;
            break;
        }
        case 'q': {  // hex epoch seconds
            size_t p = o; int64_t v = 0; int n = 0;
            while (p < len && isxdigit((unsigned char) str[p]) && n < 16) { v = v * 16 + (isdigit((unsigned char) str[p]) ? str[p] - '0' : (tolower(str[p]) - 'a' + 10)); p++; n++; }
            if (n == 0) return false;
            o = p;
            time_t t = (time_t) v;
            gmtime_r(&t, &tm.et_tm);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_HAS_TIME;
            break;
        }
        default:
            return false;
        }
    }
    if (have_ampm) {
        int h = tm.et_tm.tm_hour;
        if (pm && h < 12) h += 12;
        if (!pm && h == 12) h = 0;
        tm.et_tm.tm_hour = h;
    }
    off = o;
    return true;
}

static void append_num(std::string& out, int64_t v, int width, char pad = '0')
{
    char buf[32];
    if (pad == '0') snprintf(buf, sizeof(buf), "%0*lld", width, (long long) v);
    else snprintf(buf, sizeof(buf), "%*lld", width, (long long) v);
    out += buf;
}

std::string ftime_fmt(const char* fmt, const exttm& tm)
{
    std::string out;
    const struct tm& t = tm.et_tm;
    for (const char* f = fmt; *f; f++) {
        if (*f != '%') { out += *f; continue; }
        f++;
        switch (*f) {
        case '\0': return out;
        case '%': out += '%'; break;
        case 'Y': append_num(out, t.tm_year + 1900, 4); break;
        case 'y': append_num(out, (t.tm_year + 1900) % 100, 2); break;
        case 'm': append_num(out, t.tm_mon + 1, 2); break;
        case 'd': append_num(out, t.tm_mday, 2); break;
        case 'e': append_num(out, t.tm_mday, 2, ' '); break;
        case 'H': append_num(out, t.tm_hour, 2); break;
        case 'k': append_num(out, t.tm_hour, 2, ' '); break;
        case 'I': append_num(out, t.tm_hour % 12 == 0 ? 12 : t.tm_hour % 12, 2); break;
        case 'l': append_num(out, t.tm_hour % 12 == 0 ? 12 : t.tm_hour % 12, 2, ' '); break;
        case 'M': append_num(out, t.tm_min, 2); break;
        case 'S': append_num(out, t.tm_sec, 2); break;
        case 'p': out += t.tm_hour >= 12 ? "PM" : "AM"; break;
        case 'b': case 'h': out += MONTHS_CAP[(t.tm_mon % 12 + 12) % 12]; break;
        case 'B': out += MONTHS_FULL[(t.tm_mon % 12 + 12) % 12]; break;
        case 'a': out += DAYS_CAP[(t.tm_wday % 7 + 7) % 7]; break;
        case 'A': out += DAYS_FULL[(t.tm_wday % 7 + 7) % 7]; break;
        case 'j': append_num(out, t.tm_yday + 1, 3); break;
        case 'L': append_num(out, tm.et_nsec / 1000000, 3); break;
        case 'f': append_num(out, tm.et_nsec / 1000, 6); break;
        case 'N': append_num(out, tm.et_nsec, 9); break;
        case 's': append_num(out, (int64_t) tm2sec(&t) - tm.et_gmtoff, 1); break;
        case 'i': append_num(out, ((int64_t) tm2sec(&t) - tm.et_gmtoff) * 1000 + tm.et_nsec / 1000000, 1); break;
        case '6': append_num(out, ((int64_t) tm2sec(&t) - tm.et_gmtoff) * 1000000 + tm.et_nsec / 1000, 1); break;
        case '9': append_num(out, ((int64_t) tm2sec(&t) - tm.et_gmtoff) * 1000000000 + tm.et_nsec, 1); break;
        case 'z': {
            long off = tm.et_gmtoff;
            if ((tm.et_flags & exttm::ETF_Z_FOR_UTC) && off == 0) { out += 'Z'; break; }
            char sign = off < 0 ? '-' : '+';
            if (off < 0) off = -off;
            char buf[16];
            if (tm.et_flags & exttm::ETF_Z_COLON) snprintf(buf, sizeof(buf), "%c%02ld:%02ld", sign, off / 3600, (off % 3600) / 60);
            else snprintf(buf, sizeof(buf), "%c%02ld%02ld", sign, off / 3600, (off % 3600) / 60);
            out += buf;
            break;
        }
        case 'Z': {
            if (tm.et_gmtoff == 0) out += "UTC";
            else {
                long off = tm.et_gmtoff; char sign = off < 0 ? '-' : '+'; if (off < 0) off = -off;
                char buf[16]; snprintf(buf, sizeof(buf), "%c%02ld%02ld", sign, off / 3600, (off % 3600) / 60); out += buf;
            }
            break;
        }
        case 'T': append_num(out, t.tm_hour, 2); out += ':'; append_num(out, t.tm_min, 2); out += ':'; append_num(out, t.tm_sec, 2); break;
        case 'F': append_num(out, t.tm_year + 1900, 4); out += '-'; append_num(out, t.tm_mon + 1, 2); out += '-'; append_num(out, t.tm_mday, 2); break;
        case 'D': append_num(out, t.tm_mon + 1, 2); out += '/'; append_num(out, t.tm_mday, 2); out += '/'; append_num(out, (t.tm_year + 1900) % 100, 2); break;
        case 'R': append_num(out, t.tm_hour, 2); out += ':'; append_num(out, t.tm_min, 2); break;
        case 'n': out += '\n'; break;
        case 't': out += '\t'; break;
        case 'u': append_num(out, t.tm_wday == 0 ? 7 : t.tm_wday, 1); break;
        case 'w': append_num(out, t.tm_wday, 1); break;
        case 'C': append_num(out, (t.tm_year + 1900) / 100, 2); break;
        default: out += '%'; out += *f; break;
        }
    }
    return out;
}

