// Time parsing/formatting utilities modelled after strftime/strptime with
// extensions used by log formats.
#pragma once
#include <ctime>
#include <string>
#include <vector>
#include <cstdint>
#include <sys/time.h>

struct exttm {
    struct tm et_tm {};
    int64_t et_nsec = 0;      // nanoseconds within the second
    long et_gmtoff = 0;       // offset applied (seconds east of UTC)
    unsigned et_flags = 0;    // ETF_* flags

    static constexpr unsigned ETF_YEAR_SET = 1u << 0;
    static constexpr unsigned ETF_MONTH_SET = 1u << 1;
    static constexpr unsigned ETF_DAY_SET = 1u << 2;
    static constexpr unsigned ETF_ZONE_SET = 1u << 3;
    static constexpr unsigned ETF_EPOCH_TIME = 1u << 4;
    static constexpr unsigned ETF_MILLIS_SET = 1u << 5;
    static constexpr unsigned ETF_MICROS_SET = 1u << 6;
    static constexpr unsigned ETF_NANOS_SET = 1u << 7;
    static constexpr unsigned ETF_HOUR_SET = 1u << 8;
    static constexpr unsigned ETF_MINUTE_SET = 1u << 9;
    static constexpr unsigned ETF_SECOND_SET = 1u << 10;
    static constexpr unsigned ETF_SUB_NOT_IN_FORMAT = 1u << 11;
    static constexpr unsigned ETF_Z_FOR_UTC = 1u << 12;
    static constexpr unsigned ETF_Z_COLON = 1u << 13;
    static constexpr unsigned ETF_ZONE_NAME = 1u << 14;
    static constexpr unsigned ETF_HAS_TIME = 1u << 15;

    void init_from(time_t t) {
        gmtime_r(&t, &et_tm);
        et_nsec = 0;
    }
};

// timegm equivalent
time_t tm2sec(const struct tm* t);
void sec2tm(time_t t, struct tm* out);

// Parse `str` (len bytes) starting at offset `off` according to a strptime
// style format.  Returns true on success and advances off.
bool ptime_fmt(const char* fmt, exttm& tm, const char* str, size_t& off, size_t len);

// Format a time according to a strftime-like format with extensions
// (%L millis, %f micros, %N nanos, %z, %Z, %s, %i, %6, %9, %j...).
std::string ftime_fmt(const char* fmt, const exttm& tm);

// Look up a timezone abbreviation, returning offset in seconds east of UTC.
bool lookup_zone_abbrev(const std::string& name, long& offset_out);

// A scanner that recognizes a set of time formats.
class date_time_scanner {
public:
    date_time_scanner() { clear(); }
    void clear();
    void set_base_time(time_t base, const struct tm& tm);
    void unlock() { dts_fmt_lock = -1; dts_fmt_len = -1; }

    // Try to parse a timestamp at the start of [str, str+len).  Returns the
    // pointer to the end of the parsed region or nullptr on failure.  If
    // time_fmt is null the default list of formats is used.
