time_t tm2sec(const struct tm* t)
{
    // days from civil
    int y = t->tm_year + 1900;
    int m = t->tm_mon + 1;
    int d = t->tm_mday;
    // normalize month
    int64_t mon = m - 1;
    int64_t yy = y + mon / 12;
    mon %= 12;
