bool lookup_zone_abbrev(const std::string& name, long& offset_out)
{
    for (const auto& z : ZONES) {
        if (strcasecmp(z.name, name.c_str()) == 0) { offset_out = z.offset; return true; }
    }
    return false;
}

static inline bool is_digit(char c) { return c >= '0' && c <= '9'; }

static bool parse_digits(const char* str, size_t& off, size_t len, int min_digits, int max_digits, int64_t& out)
{
    int64_t v = 0;
    int n = 0;
    while (off < len && n < max_digits && is_digit(str[off])) {
        v = v * 10 + (str[off] - '0');
        off++; n++;
    }
    if (n < min_digits) return false;
    out = v;
    return true;
}

static bool parse_2(const char* str, size_t& off, size_t len, int& out, bool allow_space_pad)
{
    if (off + 2 > len) {
        if (allow_space_pad && off + 1 <= len && is_digit(str[off])) { out = str[off] - '0'; off++; return true; }
        return false;
    }
    char a = str[off], b = str[off + 1];
    if (allow_space_pad && a == ' ' && is_digit(b)) { out = b - '0'; off += 2; return true; }
    if (!is_digit(a)) return false;
    if (!is_digit(b)) {
        if (allow_space_pad) { out = a - '0'; off += 1; return true; }
        return false;
    }
    out = (a - '0') * 10 + (b - '0');
    off += 2;
    return true;
}

// %z : Z | [+-]HH[:]MM
static bool parse_zone_offset(const char* str, size_t& off, size_t len, exttm& tm)
{
    if (off >= len) return false;
    if (str[off] == 'Z' || str[off] == 'z') {
        off++;
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_Z_FOR_UTC;
        return true;
    }
    if (str[off] != '+' && str[off] != '-') return false;
    int sign = str[off] == '-' ? -1 : 1;
    size_t p = off + 1;
    if (p + 2 > len || !is_digit(str[p]) || !is_digit(str[p + 1])) return false;
    int hh = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    bool colon = false;
    if (p < len && str[p] == ':') { colon = true; p++; }
    if (p + 2 > len || !is_digit(str[p]) || !is_digit(str[p + 1])) return false;
    int mm = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    off = p;
    tm.et_gmtoff = sign * (hh * 3600 + mm * 60);
    tm.et_flags |= exttm::ETF_ZONE_SET;
    if (colon) tm.et_flags |= exttm::ETF_Z_COLON;
    return true;
}

// %Z : timezone abbreviation (letters)
static bool parse_zone_name(const char* str, size_t& off, size_t len, exttm& tm)
{
    size_t p = off;
    while (p < len && isalpha((unsigned char) str[p])) p++;
    size_t n = p - off;
    if (n == 0) return false;
    if (n == 1 && (str[off] == 'Z' || str[off] == 'z')) {
        off = p;
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_Z_FOR_UTC;
        return true;
    }
    if (n < 2) return false;
    std::string name(str + off, n);
    long offv = 0;
    if (lookup_zone_abbrev(name, offv)) {
        tm.et_gmtoff = offv;
        tm.et_flags |= exttm::ETF_ZONE_SET | exttm::ETF_ZONE_NAME;
    } else {
        tm.et_gmtoff = 0;
        tm.et_flags |= exttm::ETF_ZONE_NAME;
    }
    off = p;
    return true;
}

bool ptime_fmt(const char* fmt, exttm& tm, const char* str, size_t& off, size_t len)
{
    size_t o = off;
    bool pm = false, have_ampm = false;
    for (const char* f = fmt; *f; f++) {
        if (*f != '%') {
            if (o >= len || str[o] != *f) return false;
            o++;
            continue;
        }
        f++;
        switch (*f) {
        case '\0': return false;
        case '%': if (o >= len || str[o] != '%') return false; o++; break;
        case 'Y': {
            int64_t v;
            size_t p = o;
            if (!parse_digits(str, p, len, 4, 4, v)) return false;
            o = p;
            tm.et_tm.tm_year = (int) v - 1900;
            tm.et_flags |= exttm::ETF_YEAR_SET;
            break;
        }
        case 'y': {
            int v;
            if (!parse_2(str, o, len, v, false)) return false;
            tm.et_tm.tm_year = v < 69 ? v + 100 : v;
            tm.et_flags |= exttm::ETF_YEAR_SET;
            break;
        }
        case 'm': {
            int v;
            if (!parse_2(str, o, len, v, true)) return false;
            if (v < 1 || v > 12) return false;
            tm.et_tm.tm_mon = v - 1;
            tm.et_flags |= exttm::ETF_MONTH_SET;
            break;
        }
        case 'd': case 'e': {
            int v;
            if (!parse_2(str, o, len, v, true)) return false;
            if (v < 1 || v > 31) return false;
            tm.et_tm.tm_mday = v;
            tm.et_flags |= exttm::ETF_DAY_SET;
            break;
        }
        case 'H': case 'k': {
            int v;
            if (!parse_2(str, o, len, v, *f == 'k')) return false;
            if (v > 23) return false;
            tm.et_tm.tm_hour = v;
            tm.et_flags |= exttm::ETF_HOUR_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'I': case 'l': {
            int v;
            if (!parse_2(str, o, len, v, true)) return false;
            if (v < 1 || v > 12) return false;
            tm.et_tm.tm_hour = v;
            tm.et_flags |= exttm::ETF_HOUR_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'M': {
            int v;
            if (!parse_2(str, o, len, v, false)) return false;
            if (v > 59) return false;
            tm.et_tm.tm_min = v;
            tm.et_flags |= exttm::ETF_MINUTE_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'S': {
            int v;
            if (!parse_2(str, o, len, v, false)) return false;
            if (v > 59) return false;
            tm.et_tm.tm_sec = v;
            tm.et_flags |= exttm::ETF_SECOND_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'p': {
            if (o + 2 > len) return false;
            char a = (char) toupper((unsigned char) str[o]);
            char b = (char) toupper((unsigned char) str[o + 1]);
            if (b != 'M' || (a != 'A' && a != 'P')) return false;
            pm = (a == 'P');
            have_ampm = true;
            o += 2;
            break;
        }
        case 'b': case 'h': case 'B': {
            if (o + 3 > len) return false;
            int found = -1;
            for (int k = 0; k < 12; k++) {
                if (strncasecmp(str + o, MONTHS[k], 3) == 0) { found = k; break; }
            }
            if (found < 0) return false;
            o += 3;
            if (*f == 'B') {
                // consume the rest of the full month name if present
                const char* full = MONTHS_FULL[found];
                size_t fl = strlen(full);
                if (fl > 3 && o + (fl - 3) <= len && strncasecmp(str + o, full + 3, fl - 3) == 0) o += fl - 3;
            }
            tm.et_tm.tm_mon = found;
            tm.et_flags |= exttm::ETF_MONTH_SET;
            break;
        }
        case 'a': case 'A': {
            if (o + 3 > len) return false;
            int found = -1;
            for (int k = 0; k < 7; k++) {
                if (strncasecmp(str + o, DAYS[k], 3) == 0) { found = k; break; }
            }
            if (found < 0) return false;
            o += 3;
            if (*f == 'A') {
                const char* full = DAYS_FULL[found];
                size_t fl = strlen(full);
                if (o + (fl - 3) <= len && strncasecmp(str + o, full + 3, fl - 3) == 0) o += fl - 3;
            }
            tm.et_tm.tm_wday = found;
            break;
        }
        case 'L': {  // milliseconds (3 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 3, 3, v)) return false;
            o = p;
            tm.et_nsec = v * 1000000;
            tm.et_flags |= exttm::ETF_MILLIS_SET;
            break;
        }
        case 'f': {  // microseconds (6 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 6, 6, v)) return false;
            o = p;
            tm.et_nsec = v * 1000;
            tm.et_flags |= exttm::ETF_MICROS_SET;
            break;
        }
        case 'N': {  // nanoseconds (9 digits)
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 9, 9, v)) return false;
            o = p;
            tm.et_nsec = v;
            tm.et_flags |= exttm::ETF_NANOS_SET;
            break;
        }
        case 's': {  // seconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) v;
            gmtime_r(&t, &tm.et_tm);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'i': {  // milliseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000) * 1000000;
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_MILLIS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case '6': {  // microseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000000) * 1000;
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_MICROS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case '9': {  // nanoseconds since epoch
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 1, 19, v)) return false;
            o = p;
            time_t t = (time_t) (v / 1000000000);
            gmtime_r(&t, &tm.et_tm);
            tm.et_nsec = (v % 1000000000);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_NANOS_SET | exttm::ETF_HAS_TIME;
            break;
        }
        case 'j': {
            int64_t v; size_t p = o;
            if (!parse_digits(str, p, len, 3, 3, v)) return false;
            o = p;
            tm.et_tm.tm_yday = (int) v - 1;
            break;
        }
        case 'z': {
            if (!parse_zone_offset(str, o, len, tm)) return false;
            break;
        }
        case 'Z': {
            if (!parse_zone_name(str, o, len, tm)) return false;
            break;
        }
        case 'q': {  // hex epoch seconds
            size_t p = o; int64_t v = 0; int n = 0;
            while (p < len && isxdigit((unsigned char) str[p]) && n < 16) { v = v * 16 + (isdigit((unsigned char) str[p]) ? str[p] - '0' : (tolower(str[p]) - 'a' + 10)); p++; n++; }
            if (n == 0) return false;
            o = p;
            time_t t = (time_t) v;
            gmtime_r(&t, &tm.et_tm);
            tm.et_flags |= exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_HAS_TIME;
