const char* const* date_time_scanner::default_formats(size_t& count)
{
    count = sizeof(DEFAULT_TIME_FORMATS) / sizeof(DEFAULT_TIME_FORMATS[0]);
    return DEFAULT_TIME_FORMATS;
}

void date_time_scanner::clear()
{
    dts_fmt_lock = -1;
    dts_fmt_len = -1;
    dts_base_time = 0;
    dts_base_tm = exttm();
    dts_last_time = 0;
    dts_last_tm = exttm();
}

void date_time_scanner::set_base_time(time_t base, const struct tm& tm)
{
    dts_base_time = base;
    dts_base_tm.et_tm = tm;
}

void date_time_scanner::to_timeval(exttm& tm, struct timeval& tv)
{
    time_t t = tm2sec(&tm.et_tm);
    if (tm.et_flags & exttm::ETF_ZONE_SET) {
        t -= tm.et_gmtoff;
    }
    tv.tv_sec = t;
    tv.tv_usec = (suseconds_t) (tm.et_nsec / 1000);
}

const char* date_time_scanner::scan(const char* str, size_t len, const char* const time_fmt[], exttm* tm_out, struct timeval& tv_out, bool convert_local)
{
    size_t nfmts = 0;
    const char* const* fmts = time_fmt;
    if (fmts == nullptr) {
        fmts = default_formats(nfmts);
    } else {
        while (fmts[nfmts] != nullptr) nfmts++;
    }

    // relative/epoch form: +NNNN
    if (len > 1 && str[0] == '+' && is_digit(str[1])) {
        size_t off = 1;
        int64_t v;
        if (parse_digits(str, off, len, 1, 19, v)) {
            exttm tm;
            time_t t = (time_t) v;
            gmtime_r(&t, &tm.et_tm);
            tm.et_flags = exttm::ETF_EPOCH_TIME | exttm::ETF_YEAR_SET | exttm::ETF_MONTH_SET | exttm::ETF_DAY_SET | exttm::ETF_HAS_TIME;
            // fraction
            if (off < len && (str[off] == '.' || str[off] == ',')) {
                size_t p = off + 1; int64_t frac = 0; int n = 0;
                while (p < len && is_digit(str[p]) && n < 9) { frac = frac * 10 + (str[p] - '0'); p++; n++; }
                if (n > 0) { while (n < 9) { frac *= 10; n++; } tm.et_nsec = frac; off = p; while (off < len && is_digit(str[off])) off++; }
            }
            *tm_out = tm;
            tv_out.tv_sec = t;
            tv_out.tv_usec = (suseconds_t) (tm.et_nsec / 1000);
            dts_fmt_lock = -1;
            dts_fmt_len = (int) off;
            return str + off;
        }
    }

    std::vector<int> order;
    order.reserve(nfmts);
    if (dts_fmt_lock >= 0 && (size_t) dts_fmt_lock < nfmts) order.push_back(dts_fmt_lock);
    for (size_t k = 0; k < nfmts; k++) if ((int) k != dts_fmt_lock) order.push_back((int) k);

    for (int idx : order) {
        exttm tm = dts_base_tm;
        tm.et_nsec = 0;
        tm.et_gmtoff = 0;
        tm.et_flags = 0;
        size_t off = 0;
        if (!ptime_fmt(fmts[idx], tm, str, off, len)) continue;

        // sub-second value not covered by the format
        if (!(tm.et_flags & (exttm::ETF_MILLIS_SET | exttm::ETF_MICROS_SET | exttm::ETF_NANOS_SET)) && off < len && (str[off] == '.' || str[off] == ',')) {
            size_t p = off + 1; int64_t frac = 0; int n = 0;
            while (p < len && is_digit(str[p]) && n < 9) { frac = frac * 10 + (str[p] - '0'); p++; n++; }
            if (n > 0) {
                while (n < 9) { frac *= 10; n++; }
                tm.et_nsec = frac - (frac % 1000);
                while (p < len && is_digit(str[p])) p++;
                off = p;
                tm.et_flags |= exttm::ETF_SUB_NOT_IN_FORMAT;
                if (n <= 3) tm.et_flags |= exttm::ETF_MILLIS_SET; else tm.et_flags |= exttm::ETF_MICROS_SET;
            }
        }

        if (tm.et_tm.tm_year < 70 && !(tm.et_flags & exttm::ETF_EPOCH_TIME)) tm.et_tm.tm_year = 80;
        if (dts_default_zone_set && !(tm.et_flags & exttm::ETF_ZONE_SET) && !(tm.et_flags & exttm::ETF_EPOCH_TIME)) {
            tm.et_gmtoff = dts_default_zone_offset;
            tm.et_flags |= exttm::ETF_ZONE_SET;
        }
        to_timeval(tm, tv_out);
        // Keep tm in UTC (local time is UTC in our environment)
        if ((tm.et_flags & exttm::ETF_ZONE_SET) && convert_local && dts_zoned_to_local) {
            exttm conv = tm;
            time_t t = tv_out.tv_sec;
            gmtime_r(&t, &conv.et_tm);
            conv.et_gmtoff = 0;
            tm.et_tm = conv.et_tm;
            tm.et_gmtoff = 0;
            tm.et_flags &= ~exttm::ETF_ZONE_SET;
            tm.et_flags |= exttm::ETF_Z_FOR_UTC;
        }
        *tm_out = tm;
        dts_fmt_lock = idx;
        dts_fmt_len = (int) off;
        dts_last_time = tv_out.tv_sec;
        dts_last_tm = tm;
        return str + off;
    }
    return nullptr;
}
