    Match m;
    while (pos <= s.size() && match(s, m, pos)) {
        out.append(s, pos, m.start(0) - pos);
        // expand replacement
        for (size_t k = 0; k < repl.size(); k++) {
            char c = repl[k];
            if ((c == '$' || c == '\\') && k + 1 < repl.size()) {
                if (repl[k + 1] >= '0' && repl[k + 1] <= '9') {
                    size_t j = k + 1; int idx = 0;
                    while (j < repl.size() && repl[j] >= '0' && repl[j] <= '9') { idx = idx * 10 + (repl[j] - '0'); j++; }
