                if (c == '$' && repl[k + 1] == '{') {
                    size_t close = repl.find('}', k + 2);
                    if (close != std::string::npos) {
                        std::string nm = repl.substr(k + 2, close - k - 2);
                        int idx = name_index(nm);
                        if (idx < 0 && !nm.empty() && isdigit((unsigned char) nm[0])) idx = atoi(nm.c_str());
                        if (idx >= 0) out += m.str(idx);
