{
    static Regex re(
        "(?i)^(?:(?<trace>trace|verbose)|(?<debug5>debug5)|(?<debug4>debug4)|(?<debug3>debug3)|(?<debug2>debug2)|(?<debug>debug)|"
        "(?<info>info)|(?<stats>stats)|(?<notice>notice|note)|(?<warning>warn(?:ing)?)|(?<error>err(?:or)?|fail(?:ed|ure)?)|"
        "(?<critical>critical|severe|alert)|(?<fatal>fatal|emergency)|(?<invalid>invalid))$");
    return re;
}

log_level_t string2level(const char* str, size_t len, bool exact)
{
    static const log_level_t group_levels[] = {
        LEVEL_UNKNOWN, LEVEL_TRACE, LEVEL_DEBUG5, LEVEL_DEBUG4, LEVEL_DEBUG3, LEVEL_DEBUG2, LEVEL_DEBUG, LEVEL_INFO, LEVEL_STATS, LEVEL_NOTICE,
        LEVEL_WARNING, LEVEL_ERROR, LEVEL_CRITICAL, LEVEL_FATAL, LEVEL_INVALID,
    };
    if (len == 1 || (len > 1 && str[1] == ' ')) {
        auto r = abbrev2level(str, 1);
        if (r != LEVEL_UNKNOWN) return r;
    }
    const Regex& re = exact ? level_exact_re() : level_re();
    Regex::Match m;
