static value_kind_t kind_from_string(const std::string& s)
{
    if (s == "string") return VK_STRING;
    if (s == "integer") return VK_INTEGER;
    if (s == "float") return VK_FLOAT;
    if (s == "boolean") return VK_BOOLEAN;
    if (s == "json") return VK_JSON;
    if (s == "struct") return VK_STRUCT;
    if (s == "quoted") return VK_QUOTED;
    if (s == "timestamp") return VK_TIMESTAMP;
    if (s == "any") return VK_ANY;
    return VK_STRING;
}

log_level_t log_format::level_from_capture(const std::string& cap, bool* matched) const
{
    if (matched) *matched = false;
    if (level_patterns.empty()) {
        auto lvl = string2level(cap, false);
        if (matched) *matched = (lvl != LEVEL_UNKNOWN);
        return lvl;
    }
    for (const auto& lp : level_patterns) {
        if (lp.is_int) {
            char* endp = nullptr;
            long long v = strtoll(cap.c_str(), &endp, 10);
            if (endp && *endp == '\0' && !cap.empty() && v == lp.int_value) { if (matched) *matched = true; return lp.level; }
        } else if (lp.re && lp.re->test(cap)) {
            if (matched) *matched = true;
            return lp.level;
        }
    }
    return LEVEL_INFO;
}

void log_format::finalize()
{
    ts_format_ptrs.clear();
    for (auto& f : ts_formats) ts_format_ptrs.push_back(f.c_str());
    ts_format_ptrs.push_back(nullptr);
    value_index.clear();
    for (size_t k = 0; k < values.size(); k++) {
        values[k].column_index = (int) k;
        value_index[values[k].name] = (int) k;
    }
}

