std::string value_kind_name(value_kind_t k)
{
    switch (k) {
    case VK_NULL: return "null";
    case VK_STRING: return "string";
    case VK_INTEGER: return "integer";
    case VK_FLOAT: return "float";
    case VK_BOOLEAN: return "boolean";
