static void set_value_from_capture(log_value& lv, const value_def& vd, const std::string& text)
{
    lv.name = vd.name;
    lv.kind = vd.kind;
    lv.is_null = false;
    lv.str = text;
    switch (vd.kind) {
    case VK_INTEGER: {
        char* endp = nullptr;
        errno = 0;
        long long v = strtoll(text.c_str(), &endp, 10);
        if (endp && *endp == '\0' && !text.empty() && errno == 0) { lv.ival = v; }
        else { lv.kind = VK_STRING; }
        break;
    }
    case VK_FLOAT: {
        char* endp = nullptr;
        double v = strtod(text.c_str(), &endp);
        if (endp && *endp == '\0' && !text.empty()) { lv.dval = v; }
        else { lv.kind = VK_STRING; }
        break;
    }
    case VK_BOOLEAN:
        lv.ival = (text == "true" || text == "1" || text == "yes");
        break;
    default:
        break;
    }
}

scan_result external_log_format::scan(const std::string& line, size_t line_number, bool first_line)
{
    (void) line_number; (void) first_line;
    scan_result res;
    if (is_json) {
        json::Value obj;
        if (!parse_json_line(line, obj)) return res;
        return scan_json(line, obj);
    }
    std::vector<int> order;
    if (pattern_lock >= 0) order.push_back(pattern_lock);
    for (size_t k = 0; k < patterns.size(); k++) if ((int) k != pattern_lock) order.push_back((int) k);
    for (int pi : order) {
        auto& pat = patterns[pi];
        if (pat.module_format) continue;
        Regex::Match m;
        if (!pat.re->match(line, m)) continue;
        if (pat.ts_index < 0 || !m.has(pat.ts_index)) continue;
        size_t ts_start = m.start(pat.ts_index), ts_end = m.end(pat.ts_index);
        exttm tm;
        struct timeval tv {0, 0};
        const char* end = dts.scan(line.data() + ts_start, ts_end - ts_start, ts_fmt_array(), &tm, tv);
        if (!end) continue;
        res.matched = true;
        res.tv = tv;
        res.tm = tm;
        res.ts_zoned = (tm.et_flags & (exttm::ETF_Z_FOR_UTC)) != 0;
        res.ts_start = (int) ts_start;
        res.ts_end = (int) (end - line.data());
        res.pattern_index = pi;
        pattern_lock = pi;
        // level
        if (pat.level_index >= 0 && m.has(pat.level_index)) {
            res.level = level_from_capture(m.str(pat.level_index), nullptr);
        } else if (pat.level_index < 0 && level_field == "body" && pat.body_index >= 0 && m.has(pat.body_index)) {
            res.level = level_from_capture(m.str(pat.body_index), nullptr);
        } else {
            res.level = LEVEL_INFO;
        }
        if (pat.opid_index >= 0 && m.has(pat.opid_index)) res.opid = m.str(pat.opid_index);
        return res;
    }
    return res;
}

annotate_result external_log_format::annotate(const std::string& msg_text, int pattern_index)
{
    annotate_result ar;
    ar.values.resize(values.size());
    for (size_t k = 0; k < values.size(); k++) { ar.values[k].name = values[k].name; ar.values[k].kind = values[k].kind; }
    if (is_json) {
        json::Value obj;
        if (!parse_json_line(msg_text, obj)) { ar.body_null = true; return ar; }
        // flatten
        std::vector<std::pair<std::string, const json::Value*>> flat;
        std::function<void(const std::string&, const json::Value&)> walk = [&](const std::string& prefix, const json::Value& v) {
            for (auto& kv : *v.obj) {
                std::string path = prefix.empty() ? kv.first : prefix + "/" + kv.first;
                flat.emplace_back(path, &kv.second);
                if (kv.second.is_object()) {
                    // only descend if some value def refers to a sub-path
                    bool any = false;
                    std::string pfx = path + "/";
                    for (auto& vd : values) if (vd.name.compare(0, pfx.size(), pfx) == 0) { any = true; break; }
                    if (body_field.compare(0, pfx.size(), pfx) == 0 || ts_field.compare(0, pfx.size(), pfx) == 0 || level_field.compare(0, pfx.size(), pfx) == 0) any = true;
                    if (any) walk(path, kv.second);
                }
            }
        };
        if (obj.is_object()) walk("", obj);
        extra_fields_last.clear();
        for (auto& [path, val] : flat) {
            auto it = value_index.find(path);
            if (it != value_index.end()) {
                auto& lv = ar.values[it->second];
                lv.is_null = false;
                lv.from_json = true;
                if (val->is_string()) {
                    lv.str = val->s;
                    if (values[it->second].kind == VK_INTEGER || values[it->second].kind == VK_FLOAT) set_value_from_capture(lv, values[it->second], val->s);
                } else if (val->type == json::Value::Int) {
                    lv.ival = val->i; lv.dval = (double) val->i; lv.str = std::to_string(val->i);
                    if (lv.kind == VK_STRING) lv.kind = VK_INTEGER;
                    else if (lv.kind == VK_FLOAT) lv.dval = (double) val->i;
                } else if (val->type == json::Value::Double) {
                    lv.dval = val->d; lv.ival = (int64_t) val->d; lv.str = format_double(val->d);
                    if (lv.kind == VK_STRING || lv.kind == VK_INTEGER) lv.kind = VK_FLOAT;
                } else if (val->is_bool()) {
                    lv.ival = val->b ? 1 : 0; lv.str = val->b ? "true" : "false";
                    if (lv.kind == VK_STRING) lv.kind = VK_BOOLEAN;
                } else if (val->is_null()) {
                    lv.is_null = true;
                } else {
                    lv.str = json::to_string(*val);
                    lv.kind = VK_JSON;
                }
            }
            if (path == body_field) {
                ar.body = val->is_string() ? val->s : json::to_string(*val);
            }
        }
        if (ar.body.empty()) {
            auto* bv = obj.get(body_field);
            if (!bv) ar.body_null = true;
        }
        return ar;
    }
    if (pattern_index < 0 || (size_t) pattern_index >= patterns.size()) { ar.body_null = true; return ar; }
    auto& pat = patterns[pattern_index];
    Regex::Match m;
    if (!pat.re->match(msg_text, m)) { ar.body = msg_text; return ar; }
    for (size_t g = 1; g < pat.capture_names.size(); g++) {
        const std::string& cname = pat.capture_names[g];
        if (cname.empty()) continue;
        auto it = value_index.find(cname);
        if (it != value_index.end()) {
            if (m.has((int) g)) set_value_from_capture(ar.values[it->second], values[it->second], m.str((int) g));
        }
    }
    if (pat.body_index >= 0 && m.has(pat.body_index)) {
        ar.body = m.str(pat.body_index);
    } else if (pat.body_index >= 0) {
        ar.body_null = true;
    } else {
        ar.body_null = true;
    }
    if (pat.ts_index >= 0 && m.has(pat.ts_index)) { ar.ts_start = (int) m.start(pat.ts_index); ar.ts_end = (int) m.end(pat.ts_index); }
    if (pat.level_index >= 0 && m.has(pat.level_index)) { ar.level_start = (int) m.start(pat.level_index); ar.level_end = (int) m.end(pat.level_index); }
    if (pat.opid_index >= 0 && m.has(pat.opid_index)) ar.opid = m.str(pat.opid_index);
    if (pat.module_index >= 0 && m.has(pat.module_index)) ar.module = m.str(pat.module_index);
    auto grab = [&](const std::string& field, std::string& out, bool& has) {
        if (field.empty()) return;
        for (size_t g = 1; g < pat.capture_names.size(); g++) if (pat.capture_names[g] == field && m.has((int) g)) { out = m.str((int) g); has = true; }
    };
    grab(src_file_field, ar.src_file, ar.has_src_file);
    grab(src_line_field, ar.src_line, ar.has_src_line);
    grab(thread_id_field, ar.thread_id, ar.has_thread_id);
    return ar;
}

bool external_log_format::parse_json_line(const std::string& line, json::Value& out) const
{
    if (line.empty() || line[0] != '{') return false;
    try {
        json::Parser p(line.data(), line.size());
        out = p.parse_document();
    } catch (...) {
        return false;
    }
    return out.is_object();
}

scan_result external_log_format::scan_json(const std::string& line, const json::Value& obj)
{
    (void) line;
    scan_result res;
    // locate timestamp field (supports a/b paths)
    std::function<const json::Value*(const json::Value&, const std::string&)> lookup = [&](const json::Value& o, const std::string& path) -> const json::Value* {
        const json::Value* cur = &o;
        size_t start = 0;
        while (true) {
            size_t slash = path.find('/', start);
            std::string key = path.substr(start, slash == std::string::npos ? std::string::npos : slash - start);
            if (!cur->is_object()) return nullptr;
            cur = cur->get(key);
            if (!cur) return nullptr;
            if (slash == std::string::npos) return cur;
            start = slash + 1;
        }
    };
    const json::Value* tsv = lookup(obj, ts_field);
    if (!tsv) return res;
    exttm tm;
    struct timeval tv {0, 0};
    if (tsv->is_string()) {
        const char* end = dts.scan(tsv->s.data(), tsv->s.size(), ts_fmt_array(), &tm, tv);
        if (!end) return res;
    } else if (tsv->is_number()) {
        double d = tsv->num();
        if (ts_divisor > 1) d /= (double) ts_divisor;
        if (!ts_formats.empty()) {
            // formats like %s, %6, %9 given as strings of digits
            std::string s = tsv->type == json::Value::Int ? std::to_string(tsv->i) : format_double(tsv->d);
            const char* end = dts.scan(s.data(), s.size(), ts_fmt_array(), &tm, tv);
            if (!end) {
                tv.tv_sec = (time_t) d; tv.tv_usec = (suseconds_t) ((d - (double) tv.tv_sec) * 1000000.0 + 0.5);
            }
        } else {
            tv.tv_sec = (time_t) d;
            tv.tv_usec = (suseconds_t) ((d - (double) tv.tv_sec) * 1000000.0 + 0.5);
            if (tv.tv_usec >= 1000000) { tv.tv_sec++; tv.tv_usec -= 1000000; }
        }
        time_t t = tv.tv_sec;
        gmtime_r(&t, &tm.et_tm);
        tm.et_nsec = (int64_t) tv.tv_usec * 1000;
    } else {
        return res;
    }
    res.matched = true;
    res.tv = tv;
    res.tm = tm;
    res.pattern_index = 0;
    // level
    const json::Value* lv = lookup(obj, level_field);
    if (lv) {
        std::string ls = lv->is_string() ? lv->s : (lv->type == json::Value::Int ? std::to_string(lv->i) : json::to_string(*lv));
        res.level = level_from_capture(ls, nullptr);
    } else {
        res.level = LEVEL_INFO;
    }
    if (!opid_field.empty()) {
        const json::Value* ov = lookup(obj, opid_field);
        if (ov && ov->is_string()) res.opid = ov->s;
    }
    return res;
}

static std::string apply_text_transform(const std::string& s, const std::string& tt)
{
    if (tt == "uppercase") { std::string r = s; for (auto& c : r) c = (char) toupper((unsigned char) c); return r; }
    if (tt == "lowercase") { std::string r = s; for (auto& c : r) c = (char) tolower((unsigned char) c); return r; }
    if (tt == "capitalize") { std::string r = s; bool start = true; for (auto& c : r) { if (isalpha((unsigned char) c)) { c = start ? (char) toupper((unsigned char) c) : (char) tolower((unsigned char) c); start = false; } else start = true; } return r; }
    return s;
}

std::string external_log_format::render(const std::string& msg_text, int pattern_index, annotate_result* ar_in)
{
    (void) pattern_index;
    if (!is_json) return msg_text;
    json::Value obj;
    if (!parse_json_line(msg_text, obj)) return msg_text;
    annotate_result local;
    annotate_result& ar = ar_in ? *ar_in : local;
    if (!ar_in) ar = annotate(msg_text, pattern_index);

    std::function<const json::Value*(const json::Value&, const std::string&)> lookup = [&](const json::Value& o, const std::string& path) -> const json::Value* {
        const json::Value* cur = &o;
        size_t start = 0;
        while (true) {
            size_t slash = path.find('/', start);
            std::string key = path.substr(start, slash == std::string::npos ? std::string::npos : slash - start);
            if (!cur->is_object()) return nullptr;
            cur = cur->get(key);
            if (!cur) return nullptr;
            if (slash == std::string::npos) return cur;
            start = slash + 1;
        }
    };
    scan_result sr = scan_json(msg_text, obj);
    std::set<std::string> used;
    used.insert(ts_field);
    used.insert(level_field);
    used.insert(body_field);
    std::string out;
    auto value_to_string = [&](const json::Value& v) -> std::string {
        if (v.is_string()) return v.s;
        if (v.type == json::Value::Int) return std::to_string(v.i);
        if (v.type == json::Value::Double) return format_double(v.d);
        if (v.is_bool()) return v.b ? "true" : "false";
        if (v.is_null()) return "";
        return json::to_string(v);
    };
    for (auto& el : line_format) {
        if (el.is_literal) { out += el.literal; continue; }
        std::string val;
        bool present = true;
        if (el.field == "__timestamp__") {
            exttm tm = sr.tm;
            std::string fmt = !el.timestamp_format.empty() ? el.timestamp_format : (!ts_formats.empty() ? ts_formats[0] : "%Y-%m-%dT%H:%M:%S.%L%z");
            const json::Value* tsv = lookup(obj, ts_field);
            if (tsv && tsv->is_string() && el.timestamp_format.empty() && ts_formats.empty()) {
                val = tsv->s;
            } else {
                val = ftime_fmt(fmt.c_str(), tm);
            }
        } else if (el.field == "__level__") {
            val = level_name(sr.level);
        } else {
            used.insert(el.field);
            const json::Value* v = lookup(obj, el.field);
            if (!v || v->is_null()) {
                present = false;
                if (el.default_value) val = *el.default_value;
                else val = "-";
            } else {
                val = value_to_string(*v);
            }
        }
        val = apply_text_transform(val, el.text_transform);
        if (el.auto_width) {
            int w = utf8_width(val);
            auto& mw = auto_widths[el.field];
            if (w > mw) mw = w;
            if (w < mw) val.append(mw - w, ' ');
        }
        if (el.min_width > 0) {
            int w = utf8_width(val);
            if (w < el.min_width) {
                if (el.align == "right") val.insert(0, el.min_width - w, ' ');
                else val.append(el.min_width - w, ' ');
            }
        }
        if (el.max_width > 0) {
            int w = utf8_width(val);
            if (w > el.max_width) {
                if (el.overflow == "truncate") val = utf8_truncate(val, el.max_width);
                else if (el.overflow == "dot-dot") val = utf8_truncate(val, el.max_width - 2) + "..";
                else val = abbreviate_str(val, el.max_width);
            }
        }
        if (present && !val.empty()) out += el.prefix;
        out += val;
        if (present && !val.empty()) out += el.suffix;
        else if (!present && el.default_value && !el.default_value->empty()) { /* nothing */ }
    }
    // extra fields
    if (!hide_extra && obj.is_object()) {
        for (auto& kv : *obj.obj) {
            if (used.count(kv.first)) continue;
            const value_def* vd = find_value(kv.first);
            if (vd && vd->hidden) continue;
            // skip if sub-fields are used in line format
            bool sub_used = false;
            std::string pfx = kv.first + "/";
            for (auto& u : used) if (u.compare(0, pfx.size(), pfx) == 0) sub_used = true;
            if (sub_used && kv.second.is_object()) {
                for (auto& skv : *kv.second.obj) {
                    std::string path = pfx + skv.first;
                    if (used.count(path)) continue;
                    const value_def* svd = find_value(path);
                    if (svd && svd->hidden) continue;
                    out += "\n  " + path + ": " + value_to_string(skv.second);
                }
                continue;
            }
            out += "\n  " + kv.first + ": " + value_to_string(kv.second);
        }
    }
    return out;
}

