std::unique_ptr<log_format> generic_log_format::specialized() const
{
    auto copy = std::make_unique<generic_log_format>(*this);
    copy->dts.clear();
    copy->pattern_lock = -1;
    return copy;
}

static const Regex& generic_level_re()
{
    // level word followed by ':' '|' or whitespace; or bracketed followed by whitespace
    static Regex re("^\\s*(?:\\[(?<l1>(?i:error|err|warn(?:ing)?|info|debug|dbg|trace|trc))\\]\\s|(?<l2>(?i:error|err|warn(?:ing)?|info|debug|dbg|trace|trc))(?:[:|]|\\s))");
    return re;
}

static const Regex& generic_zone_re()
{
    static Regex re("^\\s*(?:(?:[A-Za-z]{3,4})+|[+-]\\d{2}:?\\d{2})(?=\\s|$)");
    return re;
}

struct generic_pattern {
    const char* pattern;
    int ts_group;
    int body_group;
    int level_group;
};

static const std::vector<std::pair<std::shared_ptr<Regex>, int>>& generic_patterns()
{
    static std::vector<std::pair<std::shared_ptr<Regex>, int>> pats = {
        {std::make_shared<Regex>("^(?:\\*\\*\\*\\s+)?(?<timestamp>@[0-9a-zA-Z]{16,24})(.*)"), 0},
        {std::make_shared<Regex>("^(?:\\*\\*\\*\\s+)?(?<timestamp>[\\w:,/\\.-]+) (.*)"), 1},
        {std::make_shared<Regex>("^(?:\\*\\*\\*\\s+)?(?<timestamp>[\\w: \\.,/-]+) (.*)"), 2},
        {std::make_shared<Regex>("^(?:\\*\\*\\*\\s+)?\\[(?<timestamp>[\\w: \\.,+/-]+)\\](.*)"), 3},
    };
    return pats;
}

static bool parse_tai64n(const std::string& ts, struct timeval& tv, exttm& tm)
{
    // @4000000063d1a5f1[0c18ff5c]
    if (ts.size() < 17 || ts[0] != '@') return false;
    uint64_t secs = 0;
    for (int k = 1; k < 17; k++) {
        char c = ts[k];
        int v;
        if (c >= '0' && c <= '9') v = c - '0'; else if (c >= 'a' && c <= 'f') v = c - 'a' + 10; else if (c >= 'A' && c <= 'F') v = c - 'A' + 10; else return false;
        secs = secs * 16 + v;
    }
    uint64_t nanos = 0;
    if (ts.size() >= 25) {
        for (int k = 17; k < 25; k++) {
            char c = ts[k];
            int v;
            if (c >= '0' && c <= '9') v = c - '0'; else if (c >= 'a' && c <= 'f') v = c - 'a' + 10; else if (c >= 'A' && c <= 'F') v = c - 'A' + 10; else return false;
            nanos = nanos * 16 + v;
        }
    }
    int64_t s = (int64_t) (secs - 0x4000000000000000ULL) - 10;
    tv.tv_sec = (time_t) s;
    tv.tv_usec = (suseconds_t) (nanos / 1000);
    time_t t = tv.tv_sec;
    gmtime_r(&t, &tm.et_tm);
    tm.et_nsec = (int64_t) nanos;
    return true;
}

bool generic_log_format::try_level_pattern(const std::string& line, size_t pos, scan_result& res, annotate_result* ar, bool& got_level)
{
    // pos: start of timestamp (after optional "*** ")
    exttm tm;
    struct timeval tv {0, 0};
    const char* end = dts.scan(line.data() + pos, line.size() - pos, nullptr, &tm, tv);
    if (!end) return false;
    size_t p = end - line.data();
    // optional zone-ish tokens
    Regex::Match zm;
    while (p < line.size() && generic_zone_re().match(line.data() + p, line.size() - p, zm)) {
        p += zm.end(0);
    }
    Regex::Match lm;
    if (!generic_level_re().match(line.data() + p, line.size() - p, lm)) return false;
    std::string lvl = lm.has(1) ? lm.str(1) : lm.str(2);
    res.matched = true;
    res.tv = tv;
    res.tm = tm;
    res.ts_start = (int) pos;
    res.ts_end = (int) (end - line.data());
    res.level = string2level(lvl, true);
    got_level = true;
    if (ar) {
        size_t bstart = p + lm.end(0);
        while (bstart < line.size() && isspace((unsigned char) line[bstart])) bstart++;
        ar->body = line.substr(bstart);
        ar->ts_start = res.ts_start; ar->ts_end = res.ts_end;
        int lg = lm.has(1) ? 1 : 2;
        ar->level_start = (int) (p + lm.start(lg)); ar->level_end = (int) (p + lm.end(lg));
    }
    return true;
}

scan_result generic_log_format::scan(const std::string& line, size_t line_number, bool first_line)
{
    (void) line_number; (void) first_line;
    scan_result res;
    size_t pos = 0;
    if (line.compare(0, 3, "***") == 0) {
        size_t q = 3;
        if (q < line.size() && isspace((unsigned char) line[q])) {
            while (q < line.size() && isspace((unsigned char) line[q])) q++;
            pos = q;
        }
    }
    // Pattern with explicit level
    bool got_level = false;
    if (pos < line.size() && line[pos] != '[') {
        scan_result r2;
        if (try_level_pattern(line, pos, r2, nullptr, got_level)) {
            r2.pattern_index = 100;
            return r2;
        }
    }
    auto& pats = generic_patterns();
    std::vector<int> order;
    if (pattern_lock >= 0 && pattern_lock < (int) pats.size()) order.push_back(pattern_lock);
    for (size_t k = 0; k < pats.size(); k++) if ((int) k != pattern_lock) order.push_back((int) k);
    for (int pi : order) {
        auto& pat = *pats[pi].first;
        Regex::Match m;
        if (!pat.match(line, m)) continue;
        if (!m.has(1)) continue;
        std::string ts = m.str(1);
        exttm tm;
        struct timeval tv {0, 0};
        const char* end = nullptr;
        if (pi == 0) {
            if (!parse_tai64n(ts, tv, tm)) continue;
            end = line.data() + m.end(1);
        } else {
            end = dts.scan(line.data() + m.start(1), m.end(1) - m.start(1), nullptr, &tm, tv);
            if (!end) continue;
        }
        res.matched = true;
        res.tv = tv;
        res.tm = tm;
        res.ts_start = (int) m.start(1);
        res.ts_end = (int) (end - line.data());
        res.pattern_index = pi;
        pattern_lock = pi;
        // body: text after the timestamp capture
        std::string body = m.has(2) ? m.str(2) : "";
        if (pi != 0) {
            // trim leading whitespace
            size_t b = 0; while (b < body.size() && isspace((unsigned char) body[b])) b++;
            body = body.substr(b);
        }
        // level: either explicit word at start of body (bracketed form) or anywhere
        Regex::Match lm;
        static Regex body_level_re("^\\[?(?<lvl>\\w+)\\]?:?(?:\\s|$)");
        if (pi == 3 || pi == 2) {
            if (body_level_re.match(body, lm)) {
                auto lvl = string2level(lm.str(1), true);
                if (lvl != LEVEL_UNKNOWN) { res.level = lvl; return res; }
            }
        }
        res.level = string2level(body, false);
        return res;
    }
    return res;
}

annotate_result generic_log_format::annotate(const std::string& msg_text, int pattern_index)
{
    annotate_result ar;
    // first line only for parsing
    size_t nl = msg_text.find('\n');
    std::string line = nl == std::string::npos ? msg_text : msg_text.substr(0, nl);
    std::string rest = nl == std::string::npos ? "" : msg_text.substr(nl);
    size_t pos = 0;
    if (line.compare(0, 3, "***") == 0) {
        size_t q = 3;
        if (q < line.size() && isspace((unsigned char) line[q])) { while (q < line.size() && isspace((unsigned char) line[q])) q++; pos = q; }
    }
    if (pattern_index == 100) {
        scan_result r2; bool gl = false;
        if (try_level_pattern(line, pos, r2, &ar, gl)) { ar.body += rest; return ar; }
    }
    auto& pats = generic_patterns();
    int pi = pattern_index;
    if (pi < 0 || pi >= (int) pats.size()) {
        // find a matching one
        for (size_t k = 0; k < pats.size(); k++) { Regex::Match m; if (pats[k].first->match(line, m)) { pi = (int) k; break; } }
    }
    if (pi < 0 || pi >= (int) pats.size()) { ar.body = msg_text; return ar; }
    Regex::Match m;
    if (!pats[pi].first->match(line, m)) { ar.body = msg_text; return ar; }
    ar.ts_start = (int) m.start(1); ar.ts_end = (int) m.end(1);
    std::string body = m.has(2) ? m.str(2) : "";
    if (pi != 0) { size_t b = 0; while (b < body.size() && isspace((unsigned char) body[b])) b++; body = body.substr(b); }
    if (pi == 3 || pi == 2) {
        static Regex body_level_re("^\\[?(?<lvl>\\w+)\\]?:?(?:\\s+|$)");
        Regex::Match lm;
        if (body_level_re.match(body, lm)) {
            auto lvl = string2level(lm.str(1), true);
            if (lvl != LEVEL_UNKNOWN) body = body.substr(lm.end(0));
        }
    }
    ar.body = body + rest;
    return ar;
}

