// piper

piper_log_format::piper_log_format()
{
    name = "lnav_piper_log";
    title = "lnav piper log";
    internal = true;
    multiline = true;
}

std::unique_ptr<log_format> piper_log_format::specialized() const
{
    auto copy = std::make_unique<piper_log_format>(*this);
    copy->dts.clear();
    return copy;
}

static const Regex& piper_re()
{
    static Regex re("^(?<ts>\\S+)\\s+\\| (?<body>.*)");
    return re;
}

scan_result piper_log_format::scan(const std::string& line, size_t line_number, bool first_line)
{
    (void) line_number; (void) first_line;
    scan_result res;
    Regex::Match m;
    if (!piper_re().match(line, m)) return res;
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    res.matched = true;
    res.tv = tv;
    time_t t = tv.tv_sec;
    gmtime_r(&t, &res.tm.et_tm);
    res.tm.et_nsec = (int64_t) tv.tv_usec * 1000;
    res.level = LEVEL_INFO;
    res.pattern_index = 0;
    return res;
}

annotate_result piper_log_format::annotate(const std::string& msg_text, int pattern_index)
{
    (void) pattern_index;
    annotate_result ar;
    ar.body_null = true;
    (void) msg_text;
    return ar;
}

std::string piper_log_format::render(const std::string& msg_text, int pattern_index, annotate_result* ar)
{
    (void) pattern_index; (void) ar;
    Regex::Match m;
    size_t nl = msg_text.find('\n');
    std::string line = nl == std::string::npos ? msg_text : msg_text.substr(0, nl);
    if (!piper_re().match(line, m)) return msg_text;
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    exttm tm;
    time_t t = tv.tv_sec;
    gmtime_r(&t, &tm.et_tm);
    tm.et_nsec = (int64_t) tv.tv_usec * 1000;
    std::string out = ftime_fmt("%Y-%m-%dT%H:%M:%S.%f%z", tm) + " " + m.str(2);
    if (nl != std::string::npos) out += msg_text.substr(nl);
    return out;
}

