logfmt_log_format::logfmt_log_format()
{
    name = "logfmt_log";
    title = "logfmt";
    internal = true;
    multiline = false;
}

std::unique_ptr<log_format> logfmt_log_format::specialized() const
{
    auto copy = std::make_unique<logfmt_log_format>(*this);
    copy->dts.clear();
    return copy;
}

static bool parse_logfmt(const std::string& line, std::vector<std::pair<std::string, std::string>>& out)
{
    size_t p = 0, n = line.size();
    while (p < n) {
        while (p < n && line[p] == ' ') p++;
        if (p >= n) break;
        size_t ks = p;
        while (p < n && line[p] != '=' && line[p] != ' ') p++;
        if (p >= n || line[p] != '=') return false;
        std::string key = line.substr(ks, p - ks);
        if (key.empty()) return false;
        p++;
        std::string val;
        if (p < n && line[p] == '"') {
            p++;
            while (p < n && line[p] != '"') {
                if (line[p] == '\\' && p + 1 < n) { p++; }
                val += line[p]; p++;
            }
            if (p >= n) return false;
            p++;
        } else {
            size_t vs = p;
            while (p < n && line[p] != ' ') p++;
            val = line.substr(vs, p - vs);
        }
        out.emplace_back(key, val);
    }
    return !out.empty();
}

scan_result logfmt_log_format::scan(const std::string& line, size_t line_number, bool first_line)
{
    (void) line_number; (void) first_line;
    scan_result res;
    std::vector<std::pair<std::string, std::string>> kvs;
    if (!parse_logfmt(line, kvs)) return res;
    bool has_ts = false;
    for (auto& [k, v] : kvs) {
        if (k == "time" || k == "ts" || k == "timestamp" || k == "t") {
            exttm tm; struct timeval tv {0, 0};
            if (dts.scan(v.data(), v.size(), nullptr, &tm, tv)) { res.tv = tv; res.tm = tm; has_ts = true; }
        } else if (k == "level" || k == "lvl" || k == "severity") {
            res.level = string2level(v, true);
        }
    }
    if (!has_ts) return res;
    res.matched = true;
    res.pattern_index = 0;
    if (res.level == LEVEL_UNKNOWN) res.level = LEVEL_INFO;
    return res;
}

annotate_result logfmt_log_format::annotate(const std::string& msg_text, int pattern_index)
{
    (void) pattern_index;
    annotate_result ar;
    std::vector<std::pair<std::string, std::string>> kvs;
    if (parse_logfmt(msg_text, kvs)) {
        for (auto& [k, v] : kvs) if (k == "msg" || k == "message") ar.body = v;
    }
    if (ar.body.empty()) ar.body_null = true;
    return ar;
}

std::string logfmt_log_format::render(const std::string& msg_text, int pattern_index, annotate_result* ar)
{
    (void) pattern_index; (void) ar;
    return msg_text;
}

