format_registry& formats()
{
    static format_registry reg;
    return reg;
}

static int capture_index_by_name(const Regex& re, const std::string& name)
{
    return re.name_index(name);
}

void format_registry::load_json_text(const std::string& text, const std::string& path, bool builtin)
{
    json::Value doc;
    try {
        doc = json::parse(text);
    } catch (json::ParseError& e) {
        errors.push_back({path, std::string("invalid JSON: ") + e.what(), 0});
        return;
    }
    if (!doc.is_object()) return;
    static json::Value table_cols;
    static bool table_cols_loaded = false;
    if (!table_cols_loaded) {
        table_cols_loaded = true;
        try { table_cols = json::parse(embedded_table_columns()); } catch (...) {}
    }
    for (auto& kv : *doc.obj) {
        const std::string& fname = kv.first;
        if (fname == "$schema") continue;
        const json::Value& fv = kv.second;
        if (!fv.is_object()) continue;
        std::shared_ptr<external_log_format> fmt;
        auto existing = by_name.find(fname);
        bool is_new = true;
        if (existing != by_name.end()) {
            fmt = std::dynamic_pointer_cast<external_log_format>(existing->second);
            is_new = false;
            if (!fmt) continue;
        } else {
            fmt = std::make_shared<external_log_format>();
            fmt->name = fname;
            fmt->builtin = builtin;
        }
        fmt->raw_json = fv;
        if (auto* v = fv.get("title")) fmt->title = v->str_or("");
        if (auto* v = fv.get("description")) fmt->description = v->str_or("");
        if (auto* v = fv.get("url")) fmt->url = v->is_string() ? v->s : (v->is_array() && v->size() ? (*v)[0].str_or("") : "");
        if (auto* v = fv.get("file-type")) fmt->is_json = (v->str_or("") == "json");
        if (auto* v = fv.get("json")) fmt->is_json = fmt->is_json || v->bool_or(false);
        if (auto* v = fv.get("multiline")) fmt->multiline = v->bool_or(true);
        if (auto* v = fv.get("convert-to-local-time")) fmt->convert_to_local = v->bool_or(false);
        if (auto* v = fv.get("hide-extra")) fmt->hide_extra = v->bool_or(false);
        if (auto* v = fv.get("ordered-by-time")) fmt->ordered_by_time = v->bool_or(true);
        if (auto* v = fv.get("timestamp-divisor")) fmt->ts_divisor = v->int_or(1);
        if (auto* v = fv.get("max-unrecognized-lines")) fmt->max_unrecognized_lines = (int) v->int_or(1000);
        if (auto* v = fv.get("timestamp-field")) fmt->ts_field = v->str_or("timestamp");
        if (auto* v = fv.get("level-field")) fmt->level_field = v->str_or("level");
        if (auto* v = fv.get("body-field")) fmt->body_field = v->str_or("body");
        if (auto* v = fv.get("opid-field")) fmt->opid_field = v->str_or("");
        if (auto* v = fv.get("module-field")) fmt->module_field = v->str_or("");
        if (auto* v = fv.get("src-file-field")) fmt->src_file_field = v->str_or("");
        if (auto* v = fv.get("src-line-field")) fmt->src_line_field = v->str_or("");
        if (auto* v = fv.get("thread-id-field")) fmt->thread_id_field = v->str_or("");
        if (auto* v = fv.get("duration-field")) fmt->duration_field = v->str_or("");
        if (auto* v = fv.get("level-pointer")) {
            fmt->level_pointer = v->str_or("");
            try { fmt->level_pointer_re = std::make_shared<Regex>(fmt->level_pointer); } catch (...) {}
        }
        if (auto* v = fv.get("file-pattern")) {
            fmt->file_pattern = v->str_or("");
            try { fmt->file_pattern_re = std::make_shared<Regex>(fmt->file_pattern); } catch (...) {}
        }
        if (auto* v = fv.get("timestamp-format")) {
            fmt->ts_formats.clear();
            if (v->is_array()) for (size_t k = 0; k < v->size(); k++) fmt->ts_formats.push_back((*v)[k].str_or(""));
            else if (v->is_string()) fmt->ts_formats.push_back(v->s);
        }
        // values
        if (auto* v = fv.get("value")) {
            if (v->is_object()) {
                for (auto& vkv : *v->obj) {
                    value_def vd;
                    vd.name = vkv.first;
                    vd.user_defined = true;
                    const json::Value& vv = vkv.second;
                    if (auto* k = vv.get("kind")) vd.kind = kind_from_string(k->str_or("string"));
                    if (auto* k = vv.get("identifier")) vd.identifier = k->bool_or(false);
                    if (auto* k = vv.get("hidden")) vd.hidden = k->bool_or(false);
                    if (auto* k = vv.get("foreign-key")) vd.foreign_key = k->bool_or(false);
                    if (auto* k = vv.get("collate")) vd.collate = k->str_or("");
                    if (auto* k = vv.get("description")) vd.description = k->str_or("");
                    if (vd.identifier || vd.foreign_key) key_names.insert(vd.name);
                    bool found = false;
                    for (auto& ev : fmt->values) if (ev.name == vd.name) { ev = vd; found = true; }
                    if (!found) fmt->values.push_back(vd);
                }
            }
        }
        // patterns
        if (auto* v = fv.get("regex")) {
            if (v->is_object()) {
                for (auto& pkv : *v->obj) {
                    pattern_def pd;
                    pd.name = pkv.first;
                    const json::Value* pv = pkv.second.get("pattern");
                    if (!pv || !pv->is_string()) continue;
                    pd.regex_str = pv->s;
                    if (auto* mf = pkv.second.get("module-format")) pd.module_format = mf->bool_or(false);
                    try {
                        pd.re = std::make_shared<Regex>(pd.regex_str);
                    } catch (regex_error& e) {
                        errors.push_back({path, "invalid regex for " + fname + "/" + pd.name + ": " + e.what(), 0});
                        continue;
                    }
                    pd.capture_names = pd.re->names();
                    pd.ts_index = capture_index_by_name(*pd.re, fmt->ts_field);
                    pd.level_index = capture_index_by_name(*pd.re, fmt->level_field);
                    pd.body_index = capture_index_by_name(*pd.re, fmt->body_field);
                    if (!fmt->opid_field.empty()) pd.opid_index = capture_index_by_name(*pd.re, fmt->opid_field);
                    if (!fmt->module_field.empty()) pd.module_index = capture_index_by_name(*pd.re, fmt->module_field);
                    bool replaced = false;
                    for (auto& ep : fmt->patterns) if (ep.name == pd.name) { ep = pd; replaced = true; }
                    if (!replaced) fmt->patterns.push_back(pd);
                }
            }
        }
        // level patterns
        if (auto* v = fv.get("level")) {
            if (v->is_object()) {
                fmt->level_patterns.clear();
                for (auto& lkv : *v->obj) {
                    level_pattern lp;
                    lp.level = string2level(lkv.first, true);
                    if (lkv.second.is_number()) { lp.is_int = true; lp.int_value = lkv.second.int_or(0); }
                    else if (lkv.second.is_string()) {
                        try { lp.re = std::make_shared<Regex>(lkv.second.s); } catch (...) { continue; }
                    } else continue;
                    fmt->level_patterns.push_back(lp);
                }
            }
        }
        // line format
        if (auto* v = fv.get("line-format")) {
            if (v->is_array()) {
                fmt->line_format.clear();
                for (size_t k = 0; k < v->size(); k++) {
                    const json::Value& e = (*v)[k];
                    line_format_elem el;
                    if (e.is_string()) { el.is_literal = true; el.literal = e.s; }
                    else if (e.is_object()) {
                        if (auto* f = e.get("field")) el.field = f->str_or("");
                        if (auto* f = e.get("default-value")) el.default_value = f->is_string() ? f->s : json::to_string(*f);
                        if (auto* f = e.get("prefix")) el.prefix = f->str_or("");
                        if (auto* f = e.get("suffix")) el.suffix = f->str_or("");
                        if (auto* f = e.get("timestamp-format")) el.timestamp_format = f->str_or("");
                        if (auto* f = e.get("auto-width")) el.auto_width = f->bool_or(false);
                        if (auto* f = e.get("min-width")) el.min_width = (int) f->int_or(0);
                        if (auto* f = e.get("max-width")) el.max_width = (int) f->int_or(0);
                        if (auto* f = e.get("align")) el.align = f->str_or("");
                        if (auto* f = e.get("overflow")) el.overflow = f->str_or("");
                        if (auto* f = e.get("text-transform")) el.text_transform = f->str_or("");
                    } else continue;
                    fmt->line_format.push_back(el);
                }
            }
        }
        // Make sure the columns follow the known table layout when available
        {
            std::vector<value_def> ordered;
            const json::Value* tc = table_cols.get(fname);
            if (tc && tc->is_array()) {
                for (size_t k = 0; k < tc->size(); k++) {
                    const json::Value& c = (*tc)[k];
                    std::string cname = c[0].str_or("");
                    value_def vd;
                    bool found = false;
                    for (auto& ev : fmt->values) if (ev.name == cname) { vd = ev; found = true; break; }
                    if (!found) { vd.name = cname; vd.user_defined = true; }
                    std::string ctype = c[1].str_or("TEXT");
                    if (!found) {
                        if (ctype == "INTEGER") vd.kind = VK_INTEGER; else if (ctype == "FLOAT" || ctype == "REAL") vd.kind = VK_FLOAT; else if (ctype == "BOOLEAN") vd.kind = VK_BOOLEAN;
                    }
                    vd.collate = c[2].str_or("");
                    vd.hidden = vd.hidden || c[3].bool_or(false);
                    ordered.push_back(vd);
                }
                // keep non-column values after (hidden from table)
                for (auto& ev : fmt->values) {
                    bool present = false;
                    for (auto& o : ordered) if (o.name == ev.name) present = true;
                    if (!present) { value_def vd = ev; vd.column_index = -2; ordered.push_back(vd); }
                }
                fmt->values = ordered;
            } else {
                // alphabetical, excluding timestamp/body fields
                std::vector<value_def> cols;
                for (auto& ev : fmt->values) {
                    if (ev.name == fmt->ts_field || ev.name == fmt->body_field) continue;
                    cols.push_back(ev);
                }
                std::sort(cols.begin(), cols.end(), [](const value_def& a, const value_def& b) { return a.name < b.name; });
                fmt->values = cols;
            }
        }
        fmt->finalize();
        if (is_new) {
            by_name[fname] = fmt;
            root_formats.push_back(fmt);
        }
    }
}

void format_registry::load_file(const std::string& path, bool builtin)
{
    std::ifstream in(path);
    if (!in) { errors.push_back({path, "unable to open", 0}); return; }
    std::stringstream ss; ss << in.rdbuf();
    load_json_text(ss.str(), path, builtin);
}

void format_registry::load_directory(const std::string& dir, bool builtin)
{
    DIR* d = opendir(dir.c_str());
    if (!d) return;
    std::vector<std::string> names;
    while (auto* ent = readdir(d)) {
        std::string n = ent->d_name;
        if (n.size() > 5 && n.compare(n.size() - 5, 5, ".json") == 0) names.push_back(n);
    }
    closedir(d);
    std::sort(names.begin(), names.end());
    for (auto& n : names) load_file(dir + "/" + n, builtin);
}

void format_registry::load_builtin()
{
    const char* const* names = embedded_format_names();
    for (int k = 0; names[k]; k++) {
        load_json_text(embedded_format_text(names[k]), std::string(names[k]) + ".json", true);
    }
    // internal formats
    auto piper = std::make_shared<piper_log_format>();
    auto logfmt = std::make_shared<logfmt_log_format>();
    auto generic = std::make_shared<generic_log_format>();
    // piper and logfmt go after the builtin json ones that start with earlier letters
    by_name[piper->name] = piper;
    by_name[logfmt->name] = logfmt;
    by_name[generic->name] = generic;
    // insert internal formats in alphabetical position among root formats
    auto insert_sorted = [&](std::shared_ptr<log_format> f) {
        auto it = root_formats.begin();
        while (it != root_formats.end() && (*it)->name < f->name) ++it;
        root_formats.insert(it, f);
    };
    insert_sorted(piper);
    insert_sorted(logfmt);
    root_formats.push_back(generic);
    static const char* builtin_keys[] = {"enabled", "filter_id", "filtering", "inode", "key", "log_level", "log_line", "log_mark", "pattern", "paused", "rowid", "st_dev", "st_gid", "st_ino", "st_mode", "st_rdev", "st_uid", "device", "capture_index", "capture_count", "range_start", "range_stop", "match_index", "log_time_msecs", nullptr};
    for (int k = 0; builtin_keys[k]; k++) key_names.insert(builtin_keys[k]);
}

std::vector<std::string> format_registry::sorted_names() const
{
    std::vector<std::string> out;
    for (auto& kv : by_name) out.push_back(kv.first);
    std::sort(out.begin(), out.end(), [](const std::string& a, const std::string& b) { return strcasecmp(a.c_str(), b.c_str()) < 0; });
    return out;
}
