std::string format_double(double d)
{
    if (std::isnan(d)) return "nan";
    if (std::isinf(d)) return d < 0 ? "-inf" : "inf";
    return fmt::format("{}", d);
}

namespace json { std::string format_double(double d) { return ::format_double(d); } }

static int cp_width(uint32_t cp)
{
    if (cp == 0) return 0;
    if (cp < 0x20 || (cp >= 0x7f && cp < 0xa0)) return 1;
    // combining marks
    if ((cp >= 0x0300 && cp <= 0x036f) || (cp >= 0x200b && cp <= 0x200f) || cp == 0xfe0f) return 0;
    // wide ranges (rough)
    if ((cp >= 0x1100 && cp <= 0x115f) || (cp >= 0x2e80 && cp <= 0xa4cf && cp != 0x303f) || (cp >= 0xac00 && cp <= 0xd7a3) ||
        (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0xfe30 && cp <= 0xfe4f) || (cp >= 0xff00 && cp <= 0xff60) || (cp >= 0xffe0 && cp <= 0xffe6) ||
        (cp >= 0x1f300 && cp <= 0x1f64f) || (cp >= 0x1f900 && cp <= 0x1f9ff) || (cp >= 0x20000 && cp <= 0x3fffd))
        return 2;
    return 1;
}

static bool decode_utf8(const std::string& s, size_t& i, uint32_t& cp)
{
    unsigned char c = (unsigned char) s[i];
    if (c < 0x80) { cp = c; i += 1; return true; }
    int n = 0;
    if ((c & 0xE0) == 0xC0) { n = 1; cp = c & 0x1F; }
    else if ((c & 0xF0) == 0xE0) { n = 2; cp = c & 0x0F; }
    else if ((c & 0xF8) == 0xF0) { n = 3; cp = c & 0x07; }
    else { cp = c; i += 1; return false; }
    if (i + n >= s.size() + 0 && i + n > s.size() - 0) { }
    if (i + n > s.size() - 0 && i + n > s.size()) { cp = c; i += 1; return false; }
    for (int k = 1; k <= n; k++) {
        if (i + k >= s.size()) { cp = c; i += 1; return false; }
        unsigned char cc = (unsigned char) s[i + k];
        if ((cc & 0xC0) != 0x80) { cp = c; i += 1; return false; }
        cp = (cp << 6) | (cc & 0x3F);
    }
    i += n + 1;
    return true;
}

int utf8_width(const std::string& s)
{
    int w = 0;
    size_t i = 0;
    while (i < s.size()) {
        uint32_t cp;
        decode_utf8(s, i, cp);
        w += cp_width(cp);
    }
    return w;
}

size_t utf8_length(const std::string& s)
{
    size_t n = 0, i = 0;
    while (i < s.size()) { uint32_t cp; decode_utf8(s, i, cp); n++; }
    return n;
}

std::string utf8_truncate(const std::string& s, size_t max_chars)
{
    size_t n = 0, i = 0;
    while (i < s.size() && n < max_chars) { uint32_t cp; decode_utf8(s, i, cp); n++; }
    return s.substr(0, i);
}

static size_t utf8_offset_of_char(const std::string& s, size_t char_index)
{
    size_t n = 0, i = 0;
    while (i < s.size() && n < char_index) { uint32_t cp; decode_utf8(s, i, cp); n++; }
    return i;
}

std::string truncate_middle(const std::string& s, size_t max_chars)
{
    size_t len = utf8_length(s);
    if (len <= max_chars) return s;
    size_t chars_to_remove = len - max_chars + 1;
    size_t midpoint = len / 2;
    size_t front = midpoint - chars_to_remove / 2;
    size_t remove_start = utf8_offset_of_char(s, front);
    size_t remove_end = utf8_offset_of_char(s, front + chars_to_remove);
    return s.substr(0, remove_start) + "\xe2\x8b\xaf" + s.substr(remove_end);
}

std::string abbreviate_str(const std::string& s, size_t max_chars)
{
    return truncate_middle(s, max_chars);
}

std::string ltrim(const std::string& s) { size_t b = 0; while (b < s.size() && isspace((unsigned char) s[b])) b++; return s.substr(b); }
std::string rtrim(const std::string& s) { size_t e = s.size(); while (e > 0 && isspace((unsigned char) s[e - 1])) e--; return s.substr(0, e); }
std::string trim(const std::string& s) { return ltrim(rtrim(s)); }

std::vector<std::string> split(const std::string& s, char sep)
{
    std::vector<std::string> out;
    size_t start = 0;
    while (true) {
        size_t p = s.find(sep, start);
        if (p == std::string::npos) { out.push_back(s.substr(start)); break; }
        out.push_back(s.substr(start, p - start));
        start = p + 1;
    }
    return out;
}

std::vector<std::string> split_ws(const std::string& s)
{
    std::vector<std::string> out;
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace((unsigned char) s[i])) i++;
        if (i >= s.size()) break;
        size_t b = i;
        while (i < s.size() && !isspace((unsigned char) s[i])) i++;
        out.push_back(s.substr(b, i - b));
    }
    return out;
}

bool starts_with(const std::string& s, const std::string& p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool ends_with(const std::string& s, const std::string& p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }
std::string to_lower(const std::string& s) { std::string r = s; for (auto& c : r) c = (char) tolower((unsigned char) c); return r; }
std::string to_upper(const std::string& s) { std::string r = s; for (auto& c : r) c = (char) toupper((unsigned char) c); return r; }

std::string replace_all(const std::string& s, const std::string& from, const std::string& to)
{
    if (from.empty()) return s;
    std::string out;
    size_t start = 0;
    while (true) {
        size_t p = s.find(from, start);
        if (p == std::string::npos) { out += s.substr(start); break; }
        out += s.substr(start, p - start);
        out += to;
        start = p + from.size();
    }
    return out;
}

std::string humanize_file_size(int64_t v)
{
    static const char* units[] = {"B", "K", "M", "G", "T", "P", "E"};
    if (v < 0) v = -v;
    double d = (double) v;
    int u = 0;
    while (d >= 1024.0 && u < 6) { d /= 1024.0; u++; }
    char buf[64];
    if (u == 0) snprintf(buf, sizeof(buf), "%lldB", (long long) v);
    else snprintf(buf, sizeof(buf), "%.1f%s", d, units[u]);
    return buf;
}

std::string humanize_duration(double secs)
{
    bool neg = secs < 0;
    if (neg) secs = -secs;
    int64_t total = (int64_t) secs;
    int64_t days = total / 86400; total %= 86400;
    int64_t hours = total / 3600; total %= 3600;
    int64_t mins = total / 60; total %= 60;
    std::string out;
    if (neg) out += "-";
    if (days > 0) out += std::to_string(days) + "d";
    if (hours > 0) out += std::to_string(hours) + "h";
    if (mins > 0) out += std::to_string(mins) + "m";
    if (total > 0 || out.empty() || out == "-") out += std::to_string(total) + "s";
    return out;
}

std::string basename_of(const std::string& path)
{
    if (path.empty()) return "";
    size_t end = path.size();
    while (end > 1 && path[end - 1] == '/') end--;
    size_t p = path.rfind('/', end - 1);
    if (p == std::string::npos) return path.substr(0, end);
    if (end == 1 && path[0] == '/') return "/";
    return path.substr(p + 1, end - p - 1);
}

std::string dirname_of(const std::string& path)
{
    if (path.empty()) return ".";
    size_t end = path.size();
    while (end > 1 && path[end - 1] == '/') end--;
    size_t p = path.rfind('/', end - 1);
    if (p == std::string::npos) return ".";
    if (p == 0) return "/";
    return path.substr(0, p);
}

std::string scrub_control_chars(const std::string& s)
{
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        switch (c) {
        case '\n': out += "\xe2\x90\x8a"; break;   // ␊
        case '\t': out += "\xe2\x87\xa5"; break;   // ⇥
        case '\r': out += "\xe2\x90\x8d"; break;   // ␍
        default: out += c;
        }
    }
    return out;
}

std::string pad_center(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    int total = width - w;
    int left = total / 2;
    int right = total - left;
    return std::string(left, ' ') + s + std::string(right, ' ');
}

std::string pad_left(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    return std::string(width - w, ' ') + s;
}

std::string pad_right(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    return s + std::string(width - w, ' ');
}

std::string read_file(const std::string& path, bool& ok)
{
    std::ifstream in(path, std::ios::binary);
    if (!in) { ok = false; return ""; }
    std::stringstream ss; ss << in.rdbuf();
    ok = true;
    return ss.str();
}

std::string shell_quote(const std::string& s)
{
    std::string out = "'";
    for (char c : s) { if (c == '\'') out += "'\\''"; else out += c; }
    out += "'";
    return out;
}

std::string json_escape(const std::string& s)
{
    std::string out;
    out += '"';
    for (unsigned char c : s) {
        switch (c) {
        case '"': out += "\\\""; break;
        case '\\': out += "\\\\"; break;
        case '\n': out += "\\n"; break;
        case '\r': out += "\\r"; break;
        case '\t': out += "\\t"; break;
        default:
            if (c < 0x20) { char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c); out += buf; }
            else out += (char) c;
        }
    }
    out += '"';
    return out;
}
