std::string rtrim(const std::string& s) { size_t e = s.size(); while (e > 0 && isspace((unsigned char) s[e - 1])) e--; return s.substr(0, e); }
std::string trim(const std::string& s) { return ltrim(rtrim(s)); }

std::vector<std::string> split(const std::string& s, char sep)
{
    std::vector<std::string> out;
    size_t start = 0;
    while (true) {
        size_t p = s.find(sep, start);
        if (p == std::string::npos) { out.push_back(s.substr(start)); break; }
        out.push_back(s.substr(start, p - start));
        start = p + 1;
    }
    return out;
}

std::vector<std::string> split_ws(const std::string& s)
{
    std::vector<std::string> out;
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace((unsigned char) s[i])) i++;
        if (i >= s.size()) break;
        size_t b = i;
        while (i < s.size() && !isspace((unsigned char) s[i])) i++;
        out.push_back(s.substr(b, i - b));
    }
    return out;
}

bool starts_with(const std::string& s, const std::string& p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool ends_with(const std::string& s, const std::string& p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }
std::string to_lower(const std::string& s) { std::string r = s; for (auto& c : r) c = (char) tolower((unsigned char) c); return r; }
std::string to_upper(const std::string& s) { std::string r = s; for (auto& c : r) c = (char) toupper((unsigned char) c); return r; }

std::string replace_all(const std::string& s, const std::string& from, const std::string& to)
{
    if (from.empty()) return s;
    std::string out;
    size_t start = 0;
    while (true) {
        size_t p = s.find(from, start);
        if (p == std::string::npos) { out += s.substr(start); break; }
        out += s.substr(start, p - start);
        out += to;
        start = p + from.size();
    }
    return out;
}

std::string humanize_file_size(int64_t v)
{
    static const char* units[] = {"B", "K", "M", "G", "T", "P", "E"};
    if (v < 0) v = -v;
    double d = (double) v;
    int u = 0;
    while (d >= 1024.0 && u < 6) { d /= 1024.0; u++; }
    char buf[64];
    if (u == 0) snprintf(buf, sizeof(buf), "%lldB", (long long) v);
    else snprintf(buf, sizeof(buf), "%.1f%s", d, units[u]);
    return buf;
}

std::string humanize_duration(double secs)
{
    bool neg = secs < 0;
    if (neg) secs = -secs;
    int64_t total = (int64_t) secs;
    int64_t days = total / 86400; total %= 86400;
    int64_t hours = total / 3600; total %= 3600;
    int64_t mins = total / 60; total %= 60;
    std::string out;
    if (neg) out += "-";
    if (days > 0) out += std::to_string(days) + "d";
    if (hours > 0) out += std::to_string(hours) + "h";
    if (mins > 0) out += std::to_string(mins) + "m";
    if (total > 0 || out.empty() || out == "-") out += std::to_string(total) + "s";
    return out;
}

std::string basename_of(const std::string& path)
{
    if (path.empty()) return "";
    size_t end = path.size();
    while (end > 1 && path[end - 1] == '/') end--;
    size_t p = path.rfind('/', end - 1);
    if (p == std::string::npos) return path.substr(0, end);
    if (end == 1 && path[0] == '/') return "/";
    return path.substr(p + 1, end - p - 1);
}

std::string dirname_of(const std::string& path)
{
    if (path.empty()) return ".";
    size_t end = path.size();
    while (end > 1 && path[end - 1] == '/') end--;
    size_t p = path.rfind('/', end - 1);
    if (p == std::string::npos) return ".";
    if (p == 0) return "/";
    return path.substr(0, p);
}

std::string scrub_control_chars(const std::string& s)
{
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        switch (c) {
        case '\n': out += "\xe2\x90\x8a"; break;   // ␊
        case '\t': out += "\xe2\x87\xa5"; break;   // ⇥
        case '\r': out += "\xe2\x90\x8d"; break;   // ␍
        default: out += c;
        }
    }
    return out;
}

std::string pad_center(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    int total = width - w;
    int left = total / 2;
    int right = total - left;
    return std::string(left, ' ') + s + std::string(right, ' ');
}

std::string pad_left(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    return std::string(width - w, ' ') + s;
}

std::string pad_right(const std::string& s, int width)
{
    int w = utf8_width(s);
    if (w >= width) return s;
    return s + std::string(width - w, ' ');
}

std::string read_file(const std::string& path, bool& ok)
{
    std::ifstream in(path, std::ios::binary);
    if (!in) { ok = false; return ""; }
    std::stringstream ss; ss << in.rdbuf();
    ok = true;
    return ss.str();
}

std::string shell_quote(const std::string& s)
{
    std::string out = "'";
    for (char c : s) { if (c == '\'') out += "'\\''"; else out += c; }
    out += "'";
    return out;
}

std::string json_escape(const std::string& s)
{
    std::string out;
    out += '"';
    for (unsigned char c : s) {
        switch (c) {
        case '"': out += "\\\""; break;
        case '\\': out += "\\\\"; break;
        case '\n': out += "\\n"; break;
        case '\r': out += "\\r"; break;
        case '\t': out += "\\t"; break;
        default:
            if (c < 0x20) { char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c); out += buf; }
            else out += (char) c;
        }
    }
    out += '"';
    return out;
}
