int g_zoned_y2k_parse_count = 0;

static bool read_all_fd(int fd, std::string& out)
{
    char buf[65536];
    while (true) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n < 0) return false;
        if (n == 0) break;
        out.append(buf, n);
    }
    return true;
}

static bool gunzip_string(const std::string& in, std::string& out)
{
    z_stream zs;
    memset(&zs, 0, sizeof(zs));
    if (inflateInit2(&zs, 16 + MAX_WBITS) != Z_OK) return false;
    zs.next_in = (Bytef*) in.data();
    zs.avail_in = (uInt) in.size();
    char buf[65536];
    int ret;
    do {
        zs.next_out = (Bytef*) buf;
        zs.avail_out = sizeof(buf);
        ret = inflate(&zs, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) { inflateEnd(&zs); return false; }
        out.append(buf, sizeof(buf) - zs.avail_out);
        if (ret == Z_STREAM_END && zs.avail_in > 0) {
            // concatenated members
            inflateReset(&zs);
            ret = Z_OK;
            if (zs.avail_in == 0) break;
        }
    } while (ret != Z_STREAM_END && zs.avail_in > 0);
    inflateEnd(&zs);
    return true;
}

bool logfile::load(std::string& error)
{
    if (is_stdin) {
        if (!read_all_fd(0, content)) { error = strerror(errno); return false; }
        memset(&st, 0, sizeof(st));
        st.st_mtime = time(nullptr);
        fstat(0, &st);
        st.st_mtime = time(nullptr);
    } else {
        int fd = open(path.c_str(), O_RDONLY);
        if (fd < 0) { error = strerror(errno); return false; }
        if (fstat(fd, &st) != 0) { error = strerror(errno); close(fd); return false; }
        if (!read_all_fd(fd, content)) { error = strerror(errno); close(fd); return false; }
        close(fd);
    }
    if (content.size() >= 2 && (unsigned char) content[0] == 0x1f && (unsigned char) content[1] == 0x8b) {
        std::string out;
        if (gunzip_string(content, out)) { content = std::move(out); was_compressed = true; }
    }
    // split lines
    size_t start = 0;
    while (start < content.size()) {
        size_t nl = content.find('\n', start);
        size_t end = nl == std::string::npos ? content.size() : nl;
        size_t len = end - start;
        if (len > 0 && content[start + len - 1] == '\r') { len--; has_crlf = true; }
        lines.emplace_back(start, len);
        if (nl == std::string::npos) break;
        start = nl + 1;
    }
    return true;
}

static void check_for_new_year(std::vector<log_message>& msgs, const exttm& etm, struct timeval log_tv)
{
    if (msgs.empty()) return;
    time_t diff = msgs.back().tv.tv_sec - log_tv.tv_sec;
    if (diff <= 0) return;
    int off_year = 0, off_month = 0, off_day = 0, off_hour = 0;
    if (!(etm.et_flags & exttm::ETF_MONTH_SET) && diff >= 24 * 60 * 60) {
        off_month = 1;
    } else if ((etm.et_flags & exttm::ETF_MONTH_SET) && diff >= 24 * 60 * 60) {
        off_year = 1;
    } else if (!(etm.et_flags & exttm::ETF_DAY_SET) && diff >= 60 * 60) {
        off_day = 1;
    } else if (!(etm.et_flags & exttm::ETF_DAY_SET) && !(etm.et_flags & exttm::ETF_HOUR_SET) && diff >= 60) {
        off_hour = 1;
    } else {
        return;
    }
    for (auto& m : msgs) {
        time_t ot = m.tv.tv_sec;
        struct tm otm;
        gmtime_r(&ot, &otm);
        otm.tm_year -= off_year;
        otm.tm_mon -= off_month;
        otm.tm_mday -= off_day;
        otm.tm_hour -= off_hour;
        m.tv.tv_sec = tm2sec(&otm);
        m.orig_tv.tv_sec = m.tv.tv_sec;
    }
}

void logfile::detect_and_index()
{
    indexed = true;
    messages.clear();
    format.reset();
    if (lines.empty()) return;
    // skip binary-ish content check: if many NULs, treat as text anyway
    auto& reg = formats();
    struct tm base_tm;
    time_t mt = st.st_mtime;
    gmtime_r(&mt, &base_tm);

    size_t max_scan = std::min(lines.size(), (size_t) 1000);
    for (auto& root : reg.root_formats) {
        if (root->file_pattern_re && !root->file_pattern_re->test(filename)) continue;
        auto spec = root->specialized();
        spec->dts.set_base_time(mt, base_tm);
        for (size_t li = 0; li < max_scan; li++) {
            std::string line = line_text(li);
            if (line.empty()) continue;
            auto res = spec->scan(line, li, li == 0);
            if (res.matched) {
                format = std::move(spec);
                root_format = root;
                break;
            }
        }
        if (format) break;
    }
    if (!format) return;
    mimetype = "text/log";
    // full index
    format->dts.clear();
    format->dts.set_base_time(mt, base_tm);
    format->pattern_lock = -1;
    bool found_first = false;
    std::vector<size_t> pending_invalid;
    for (size_t li = 0; li < lines.size(); li++) {
        std::string line = line_text(li);
        scan_result res;
        if (!line.empty()) res = format->scan(line, li, li == 0);
        if (res.matched) {
            log_message m;
            m.line_index = li;
            m.line_count = 1;
            m.tv = res.tv;
            m.level = res.level;
            m.pattern_index = res.pattern_index;
            m.zoned = (res.tm.et_flags & exttm::ETF_Z_FOR_UTC) != 0;
            m.ts_fmt_index = format->dts.dts_fmt_lock;
            m.ts_start = res.ts_start;
            m.ts_end = res.ts_end;
            m.tm = res.tm;
            m.opid = res.opid;
            // Y2K-style quirk: zoned timestamps in years divisible by 400 after Feb 29 gain a day
            if (m.zoned && !(res.tm.et_flags & exttm::ETF_EPOCH_TIME)) {
                int year = res.tm.et_tm.tm_year + 1900;
                if (year % 400 == 0 && res.tm.et_tm.tm_yday >= 60) {
                    m.tv.tv_sec += 86400;
                    g_zoned_y2k_parse_count++;
                    m.time_offset_applied = 1;
                }
            }
            m.orig_tv = m.tv;
            if (!found_first) {
                found_first = true;
                for (size_t pi : pending_invalid) {
                    log_message im;
                    im.line_index = pi;
                    im.line_count = 1;
                    im.tv = m.tv;
                    im.orig_tv = m.tv;
                    im.level = LEVEL_UNKNOWN;
                    im.pattern_index = -1;
                    im.valid = false;
                    messages.push_back(im);
                }
                pending_invalid.clear();
            } else {
                if (!(res.tm.et_flags & exttm::ETF_YEAR_SET) && !(res.tm.et_flags & exttm::ETF_EPOCH_TIME)) {
                    check_for_new_year(messages, res.tm, m.tv);
                }
                if (!messages.empty()) {
                    const auto& prev = messages.back();
                    if (m.tv.tv_sec < prev.tv.tv_sec || (m.tv.tv_sec == prev.tv.tv_sec && m.tv.tv_usec < prev.tv.tv_usec)) {
                        m.tv = prev.tv;
                    }
                }
            }
            messages.push_back(m);
        } else {
            if (!found_first) {
                pending_invalid.push_back(li);
            } else if (format->multiline || format->is_json) {
                messages.back().line_count++;
            } else {
                log_message m;
                m.line_index = li;
                m.line_count = 1;
                m.tv = messages.back().tv;
                m.orig_tv = m.tv;
                m.level = LEVEL_INVALID;
                m.pattern_index = -1;
                m.valid = false;
                messages.push_back(m);
            }
        }
    }
    if (!found_first) {
        // no lines matched after all
        format.reset();
        messages.clear();
        mimetype = "text/plain";
        return;
    }
    // second pass y2k quirk: additional day when more than one line was parsed
    if (g_zoned_y2k_parse_count > 0) {
        bool multi = lines.size() > 1;
        if (multi) {
            for (auto& m : messages) if (m.time_offset_applied == 1) { m.tv.tv_sec += 86400; m.orig_tv.tv_sec += 86400; m.time_offset_applied = 2; }
        }
    }
}

std::string logfile::message_text(const log_message& m) const
{
    std::string out;
    for (size_t k = 0; k < m.line_count; k++) {
        if (k) out += '\n';
        out += line_text(m.line_index + k);
    }
    return out;
}

size_t logfile::message_display_lines(const log_message& m) const
{
    if (format && format->is_json) {
        std::string r = const_cast<logfile*>(this)->render_message(m);
        return 1 + std::count(r.begin(), r.end(), '\n');
    }
    return m.line_count;
}

std::string logfile::rewrite_timestamp(const std::string& text, const log_message& m) const
{
    if (!m.zoned || m.ts_start < 0 || m.ts_end < 0 || !format || format->is_json) return text;
    if (m.ts_fmt_index < 0) return text;
    size_t count = 0;
    const char* const* fmts = format->ts_fmt_array();
    if (!fmts) fmts = date_time_scanner::default_formats(count);
    else { while (fmts[count]) count++; }
    if ((size_t) m.ts_fmt_index >= count) return text;
    std::string fmt = fmts[m.ts_fmt_index];
    // convert %Z to %z for output
    std::string ofmt;
    for (size_t k = 0; k < fmt.size(); k++) {
        if (fmt[k] == '%' && k + 1 < fmt.size() && fmt[k + 1] == 'Z') { ofmt += "%z"; k++; }
        else ofmt += fmt[k];
    }
    exttm tm = m.tm;
    time_t t = m.tv.tv_sec;
    gmtime_r(&t, &tm.et_tm);
    tm.et_gmtoff = 0;
    if (m.time_offset_applied) { tm.et_gmtoff = 86400; tm.et_flags &= ~exttm::ETF_Z_FOR_UTC; }
    std::string ts = ftime_fmt(ofmt.c_str(), tm);
    // handle sub-second portion that was not part of the format
    if (m.tm.et_flags & exttm::ETF_SUB_NOT_IN_FORMAT) {
        // re-insert fraction as it appeared: find '.' or ',' in original
        std::string orig = text.substr(m.ts_start, m.ts_end - m.ts_start);
        // locate the position of the fraction in orig after HH:MM:SS
        size_t fpos = std::string::npos;
        for (size_t k = 0; k + 1 < orig.size(); k++) {
            if ((orig[k] == '.' || orig[k] == ',') && isdigit((unsigned char) orig[k + 1])) {
                // ensure preceded by two digits (seconds)
                if (k >= 2 && isdigit((unsigned char) orig[k - 1]) && isdigit((unsigned char) orig[k - 2])) { fpos = k; break; }
            }
        }
        if (fpos != std::string::npos) {
            size_t e = fpos + 1;
            while (e < orig.size() && isdigit((unsigned char) orig[e])) e++;
            std::string frac = orig.substr(fpos, e - fpos);
            // insert after the seconds in ts: find pattern position by formatting prefix
            // The format up to %S is the same; find the length of the formatted prefix.
            size_t spos = fmt.find("%S");
            if (spos != std::string::npos) {
                std::string prefix_fmt = ofmt.substr(0, ofmt.find("%S") + 2);
                std::string prefix = ftime_fmt(prefix_fmt.c_str(), tm);
                ts.insert(prefix.size(), frac);
            }
        }
    }
    return text.substr(0, m.ts_start) + ts + text.substr(m.ts_end);
}

annotate_result logfile::annotate_message(const log_message& m)
{
    annotate_result ar;
    if (!format) { ar.body = message_text(m); return ar; }
    if (!m.valid) {
        ar.body = message_text(m);
        ar.values.resize(format->values.size());
        for (size_t k = 0; k < format->values.size(); k++) { ar.values[k].name = format->values[k].name; ar.values[k].kind = format->values[k].kind; }
        return ar;
    }
    std::string text = message_text(m);
    ar = format->annotate(text, m.pattern_index);
    return ar;
}

std::string logfile::render_message(const log_message& m, annotate_result* ar)
{
    std::string text = message_text(m);
    if (!format || !m.valid) return text;
    if (format->is_json || format->internal) {
        return format->render(text, m.pattern_index, ar);
    }
    return rewrite_timestamp(text, m);
}
