static void collect_dir(const std::string& dir, bool recursive, std::vector<std::string>& out)
{
    DIR* d = opendir(dir.c_str());
    if (!d) return;
    std::vector<std::string> names;
    while (auto* ent = readdir(d)) {
        std::string n = ent->d_name;
        if (n == "." || n == "..") continue;
        if (!n.empty() && n[0] == '.') continue;
        names.push_back(n);
    }
    closedir(d);
    std::sort(names.begin(), names.end());
    for (auto& n : names) {
        std::string full = dir + "/" + n;
        struct stat st;
        if (stat(full.c_str(), &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) {
            if (recursive) collect_dir(full, recursive, out);
        } else if (S_ISREG(st.st_mode)) {
            out.push_back(full);
        }
    }
}

bool lnav_app::load_files(app_error& err)
{
    std::vector<std::string> paths;
    bool use_stdin = false;
    if (opts.files.empty()) {
        if (!isatty(0)) use_stdin = true;
    }
    for (auto& f : opts.files) {
        if (f == "-") { use_stdin = true; continue; }
        struct stat st;
        if (stat(f.c_str(), &st) == 0) {
            if (S_ISDIR(st.st_mode)) {
                collect_dir(f, opts.recursive, paths);
            } else {
                paths.push_back(f);
            }
            continue;
        }
        // glob
        glob_t g;
        memset(&g, 0, sizeof(g));
        int rc = glob(f.c_str(), GLOB_NOCHECK, nullptr, &g);
        bool matched = false;
        if (rc == 0) {
            for (size_t k = 0; k < g.gl_pathc; k++) {
                std::string p = g.gl_pathv[k];
                struct stat st2;
                if (stat(p.c_str(), &st2) == 0) {
                    matched = true;
                    if (S_ISDIR(st2.st_mode)) collect_dir(p, opts.recursive, paths);
                    else paths.push_back(p);
                }
            }
        }
        globfree(&g);
        if (!matched) {
            bool is_glob = f.find_first_of("*?[") != std::string::npos;
            err.msg = "unable to open file: " + f;
            if (is_glob) {
                err.reason = "failed to find path of \xe2\x80\x9c" + f + "\xe2\x80\x9d\n|        reason: " + std::string(strerror(ENOENT));
            } else {
                err.reason = strerror(errno == 0 ? ENOENT : errno);
            }
            err.exit_code = 1;
            return false;
        }
    }
    for (auto& p : paths) {
        auto lf = std::make_unique<logfile>();
        lf->path = p;
        lf->filename = p;
        std::string e;
        if (!lf->load(e)) {
            err.msg = "unable to open file: " + p;
            err.reason = e;
            err.exit_code = 1;
            return false;
        }
        files.push_back(std::move(lf));
    }
    if (use_stdin) {
        auto lf = std::make_unique<logfile>();
        lf->is_stdin = true;
        lf->path = "stdin";
        lf->filename = "stdin";
        std::string e;
        if (lf->load(e)) files.push_back(std::move(lf));
    }
    for (auto& lf : files) lf->detect_and_index();
    rebuild_log_view();
    return true;
}

struct merge_iter {
    int file_idx;
    size_t msg_idx;
    struct timeval tv;
};

void lnav_app::rebuild_log_view()
{
    log_entries.clear();
    std::vector<merge_iter> heap;
    for (size_t fi = 0; fi < files.size(); fi++) {
        auto& lf = files[fi];
        if (lf->is_text() || lf->messages.empty() || !lf->visible) continue;
        heap.push_back({(int) fi, 0, lf->messages[0].tv});
    }
    auto cmp = [](const merge_iter& a, const merge_iter& b) {
        if (a.tv.tv_sec != b.tv.tv_sec) return a.tv.tv_sec > b.tv.tv_sec;
        return a.tv.tv_usec > b.tv.tv_usec;
    };
    std::make_heap(heap.begin(), heap.end(), cmp);
    while (!heap.empty()) {
        std::pop_heap(heap.begin(), heap.end(), cmp);
        merge_iter cur = heap.back();
        heap.pop_back();
        view_entry ve;
        ve.file_idx = cur.file_idx;
        ve.msg_idx = (int) cur.msg_idx;
        ve.row_start = 0;
        ve.row_count = 1;
        log_entries.push_back(ve);
        auto& lf = files[cur.file_idx];
        if (cur.msg_idx + 1 < lf->messages.size()) {
            cur.msg_idx++;
            cur.tv = lf->messages[cur.msg_idx].tv;
            heap.push_back(cur);
            std::push_heap(heap.begin(), heap.end(), cmp);
        }
    }
    apply_filters();
}

std::string lnav_app::message_display_text(int file_idx, int msg_idx)
{
    auto& lf = files[file_idx];
    return lf->render_message(lf->messages[msg_idx]);
}

bool lnav_app::message_passes_filters(int file_idx, int msg_idx, const std::vector<text_filter>& filters, bool& filtered_out)
{
    filtered_out = false;
    auto& lf = files[file_idx];
    auto& m = lf->messages[msg_idx];
    if (min_level != LEVEL_UNKNOWN && m.level < min_level && m.valid) { filtered_out = true; return false; }
    if (hide_unmarked && !m.marked) { filtered_out = true; return false; }
    bool has_in = false;
    bool in_matched = false;
    std::string text;
    bool text_ready = false;
    for (auto& f : filters) {
        if (!f.enabled || f.lang != "regex" || !f.re) continue;
        if (!text_ready) { text = message_display_text(file_idx, msg_idx); text_ready = true; }
        Regex::Match mm;
        bool hit = f.re->match(text, mm);
        if (f.out) {
            if (hit) { filtered_out = true; return false; }
        } else {
            has_in = true;
            if (hit) in_matched = true;
        }
    }
    if (has_in && !in_matched) { filtered_out = true; return false; }
    return true;
}

void lnav_app::apply_filters()
{
    log_visible.clear();
    size_t row = 0;
    for (auto& ve : log_entries) {
        bool fo = false;
        if (!message_passes_filters(ve.file_idx, ve.msg_idx, log_filters, fo)) continue;
        view_entry v = ve;
        v.row_start = row;
        auto& lf = files[ve.file_idx];
        std::string txt = lf->render_message(lf->messages[ve.msg_idx]);
        v.row_count = 1 + std::count(txt.begin(), txt.end(), '\n');
        row += v.row_count;
        log_visible.push_back(v);
    }
}

const view_entry* lnav_app::entry_for_row(size_t row, size_t* line_in_msg) const
{
    // binary search
    size_t lo = 0, hi = log_visible.size();
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        const auto& e = log_visible[mid];
        if (row < e.row_start) hi = mid;
        else if (row >= e.row_start + e.row_count) lo = mid + 1;
        else { if (line_in_msg) *line_in_msg = row - e.row_start; return &e; }
    }
    return nullptr;
}

bool lnav_app::has_text() const
{
    for (auto& lf : files) if (lf->is_text() && !lf->lines.empty()) return true;
    return false;
}

std::string lnav_app::render_log_view()
{
    std::string out;
    for (auto& ve : log_visible) {
        auto& lf = files[ve.file_idx];
        out += lf->render_message(lf->messages[ve.msg_idx]);
        out += '\n';
    }
    return out;
}

std::vector<std::string> lnav_app::text_view_lines()
{
    std::vector<std::string> out;
    for (auto& lf : files) {
        if (!lf->is_text() || !lf->visible) continue;
        for (size_t k = 0; k < lf->lines.size(); k++) {
            std::string l = lf->line_text(k);
            bool skip = false;
            for (auto& f : text_filters) {
                if (!f.enabled || !f.re) continue;
                Regex::Match mm;
                bool hit = f.re->match(l, mm);
                if (f.out && hit) skip = true;
            }
            bool has_in = false, in_hit = false;
            for (auto& f : text_filters) {
                if (!f.enabled || !f.re || f.out) continue;
                has_in = true;
                Regex::Match mm;
                if (f.re->match(l, mm)) in_hit = true;
            }
            if (has_in && !in_hit) skip = true;
            if (skip) continue;
            out.push_back(l);
        }
    }
    return out;
}

std::string lnav_app::render_text_view()
{
    std::string out;
    for (auto& l : text_view_lines()) { out += l; out += '\n'; }
    return out;
}
