static std::string compute_content_id(const logfile& lf)
{
    // a stable-ish hash of the beginning of the file
    uint64_t h1 = 1469598103934665603ULL, h2 = 0x9e3779b97f4a7c15ULL;
    size_t n = std::min(lf.content.size(), (size_t) 4096);
    for (size_t k = 0; k < n; k++) { h1 ^= (unsigned char) lf.content[k]; h1 *= 1099511628211ULL; h2 = (h2 ^ (unsigned char) lf.content[k]) * 0x100000001b3ULL + k; }
    char buf[64];
    snprintf(buf, sizeof(buf), "v1:%016llx%016llx", (unsigned long long) h1, (unsigned long long) h2);
    return buf;
}

static std::string mimetype_for(const logfile& lf)
{
    if (lf.lines.empty() || lf.content.empty()) return "application/octet-stream";
    if (lf.format) return "text/log";
    return lf.mimetype;
}

static void create_misc_tables(lnav_app& app, sqlite3* db)
{
    lnav_app* ap = &app;
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_file";
        def->create_sql = "CREATE TABLE lnav_file (device integer, inode integer, filepath text, mimetype text, content_id text, format text, lines integer, time_offset integer, options_path TEXT, options TEXT, content BLOB HIDDEN)";
        def->columns = parse_cols_from_create(def->create_sql);
