            std::vector<std::string> order;
            for (auto& ve : ap->log_visible) {
                auto& lf = ap->files[ve.file_idx];
                auto& msg = lf->messages[ve.msg_idx];
                if (msg.opid.empty()) continue;
                auto it = m.find(msg.opid);
                if (it == m.end()) { st s; s.first = msg.tv; s.last = msg.tv; m[msg.opid] = s; order.push_back(msg.opid); it = m.find(msg.opid); }
                it->second.last = msg.tv;
                it->second.total++;
                if (msg.level >= LEVEL_ERROR) it->second.errors++;
                else if (msg.level == LEVEL_WARNING) it->second.warnings++;
            }
            std::sort(order.begin(), order.end());
            int64_t id = 0;
            for (auto& k : order) {
                auto& s = m[k];
                int64_t dur = ((int64_t) s.last.tv_sec - s.first.tv_sec) * 1000000 + (s.last.tv_usec - s.first.tv_usec);
                rows.push_back({sql_value::text(k), sql_value::text(format_log_time(s.first)), sql_value::text(format_log_time(s.last)), sql_value::integer(dur), sql_value::integer(s.errors), sql_value::integer(s.warnings), sql_value::integer(s.total), sql_value::null(), sql_value::null()});
