// collations
static int collate_loglevel(void*, int l1, const void* s1, int l2, const void* s2)
{
    auto a = string2level((const char*) s1, l1, true);
    auto b = string2level((const char*) s2, l2, true);
    return (int) a - (int) b;
}

static int natural_compare(const char* a, int la, const char* b, int lb, bool nocase)
{
    int i = 0, j = 0;
    while (i < la && j < lb) {
        if (isdigit((unsigned char) a[i]) && isdigit((unsigned char) b[j])) {
            // compare numbers
            int si = i, sj = j;
            while (i < la && isdigit((unsigned char) a[i])) i++;
            while (j < lb && isdigit((unsigned char) b[j])) j++;
            // strip leading zeros
            int zi = si, zj = sj;
            while (zi < i - 1 && a[zi] == '0') zi++;
            while (zj < j - 1 && b[zj] == '0') zj++;
            int ni = i - zi, nj = j - zj;
            if (ni != nj) return ni - nj;
            int c = memcmp(a + zi, b + zj, ni);
            if (c) return c;
            continue;
        }
        char ca = a[i], cb = b[j];
        if (nocase) { ca = (char) tolower((unsigned char) ca); cb = (char) tolower((unsigned char) cb); }
        if (ca != cb) return (unsigned char) ca - (unsigned char) cb;
        i++; j++;
    }
    return (la - i) - (lb - j);
}
static int collate_naturalcase(void*, int l1, const void* s1, int l2, const void* s2) { return natural_compare((const char*) s1, l1, (const char*) s2, l2, false); }
static int collate_naturalnocase(void*, int l1, const void* s1, int l2, const void* s2) { return natural_compare((const char*) s1, l1, (const char*) s2, l2, true); }
static int collate_ipaddress(void*, int l1, const void* s1, int l2, const void* s2)
{
    std::string a((const char*) s1, l1), b((const char*) s2, l2);
    unsigned ia[4], ib[4];
    bool va = sscanf(a.c_str(), "%u.%u.%u.%u", &ia[0], &ia[1], &ia[2], &ia[3]) == 4;
    bool vb = sscanf(b.c_str(), "%u.%u.%u.%u", &ib[0], &ib[1], &ib[2], &ib[3]) == 4;
    if (va && vb) {
        for (int k = 0; k < 4; k++) if (ia[k] != ib[k]) return (int) ia[k] - (int) ib[k];
        return 0;
    }
    if (va != vb) return va ? -1 : 1;
    return natural_compare(a.data(), l1, b.data(), l2, true);
}

void sql_init(lnav_app& app)
{
    sqlite3* db = nullptr;
    sqlite3_open(":memory:", &db);
    app.db = db;
    sqlite3_create_collation(db, "loglevel", SQLITE_UTF8, nullptr, collate_loglevel);
    sqlite3_create_collation(db, "naturalcase", SQLITE_UTF8, nullptr, collate_naturalcase);
    sqlite3_create_collation(db, "naturalnocase", SQLITE_UTF8, nullptr, collate_naturalnocase);
    sqlite3_create_collation(db, "ipaddress", SQLITE_UTF8, nullptr, collate_ipaddress);
    register_sql_functions(app, db);
    create_misc_tables(app, db);
    sqlite3_exec(db, STATIC_SCHEMA, nullptr, nullptr, nullptr);
    for (auto& hc : HTTP_CODES) {
        char* sql = sqlite3_mprintf("INSERT INTO http_status_codes VALUES (%d, %Q)", hc.code, hc.msg);
        sqlite3_exec(db, sql, nullptr, nullptr, nullptr);
        sqlite3_free(sql);
    }
    // log tables
    for (auto& fmt : formats().root_formats) {
        create_log_table(app, db, fmt, false);
    }
    create_log_table(app, db, nullptr, true);
}

void sql_refresh_tables(lnav_app&) {}

// ---------------------------------------------------------------------------
// Execution

static std::string type_name(int t)
{
    switch (t) { case SQLITE_INTEGER: return "integer"; case SQLITE_FLOAT: return "float"; case SQLITE_TEXT: return "text"; case SQLITE_BLOB: return "blob"; default: return "null"; }
}

static void bind_env_vars(lnav_app& app, sqlite3_stmt* stmt)
{
    int n = sqlite3_bind_parameter_count(stmt);
    for (int k = 1; k <= n; k++) {
        const char* name = sqlite3_bind_parameter_name(stmt, k);
        if (!name) continue;
        std::string nm = name;
        if (nm.size() > 1 && nm[0] == '$') {
            const char* v = getenv(nm.c_str() + 1);
            if (v) sqlite3_bind_text(stmt, k, v, -1, SQLITE_TRANSIENT);
            else sqlite3_bind_null(stmt, k);
        } else if (nm.size() > 1 && nm[0] == ':') {
            std::string var = nm.substr(1);
            // bind log columns of the top line
            bool bound = false;
            if (!app.log_visible.empty()) {
                size_t top = std::min(app.log_top, app.log_row_count() - 1);
                const view_entry* ve = app.entry_for_row(top);
                if (ve) {
                    auto& lf = app.files[ve->file_idx];
                    auto& m = lf->messages[ve->msg_idx];
                    if (var == "log_line") { sqlite3_bind_int64(stmt, k, (int64_t) ve->row_start); bound = true; }
                    else if (var == "log_time") { auto s = format_log_time(m.tv); sqlite3_bind_text(stmt, k, s.c_str(), -1, SQLITE_TRANSIENT); bound = true; }
                    else if (var == "log_level") { sqlite3_bind_text(stmt, k, level_name(m.level), -1, SQLITE_TRANSIENT); bound = true; }
                    else if (var == "log_format") { sqlite3_bind_text(stmt, k, lf->format->name.c_str(), -1, SQLITE_TRANSIENT); bound = true; }
                    else if (var == "log_path") { sqlite3_bind_text(stmt, k, lf->path.c_str(), -1, SQLITE_TRANSIENT); bound = true; }
                    else if (var == "log_text" || var == "log_raw_text") { auto s = lf->message_text(m); sqlite3_bind_text(stmt, k, s.c_str(), -1, SQLITE_TRANSIENT); bound = true; }
                    else if (var == "log_body") { auto ar = lf->annotate_message(m); if (ar.body_null) sqlite3_bind_null(stmt, k); else sqlite3_bind_text(stmt, k, ar.body.c_str(), -1, SQLITE_TRANSIENT); bound = true; }
                    else {
                        auto ar = lf->annotate_message(m);
                        for (auto& lv : ar.values) {
                            if (lv.name == var) {
                                if (lv.is_null) sqlite3_bind_null(stmt, k);
                                else if (lv.kind == VK_INTEGER) sqlite3_bind_int64(stmt, k, lv.ival);
                                else if (lv.kind == VK_FLOAT) sqlite3_bind_double(stmt, k, lv.dval);
                                else sqlite3_bind_text(stmt, k, lv.str.c_str(), -1, SQLITE_TRANSIENT);
                                bound = true;
                            }
                        }
                    }
                }
            }
            if (!bound) sqlite3_bind_null(stmt, k);
        }
    }
}

bool sql_execute(lnav_app& app, const std::string& sql_in, app_error& err, bool capture)
{
    std::string sql = trim(sql_in);
    if (sql.empty()) return true;
    if (sql == ".schema") {
        if (capture) {
            fputs(embedded_schema_text(), stdout);
            app.produced_output = true;
        }
        return true;
    }
    if (!sql.empty() && sql[0] == '.') {
        err.msg = "unknown sqlite command: " + sql;
        return false;
    }
    sqlite3* db = app.db;
    const char* tail = sql.c_str();
    bool any_rows_result = false;
    app.last_result = lnav_app::db_result();
    while (tail && *tail) {
        sqlite3_stmt* stmt = nullptr;
        const char* next = nullptr;
        int rc = sqlite3_prepare_v2(db, tail, -1, &stmt, &next);
        if (rc != SQLITE_OK) {
            err.msg = "failed to compile SQL statement";
            err.reason = sqlite3_errmsg(db);
            return false;
        }
        if (!stmt) { tail = next; continue; }
        bind_env_vars(app, stmt);
        int ncols = sqlite3_column_count(stmt);
        lnav_app::db_result res;
        for (int c = 0; c < ncols; c++) {
            const char* nm = sqlite3_column_name(stmt, c);
            res.headers.push_back(nm ? nm : "");
        }
        res.header_types.assign(ncols, SQLITE_NULL);
        bool first = true;
        while (true) {
            rc = sqlite3_step(stmt);
            if (rc == SQLITE_ROW) {
                std::vector<std::string> row; std::vector<int> types; std::vector<double> nums; std::vector<int64_t> ints;
                for (int c = 0; c < ncols; c++) {
                    int t = sqlite3_column_type(stmt, c);
                    types.push_back(t);
                    if (first) res.header_types[c] = t;
                    switch (t) {
                    case SQLITE_INTEGER: { int64_t v = sqlite3_column_int64(stmt, c); row.push_back(std::to_string(v)); nums.push_back((double) v); ints.push_back(v); break; }
                    case SQLITE_FLOAT: { double v = sqlite3_column_double(stmt, c); row.push_back(format_double(v)); nums.push_back(v); ints.push_back((int64_t) v); break; }
                    case SQLITE_TEXT: { const unsigned char* s = sqlite3_column_text(stmt, c); int n = sqlite3_column_bytes(stmt, c); row.push_back(std::string((const char*) s, n)); nums.push_back(0); ints.push_back(0); break; }
                    case SQLITE_BLOB: { const void* s = sqlite3_column_blob(stmt, c); int n = sqlite3_column_bytes(stmt, c); row.push_back(std::string((const char*) s, n)); nums.push_back(0); ints.push_back(0); break; }
                    default: row.push_back(""); nums.push_back(0); ints.push_back(0); break;
                    }
                }
                res.rows.push_back(row); res.row_types.push_back(types); res.row_nums.push_back(nums); res.row_ints.push_back(ints);
                first = false;
            } else if (rc == SQLITE_DONE) {
                break;
            } else {
                err.msg = "failed to execute SQL statement";
                err.reason = sqlite3_errmsg(db);
                sqlite3_finalize(stmt);
                return false;
            }
        }
        sqlite3_finalize(stmt);
        if (ncols > 0) {
            res.valid = true;
            app.last_result = res;
            any_rows_result = true;
        } else {
            app.last_result = lnav_app::db_result();
        }
        tail = next;
        while (tail && *tail && isspace((unsigned char) *tail)) tail++;
    }
    (void) any_rows_result;
    (void) capture;
    return true;
}

// ---------------------------------------------------------------------------
// Rendering

static bool looks_numeric_text(const std::string& s)
{
    size_t i = 0;
    if (i >= s.size() || !isdigit((unsigned char) s[i])) return false;
    while (i < s.size() && isdigit((unsigned char) s[i])) i++;
    if (i < s.size() && s[i] == '.') {
        i++;
        size_t ds = i;
        while (i < s.size() && isdigit((unsigned char) s[i])) i++;
        if (i == ds) return false;
    }
    while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r' || s[i] == '\v' || s[i] == '\f')) i++;
    return i == s.size();
}

std::string render_db_result(lnav_app& app)
{
    auto& r = app.last_result;
    if (!r.valid) return "";
    size_t ncols = r.headers.size();
    std::vector<size_t> widths(ncols, 0);
    std::vector<bool> right_align(ncols, false);
    std::vector<std::vector<std::string>> cells(r.rows.size(), std::vector<std::string>(ncols));
    const size_t MAX_W = 120;
    for (size_t c = 0; c < ncols; c++) {
        std::string hdr = truncate_middle(r.headers[c], MAX_W);
        widths[c] = utf8_width(hdr);
        bool graphable = false;
        if (!r.rows.empty()) {
            int t = r.row_types[0][c];
            if (t == SQLITE_INTEGER || t == SQLITE_FLOAT) graphable = true;
            else if (t == SQLITE_TEXT && looks_numeric_text(r.rows[0][c])) graphable = true;
            if (graphable && formats().key_names.count(r.headers[c])) graphable = false;
        }
        if (graphable && widths[c] < 10) widths[c] = 10;
        for (size_t ri = 0; ri < r.rows.size(); ri++) {
            int t = r.row_types[ri][c];
            std::string cell;
            if (t == SQLITE_NULL) cell = "<NULL>";
            else if (t == SQLITE_BLOB) cell = r.rows[ri][c];
            else cell = scrub_control_chars(r.rows[ri][c]);
            cell = truncate_middle(cell, MAX_W);
            if (t == SQLITE_INTEGER || t == SQLITE_FLOAT) right_align[c] = true;
            else if (t == SQLITE_TEXT && !r.rows[ri][c].empty() && isdigit((unsigned char) r.rows[ri][c][0])) right_align[c] = true;
            size_t w = utf8_width(cell);
            if (w > widths[c]) widths[c] = w;
            cells[ri][c] = cell;
        }
    }
    std::string out;
    for (size_t c = 0; c < ncols; c++) {
        out += pad_center(truncate_middle(r.headers[c], MAX_W), (int) widths[c]);
        out += ' ';
    }
    out += '\n';
    for (size_t ri = 0; ri < r.rows.size(); ri++) {
        for (size_t c = 0; c < ncols; c++) {
            if (right_align[c]) out += pad_left(cells[ri][c], (int) widths[c]);
            else out += pad_right(cells[ri][c], (int) widths[c]);
            out += ' ';
        }
        out += '\n';
    }
    return out;
}
