// ---------------------------------------------------------------------------
// Generic snapshot-based virtual table

struct vtab_def;

struct vtab_table {
    sqlite3_vtab base;
    vtab_def* def;
};

struct vtab_cursor {
    sqlite3_vtab_cursor base;
    std::vector<std::vector<sql_value>> rows;
    std::vector<int64_t> rowids;
    size_t pos = 0;
};

struct vtab_def {
    std::string name;
    std::string create_sql;
    std::vector<std::string> columns;
    std::function<void(std::vector<std::vector<sql_value>>&, std::vector<int64_t>&)> fill;
    std::function<int(sqlite3_vtab*, int argc, sqlite3_value** argv, sqlite3_int64* rowid)> update;  // optional
};

static std::map<std::string, std::unique_ptr<vtab_def>> g_vtabs;

static void set_result(sqlite3_context* ctx, const sql_value& v)
{
    switch (v.type) {
    case sql_value::Null: sqlite3_result_null(ctx); break;
    case sql_value::Int: sqlite3_result_int64(ctx, v.i); break;
    case sql_value::Float: sqlite3_result_double(ctx, v.d); break;
    case sql_value::Text: sqlite3_result_text(ctx, v.s.data(), (int) v.s.size(), SQLITE_TRANSIENT); break;
    case sql_value::Blob: sqlite3_result_blob(ctx, v.s.data(), (int) v.s.size(), SQLITE_TRANSIENT); break;
    }
}

static int vt_connect(sqlite3* db, void* aux, int, const char* const*, sqlite3_vtab** pp, char** err)
{
    (void) err;
    auto* def = (vtab_def*) aux;
    int rc = sqlite3_declare_vtab(db, def->create_sql.c_str());
    if (rc != SQLITE_OK) { *err = sqlite3_mprintf("%s", sqlite3_errmsg(db)); return rc; }
    auto* t = new vtab_table();
    memset(&t->base, 0, sizeof(t->base));
    t->def = def;
    *pp = &t->base;
    return SQLITE_OK;
}
static int vt_disconnect(sqlite3_vtab* v) { delete (vtab_table*) v; return SQLITE_OK; }
static int vt_best_index(sqlite3_vtab*, sqlite3_index_info* info)
{
    info->estimatedCost = 1000.0;
    // support rowid equality cheaply
    for (int k = 0; k < info->nConstraint; k++) {
        auto& c = info->aConstraint[k];
        if (c.usable && c.iColumn == -1 && c.op == SQLITE_INDEX_CONSTRAINT_EQ) {
            info->aConstraintUsage[k].argvIndex = 1;
            info->idxNum = 1;
            info->estimatedCost = 1.0;
            break;
        }
    }
    return SQLITE_OK;
}
static int vt_open(sqlite3_vtab*, sqlite3_vtab_cursor** pp)
{
    auto* c = new vtab_cursor();
    memset(&c->base, 0, sizeof(c->base));
    *pp = &c->base;
    return SQLITE_OK;
}
static int vt_close(sqlite3_vtab_cursor* c) { delete (vtab_cursor*) c; return SQLITE_OK; }
static int vt_filter(sqlite3_vtab_cursor* pc, int idxNum, const char*, int argc, sqlite3_value** argv)
{
    auto* c = (vtab_cursor*) pc;
    auto* t = (vtab_table*) pc->pVtab;
    c->rows.clear(); c->rowids.clear(); c->pos = 0;
    t->def->fill(c->rows, c->rowids);
    if (idxNum == 1 && argc >= 1) {
        int64_t want = sqlite3_value_int64(argv[0]);
        std::vector<std::vector<sql_value>> rows; std::vector<int64_t> ids;
        for (size_t k = 0; k < c->rows.size(); k++) if (c->rowids[k] == want) { rows.push_back(c->rows[k]); ids.push_back(c->rowids[k]); }
        c->rows = rows; c->rowids = ids;
    }
    return SQLITE_OK;
}
static int vt_next(sqlite3_vtab_cursor* pc) { ((vtab_cursor*) pc)->pos++; return SQLITE_OK; }
static int vt_eof(sqlite3_vtab_cursor* pc) { auto* c = (vtab_cursor*) pc; return c->pos >= c->rows.size(); }
static int vt_column(sqlite3_vtab_cursor* pc, sqlite3_context* ctx, int col)
{
    auto* c = (vtab_cursor*) pc;
    auto& row = c->rows[c->pos];
    if (col < 0 || (size_t) col >= row.size()) { sqlite3_result_null(ctx); return SQLITE_OK; }
    set_result(ctx, row[col]);
    return SQLITE_OK;
}
static int vt_rowid(sqlite3_vtab_cursor* pc, sqlite3_int64* out) { auto* c = (vtab_cursor*) pc; *out = c->rowids[c->pos]; return SQLITE_OK; }
static int vt_update(sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64* rowid)
{
    auto* t = (vtab_table*) v;
    if (!t->def->update) { v->zErrMsg = sqlite3_mprintf("table %s is read-only", t->def->name.c_str()); return SQLITE_ERROR; }
    return t->def->update(v, argc, argv, rowid);
}

static sqlite3_module g_vt_module = {
    0, vt_connect, vt_connect, vt_best_index, vt_disconnect, vt_disconnect, vt_open, vt_close, vt_filter, vt_next, vt_eof, vt_column, vt_rowid,
    vt_update, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
};

static void register_vtab(sqlite3* db, std::unique_ptr<vtab_def> def, const std::string& module_name)
{
    auto* raw = def.get();
    g_vtabs[def->name] = std::move(def);
    sqlite3_create_module(db, module_name.c_str(), &g_vt_module, raw);
    std::string sql = "CREATE VIRTUAL TABLE " + raw->name + " USING " + module_name + "()";
    char* err = nullptr;
    sqlite3_exec(db, sql.c_str(), nullptr, nullptr, &err);
    if (err) { sqlite3_free(err); }
}

