    auto& lf = app.files[file_idx];
    std::string path = lf->path;
    auto parts = split(path, '/');
    for (size_t n = 1; n <= parts.size(); n++) {
        std::string cand;
        for (size_t k = parts.size() - n; k < parts.size(); k++) { if (!cand.empty() || k > parts.size() - n) cand += "/"; cand += parts[k]; }
        if (path.size() && path[0] == '/' && n == parts.size()) cand = path;
        bool unique = true;
        for (size_t fi = 0; fi < app.files.size(); fi++) {
            if ((int) fi == file_idx) continue;
            if (ends_with(app.files[fi]->path, cand) ) { unique = false; break; }
        }
        if (unique) return cand;
    }
    return path;
}

static void fill_log_rows(lnav_app& app, log_format* fmt_filter, bool all_logs, std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& rowids)
{
    const struct timeval* prev_tv = nullptr;
    for (auto& ve : app.log_visible) {
        auto& lf = app.files[ve.file_idx];
        auto& m = lf->messages[ve.msg_idx];
        bool include = all_logs || (fmt_filter && lf->format && lf->format->name == fmt_filter->name);
        if (!include) {
            prev_tv = &m.tv;
            continue;
        }
        std::vector<sql_value> row;
        row.push_back(sql_value::integer((int64_t) ve.row_start));
        row.push_back(sql_value::text(format_log_time(m.tv)));
        row.push_back(sql_value::text(level_name(m.level)));
        annotate_result ar = lf->annotate_message(m);
        if (all_logs) {
            // log_msg_format, log_msg_schema, log_msg_values, log_msg_src, log_stack_trace
            row.push_back(sql_value::text(ar.body_null ? "" : ar.body));
            row.push_back(sql_value::null());
            row.push_back(sql_value::text("{}"));
            row.push_back(sql_value::null());
            row.push_back(sql_value::null());
        } else {
            for (size_t k = 0; k < lf->format->values.size(); k++) {
                const auto& vd = lf->format->values[k];
                if (vd.column_index < 0) continue;
                const log_value* lv = k < ar.values.size() ? &ar.values[k] : nullptr;
                if (!lv || lv->is_null) { row.push_back(sql_value::null()); continue; }
                if (vd.identifier && !lv->from_json) { row.push_back(sql_value::text(lv->str)); continue; }
                switch (lv->kind) {
                case VK_INTEGER: row.push_back(lv->from_json && vd.identifier ? sql_value::text(lv->str) : sql_value::integer(lv->ival)); break;
                case VK_FLOAT: row.push_back(sql_value::real(lv->dval)); break;
                case VK_BOOLEAN: row.push_back(sql_value::integer(lv->ival)); break;
                default: row.push_back(sql_value::text(lv->str)); break;
                }
            }
        }
        row.push_back(m.partition.empty() ? sql_value::null() : sql_value::text(m.partition));
        row.push_back(sql_value::text(format_log_time(m.orig_tv)));
        int64_t idle = 0;
        if (prev_tv) idle = ((int64_t) m.tv.tv_sec - prev_tv->tv_sec) * 1000 + ((int64_t) m.tv.tv_usec - prev_tv->tv_usec) / 1000;
        row.push_back(sql_value::integer(idle));
        row.push_back(sql_value::integer(m.marked ? 1 : 0));
        row.push_back(sql_value::integer(0));
        row.push_back(m.comment.empty() ? sql_value::null() : sql_value::text(m.comment));
        if (m.tags.empty()) row.push_back(sql_value::null());
        else { json::Value arr = json::Value::array(); for (auto& t : m.tags) arr.push(json::Value::string(t)); row.push_back(sql_value::text(json::to_string(arr))); }
        row.push_back(sql_value::null());  // annotations
        row.push_back(sql_value::null());  // filters
        row.push_back(m.opid.empty() ? sql_value::null() : sql_value::text(m.opid));
        row.push_back(sql_value::null());
        row.push_back(sql_value::null());
        row.push_back(sql_value::text(lf->format->name));
        row.push_back(sql_value::text(lf->format->pattern_name(m.pattern_index)));
        row.push_back(sql_value::integer((int64_t) m.tv.tv_sec * 1000 + m.tv.tv_usec / 1000));
        row.push_back(sql_value::text(lf->path));
        row.push_back(sql_value::text(unique_path_for(app, ve.file_idx)));
        std::string text = lf->message_text(m);
        row.push_back(sql_value::text(text));
        row.push_back(ar.body_null ? sql_value::null() : sql_value::text(ar.body));
        row.push_back(sql_value::text(text));
        row.push_back(sql_value::null());  // line hash
        row.push_back(sql_value::null());  // link
        row.push_back(ar.has_src_file ? sql_value::text(ar.src_file) : sql_value::null());
        row.push_back(ar.has_src_line ? sql_value::text(ar.src_line) : sql_value::null());
        row.push_back(ar.has_thread_id ? sql_value::text(ar.thread_id) : sql_value::null());
        row.push_back(sql_value::null());
        rows.push_back(std::move(row));
        rowids.push_back((int64_t) ve.row_start);
        prev_tv = &m.tv;
    }
}

static int log_table_update(lnav_app& app, sqlite3_vtab* v, int argc, sqlite3_value** argv, const std::vector<std::string>& cols)
{
    if (argc == 1) { v->zErrMsg = sqlite3_mprintf("deleting rows is not supported"); return SQLITE_ERROR; }
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { v->zErrMsg = sqlite3_mprintf("inserting rows is not supported"); return SQLITE_ERROR; }
    int64_t rowid = sqlite3_value_int64(argv[0]);
    const view_entry* ve = app.entry_for_row((size_t) rowid);
    if (!ve || ve->row_start != (size_t) rowid) return SQLITE_OK;
    auto& m = app.files[ve->file_idx]->messages[ve->msg_idx];
    for (size_t c = 0; c < cols.size() && (int)(c + 2) < argc; c++) {
        sqlite3_value* val = argv[c + 2];
        const std::string& cn = cols[c];
        if (cn == "log_mark") { m.marked = sqlite3_value_int(val) != 0; }
        else if (cn == "log_comment") { m.comment = sqlite3_value_type(val) == SQLITE_NULL ? "" : (const char*) sqlite3_value_text(val); }
        else if (cn == "log_part") { m.partition = sqlite3_value_type(val) == SQLITE_NULL ? "" : (const char*) sqlite3_value_text(val); }
        else if (cn == "log_tags") {
            m.tags.clear();
            if (sqlite3_value_type(val) != SQLITE_NULL) {
                try {
                    json::Value arr = json::parse((const char*) sqlite3_value_text(val));
                    if (arr.is_array()) for (size_t k = 0; k < arr.size(); k++) if (arr[k].is_string()) m.tags.push_back(arr[k].s);
                } catch (...) {}
            }
        }
    }
    return SQLITE_OK;
}

static std::vector<std::string> parse_cols_from_create(const std::string& sql)
{
    std::vector<std::string> cols;
    size_t p = sql.find('(');
    std::string body = sql.substr(p + 1);
    for (auto& line : split(body, '\n')) {
        std::string l = trim(line);
        if (l.empty() || l[0] == ',' || l[0] == ')' || starts_with(l, "--") || starts_with(l, "PRIMARY")) continue;
        std::string nm;
        if (l[0] == '"') { size_t e = l.find('"', 1); nm = l.substr(1, e - 1); }
        else { size_t e = l.find_first_of(" \t"); nm = l.substr(0, e); }
        cols.push_back(nm);
    }
    return cols;
}

static void create_log_table(lnav_app& app, sqlite3* db, std::shared_ptr<log_format> fmt, bool all_logs)
{
    auto def = std::make_unique<vtab_def>();
    def->name = all_logs ? "all_logs" : fmt->name;
    std::string sql = "CREATE TABLE " + def->name + " (\n";
    sql += STD_COLS_HEAD;
    if (all_logs) {
        sql += "  log_msg_format TEXT COLLATE 'BINARY',\n  log_msg_schema TEXT hidden COLLATE 'BINARY',\n  log_msg_values TEXT COLLATE 'BINARY',\n  log_msg_src TEXT COLLATE 'BINARY',\n  log_stack_trace TEXT COLLATE 'BINARY',\n";
    } else {
        for (auto& vd : fmt->values) {
            if (vd.column_index < 0) continue;
            std::string coll = vd.collate.empty() ? "BINARY" : vd.collate;
            sql += "  \"" + vd.name + "\" " + sql_type_for_kind(vd.kind, vd.identifier) + " COLLATE '" + coll + "',\n";
        }
    }
    sql += STD_COLS_TAIL;
    sql += ")";
    def->create_sql = sql;
    def->columns = parse_cols_from_create(sql);
    log_format* raw = fmt.get();
    lnav_app* ap = &app;
    def->fill = [ap, raw, all_logs](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) { fill_log_rows(*ap, raw, all_logs, rows, ids); };
    std::vector<std::string> cols = def->columns;
    def->update = [ap, cols](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64*) { return log_table_update(*ap, v, argc, argv, cols); };
    register_vtab(db, std::move(def), all_logs ? "log_vtab_impl_all" : "log_vtab_impl_" + fmt->name);
}

