static std::string compute_content_id(const logfile& lf)
{
    // a stable-ish hash of the beginning of the file
    uint64_t h1 = 1469598103934665603ULL, h2 = 0x9e3779b97f4a7c15ULL;
    size_t n = std::min(lf.content.size(), (size_t) 4096);
    for (size_t k = 0; k < n; k++) { h1 ^= (unsigned char) lf.content[k]; h1 *= 1099511628211ULL; h2 = (h2 ^ (unsigned char) lf.content[k]) * 0x100000001b3ULL + k; }
    char buf[64];
    snprintf(buf, sizeof(buf), "v1:%016llx%016llx", (unsigned long long) h1, (unsigned long long) h2);
    return buf;
}

static std::string mimetype_for(const logfile& lf)
{
    if (lf.lines.empty() || lf.content.empty()) return "application/octet-stream";
    if (lf.format) return "text/log";
    return lf.mimetype;
}

static void create_misc_tables(lnav_app& app, sqlite3* db)
{
    lnav_app* ap = &app;
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_file";
        def->create_sql = "CREATE TABLE lnav_file (device integer, inode integer, filepath text, mimetype text, content_id text, format text, lines integer, time_offset integer, options_path TEXT, options TEXT, content BLOB HIDDEN)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            int64_t id = 0;
            for (auto& lf : ap->files) {
                std::vector<sql_value> row;
                row.push_back(sql_value::integer((int64_t) lf->st.st_dev));
                row.push_back(sql_value::integer((int64_t) lf->st.st_ino));
                row.push_back(sql_value::text(lf->path));
                row.push_back(sql_value::text(mimetype_for(*lf)));
                row.push_back(sql_value::text(compute_content_id(*lf)));
                row.push_back(lf->format ? sql_value::text(lf->format->name) : sql_value::null());
                row.push_back(sql_value::integer((int64_t) lf->lines.size()));
                row.push_back(sql_value::integer(lf->time_offset_ms));
                row.push_back(sql_value::null());
                row.push_back(sql_value::null());
                row.push_back(sql_value::blob(lf->content));
                rows.push_back(row);
                ids.push_back(id++);
            }
        };
        def->update = [ap](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1 || sqlite3_value_type(argv[0]) == SQLITE_NULL) { v->zErrMsg = sqlite3_mprintf("Rows cannot be inserted into or deleted from the lnav_file table"); return SQLITE_ERROR; }
            int64_t rowid = sqlite3_value_int64(argv[0]);
            if (rowid < 0 || (size_t) rowid >= ap->files.size()) return SQLITE_OK;
            auto& lf = ap->files[rowid];
            // filepath (col 2) can be renamed, time_offset (col 7)
            if (sqlite3_value_type(argv[2 + 2]) == SQLITE_TEXT) { lf->path = (const char*) sqlite3_value_text(argv[4]); lf->filename = lf->path; }
            if (sqlite3_value_type(argv[2 + 7]) == SQLITE_INTEGER) {
                int64_t off = sqlite3_value_int64(argv[9]);
                int64_t delta = off - lf->time_offset_ms;
                lf->time_offset_ms = off;
                for (auto& m : lf->messages) { int64_t us = (int64_t) m.tv.tv_sec * 1000000 + m.tv.tv_usec + delta * 1000; m.tv.tv_sec = us / 1000000; m.tv.tv_usec = us % 1000000; }
                ap->rebuild_log_view();
            }
            return SQLITE_OK;
        };
        register_vtab(db, std::move(def), "lnav_file_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_views";
        def->create_sql = "CREATE TABLE lnav_views (name TEXT PRIMARY KEY, top INTEGER, left INTEGER, height INTEGER, inner_height INTEGER, top_time DATETIME, top_file TEXT, paused INTEGER, search TEXT, filtering INTEGER, movement TEXT, top_meta TEXT, selection INTEGER, options TEXT, selected_text TEXT, row_details TEXT)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            static const char* names[] = {"log", "text", "help", "histogram", "db", "schema", "pretty", "spectro", "timeline", "gantt"};
            int64_t id = 0;
            for (const char* n : names) {
                std::vector<sql_value> row;
                std::string nm = n;
                row.push_back(sql_value::text(nm));
                size_t top = 0, inner = 0;
                sql_value top_time = sql_value::null(), top_file = sql_value::null();
                if (nm == "log") {
                    top = ap->log_top; inner = ap->log_row_count();
                    if (!ap->log_visible.empty()) {
                        const view_entry* ve = ap->entry_for_row(std::min(top, inner ? inner - 1 : 0));
                        if (ve) { auto& lf = ap->files[ve->file_idx]; top_time = sql_value::text(format_log_time(lf->messages[ve->msg_idx].tv)); top_file = sql_value::text(lf->path); }
                    }
                } else if (nm == "text") {
                    top = ap->text_top; inner = ap->text_view_lines().size();
                    for (auto& lf : ap->files) if (lf->is_text() && !lf->lines.empty()) { top_file = sql_value::text(lf->path); break; }
                } else if (nm == "db") {
                    top = ap->db_top; inner = ap->last_result.valid ? ap->last_result.rows.size() : 0;
                }
                row.push_back(sql_value::integer((int64_t) top));
                row.push_back(sql_value::integer(0));
                row.push_back(sql_value::integer(0));
                row.push_back(sql_value::integer((int64_t) inner));
                row.push_back(top_time);
                row.push_back(top_file);
                row.push_back(sql_value::integer(0));
                row.push_back(sql_value::text(""));
                row.push_back(sql_value::integer(1));
                row.push_back(sql_value::text("cursor"));
                row.push_back(sql_value::text("{}"));
                row.push_back(sql_value::integer((int64_t) top));
                row.push_back(sql_value::text("{}"));
                row.push_back(sql_value::null());
                row.push_back(sql_value::null());
                rows.push_back(row);
                ids.push_back(id++);
            }
        };
        def->update = [ap](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1 || sqlite3_value_type(argv[0]) == SQLITE_NULL) { v->zErrMsg = sqlite3_mprintf("Rows cannot be inserted into or deleted from the lnav_views table"); return SQLITE_ERROR; }
            int64_t rowid = sqlite3_value_int64(argv[0]);
            static const char* names[] = {"log", "text", "help", "histogram", "db", "schema", "pretty", "spectro", "timeline", "gantt"};
            if (rowid < 0 || rowid >= 10) return SQLITE_OK;
            std::string nm = names[rowid];
            if (sqlite3_value_type(argv[2 + 1]) == SQLITE_INTEGER) {
                int64_t top = sqlite3_value_int64(argv[3]);
                if (nm == "log") ap->log_top = (size_t) std::max<int64_t>(0, top);
                else if (nm == "text") ap->text_top = (size_t) std::max<int64_t>(0, top);
            }
            if (sqlite3_value_type(argv[2 + 12]) == SQLITE_INTEGER) {
                int64_t sel = sqlite3_value_int64(argv[14]);
                if (nm == "log") ap->log_top = (size_t) std::max<int64_t>(0, sel);
                else if (nm == "text") ap->text_top = (size_t) std::max<int64_t>(0, sel);
            }
            return SQLITE_OK;
        };
        register_vtab(db, std::move(def), "lnav_views_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_view_stack";
        def->create_sql = "CREATE TABLE lnav_view_stack (name TEXT)";
        def->columns = {"name"};
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            int64_t id = 0;
            for (auto& v : ap->view_stack) { rows.push_back({sql_value::text(v)}); ids.push_back(id++); }
            rows.push_back({sql_value::text(ap->current_view)}); ids.push_back(id++);
        };
        register_vtab(db, std::move(def), "lnav_view_stack_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_view_filters";
        def->create_sql = "CREATE TABLE lnav_view_filters (view_name TEXT, filter_id INTEGER DEFAULT 0, enabled INTEGER DEFAULT 1, type TEXT DEFAULT 'out', language TEXT DEFAULT 'regex', pattern TEXT)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            auto add = [&](const char* view, const text_filter& f) {
                rows.push_back({sql_value::text(view), sql_value::integer(f.id), sql_value::integer(f.enabled ? 1 : 0), sql_value::text(f.out ? "out" : "in"), sql_value::text(f.lang), sql_value::text(f.pattern)});
                ids.push_back(f.id);
            };
            for (auto& f : ap->log_filters) add("log", f);
            for (auto& f : ap->text_filters) add("text", f);
        };
        def->update = [ap](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64* rowid_out) {
            auto find = [&](int64_t id, std::vector<text_filter>** vec) -> text_filter* {
                for (auto& f : ap->log_filters) if (f.id == id) { *vec = &ap->log_filters; return &f; }
                for (auto& f : ap->text_filters) if (f.id == id) { *vec = &ap->text_filters; return &f; }
                return nullptr;
            };
            if (argc == 1) {
                int64_t id = sqlite3_value_int64(argv[0]);
                std::vector<text_filter>* vec = nullptr;
                text_filter* f = find(id, &vec);
                if (f) { vec->erase(vec->begin() + (f - vec->data())); ap->apply_filters(); }
                return SQLITE_OK;
            }
            std::string view = sqlite3_value_type(argv[2]) == SQLITE_TEXT ? (const char*) sqlite3_value_text(argv[2]) : "log";
            text_filter nf;
            nf.id = sqlite3_value_type(argv[3]) == SQLITE_INTEGER ? (int) sqlite3_value_int64(argv[3]) : 0;
            nf.enabled = sqlite3_value_type(argv[4]) == SQLITE_NULL ? true : sqlite3_value_int(argv[4]) != 0;
            std::string type = sqlite3_value_type(argv[5]) == SQLITE_TEXT ? (const char*) sqlite3_value_text(argv[5]) : "out";
            nf.out = (type != "in");
            nf.lang = sqlite3_value_type(argv[6]) == SQLITE_TEXT ? (const char*) sqlite3_value_text(argv[6]) : "regex";
            nf.pattern = sqlite3_value_type(argv[7]) == SQLITE_TEXT ? (const char*) sqlite3_value_text(argv[7]) : "";
            if (nf.lang == "regex") {
                try { nf.re = std::make_shared<Regex>(nf.pattern); } catch (regex_error& e) { v->zErrMsg = sqlite3_mprintf("invalid regular expression: %s", e.what()); return SQLITE_ERROR; }
            }
            if (sqlite3_value_type(argv[0]) == SQLITE_NULL) {
                if (nf.id == 0) nf.id = ap->next_filter_id++;
                else if (nf.id >= ap->next_filter_id) ap->next_filter_id = nf.id + 1;
                if (view == "text") ap->text_filters.push_back(nf); else ap->log_filters.push_back(nf);
                *rowid_out = nf.id;
            } else {
                int64_t id = sqlite3_value_int64(argv[0]);
                std::vector<text_filter>* vec = nullptr;
                text_filter* f = find(id, &vec);
                if (f) { int oid = f->id; *f = nf; f->id = oid; }
            }
            ap->apply_filters();
            return SQLITE_OK;
        };
        register_vtab(db, std::move(def), "lnav_view_filters_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_view_filter_stats";
        def->create_sql = "CREATE TABLE lnav_view_filter_stats (view_name TEXT, filter_id INTEGER, hits INTEGER)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            int64_t id = 0;
            for (auto& f : ap->log_filters) {
                size_t hits = 0;
                if (f.re) for (auto& ve : ap->log_entries) { Regex::Match m; if (f.re->match(ap->message_display_text(ve.file_idx, ve.msg_idx), m)) hits++; }
                rows.push_back({sql_value::text("log"), sql_value::integer(f.id), sql_value::integer((int64_t) hits)}); ids.push_back(id++);
            }
            for (auto& f : ap->text_filters) {
                rows.push_back({sql_value::text("text"), sql_value::integer(f.id), sql_value::integer((int64_t) f.hits)}); ids.push_back(id++);
            }
        };
        register_vtab(db, std::move(def), "lnav_view_filter_stats_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_view_files";
        def->create_sql = "CREATE TABLE lnav_view_files (view_name TEXT, filepath TEXT, visible INTEGER)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            int64_t id = 0;
            for (auto& lf : ap->files) {
                if (lf->is_text()) continue;
                rows.push_back({sql_value::text("log"), sql_value::text(lf->path), sql_value::integer(lf->visible ? 1 : 0)}); ids.push_back(id++);
            }
        };
        def->update = [ap](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1 || sqlite3_value_type(argv[0]) == SQLITE_NULL) { v->zErrMsg = sqlite3_mprintf("Rows cannot be inserted into or deleted from the lnav_view_files table"); return SQLITE_ERROR; }
            int64_t rowid = sqlite3_value_int64(argv[0]);
            int64_t id = 0;
            for (auto& lf : ap->files) {
                if (lf->is_text()) continue;
                if (id == rowid) { lf->visible = sqlite3_value_int(argv[4]) != 0; ap->rebuild_log_view(); break; }
                id++;
            }
            return SQLITE_OK;
        };
        register_vtab(db, std::move(def), "lnav_view_files_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "environ";
        def->create_sql = "CREATE TABLE environ (name TEXT PRIMARY KEY, value TEXT)";
        def->columns = {"name", "value"};
        def->fill = [](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            extern char** environ;
            int64_t id = 0;
            std::vector<std::pair<std::string, std::string>> env;
            for (char** e = environ; *e; e++) {
                std::string kv = *e;
                size_t eq = kv.find('=');
                if (eq == std::string::npos) continue;
                env.emplace_back(kv.substr(0, eq), kv.substr(eq + 1));
            }
            for (auto& [k, v] : env) { rows.push_back({sql_value::text(k), sql_value::text(v)}); ids.push_back(id++); }
        };
        def->update = [](sqlite3_vtab* v, int argc, sqlite3_value** argv, sqlite3_int64*) {
            extern char** environ;
            auto name_at = [&](int64_t rowid) -> std::string {
                int64_t id = 0;
                for (char** e = environ; *e; e++) {
                    std::string kv = *e; size_t eq = kv.find('='); if (eq == std::string::npos) continue;
                    if (id == rowid) return kv.substr(0, eq);
                    id++;
                }
                return "";
            };
            if (argc == 1) { std::string n = name_at(sqlite3_value_int64(argv[0])); if (!n.empty()) unsetenv(n.c_str()); return SQLITE_OK; }
            if (sqlite3_value_type(argv[2]) != SQLITE_TEXT) { v->zErrMsg = sqlite3_mprintf("A non-empty name is required for environment variables"); return SQLITE_ERROR; }
            std::string name = (const char*) sqlite3_value_text(argv[2]);
            if (name.empty()) { v->zErrMsg = sqlite3_mprintf("A non-empty name is required for environment variables"); return SQLITE_ERROR; }
            if (name.find('=') != std::string::npos) { v->zErrMsg = sqlite3_mprintf("Environment variable names cannot contain an equals sign (=)"); return SQLITE_ERROR; }
            std::string value = sqlite3_value_type(argv[3]) == SQLITE_NULL ? "" : (const char*) sqlite3_value_text(argv[3]);
            if (sqlite3_value_type(argv[0]) == SQLITE_NULL) {
                if (getenv(name.c_str())) { v->zErrMsg = sqlite3_mprintf("An environment variable with the name '%s' already exists", name.c_str()); return SQLITE_CONSTRAINT; }
            } else {
                std::string old = name_at(sqlite3_value_int64(argv[0]));
                if (!old.empty() && old != name) unsetenv(old.c_str());
            }
            setenv(name.c_str(), value.c_str(), 1);
            return SQLITE_OK;
        };
        register_vtab(db, std::move(def), "environ_vtab_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_file_metadata";
        def->create_sql = "CREATE TABLE lnav_file_metadata (filepath text, descriptor text, mimetype text, content text)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [](std::vector<std::vector<sql_value>>&, std::vector<int64_t>&) {};
        register_vtab(db, std::move(def), "lnav_file_metadata_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "all_opids";
        def->create_sql = "CREATE TABLE all_opids (opid TEXT PRIMARY KEY, earliest DATETIME, latest DATETIME, duration INTEGER, errors INTEGER, warnings INTEGER, total INTEGER, definition TEXT, description TEXT)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [ap](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            struct st { struct timeval first, last; int64_t errors = 0, warnings = 0, total = 0; };
            std::map<std::string, st> m;
            std::vector<std::string> order;
            for (auto& ve : ap->log_visible) {
                auto& lf = ap->files[ve.file_idx];
                auto& msg = lf->messages[ve.msg_idx];
                if (msg.opid.empty()) continue;
                auto it = m.find(msg.opid);
                if (it == m.end()) { st s; s.first = msg.tv; s.last = msg.tv; m[msg.opid] = s; order.push_back(msg.opid); it = m.find(msg.opid); }
                it->second.last = msg.tv;
                it->second.total++;
                if (msg.level >= LEVEL_ERROR) it->second.errors++;
                else if (msg.level == LEVEL_WARNING) it->second.warnings++;
            }
            std::sort(order.begin(), order.end());
            int64_t id = 0;
            for (auto& k : order) {
                auto& s = m[k];
                int64_t dur = ((int64_t) s.last.tv_sec - s.first.tv_sec) * 1000000 + (s.last.tv_usec - s.first.tv_usec);
                rows.push_back({sql_value::text(k), sql_value::text(format_log_time(s.first)), sql_value::text(format_log_time(s.last)), sql_value::integer(dur), sql_value::integer(s.errors), sql_value::integer(s.warnings), sql_value::integer(s.total), sql_value::null(), sql_value::null()});
                ids.push_back(id++);
            }
        };
        register_vtab(db, std::move(def), "all_opids_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "all_thread_ids";
        def->create_sql = "CREATE TABLE all_thread_ids (thread_id TEXT PRIMARY KEY, earliest DATETIME, latest DATETIME, duration INTEGER, errors INTEGER, warnings INTEGER, total INTEGER)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [](std::vector<std::vector<sql_value>>&, std::vector<int64_t>&) {};
        register_vtab(db, std::move(def), "all_thread_ids_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_log_breakpoints";
        def->create_sql = "CREATE TABLE lnav_log_breakpoints (schema_id TEXT NOT NULL, description TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'src_location', enabled INTEGER NOT NULL DEFAULT 1)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [](std::vector<std::vector<sql_value>>&, std::vector<int64_t>&) {};
        register_vtab(db, std::move(def), "lnav_log_breakpoints_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_apps";
        def->create_sql = "CREATE TABLE lnav_apps (name TEXT PRIMARY KEY, description TEXT, root TEXT)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [](std::vector<std::vector<sql_value>>& rows, std::vector<int64_t>& ids) {
            rows.push_back({sql_value::text("lnav"), sql_value::text("The lnav app"), sql_value::text("")}); ids.push_back(0);
        };
        register_vtab(db, std::move(def), "lnav_apps_impl");
    }
    {
        auto def = std::make_unique<vtab_def>();
        def->name = "lnav_app_files";
        def->create_sql = "CREATE TABLE lnav_app_files (name TEXT PRIMARY KEY, app TEXT, filepath TEXT, content BLOB HIDDEN)";
        def->columns = parse_cols_from_create(def->create_sql);
        def->fill = [](std::vector<std::vector<sql_value>>&, std::vector<int64_t>&) {};
        register_vtab(db, std::move(def), "lnav_app_file_vtab_impl");
    }
}

