// collations
static int collate_loglevel(void*, int l1, const void* s1, int l2, const void* s2)
{
    auto a = string2level((const char*) s1, l1, true);
    auto b = string2level((const char*) s2, l2, true);
    return (int) a - (int) b;
}

static int natural_compare(const char* a, int la, const char* b, int lb, bool nocase)
{
    int i = 0, j = 0;
    while (i < la && j < lb) {
        if (isdigit((unsigned char) a[i]) && isdigit((unsigned char) b[j])) {
            // compare numbers
            int si = i, sj = j;
            while (i < la && isdigit((unsigned char) a[i])) i++;
            while (j < lb && isdigit((unsigned char) b[j])) j++;
            // strip leading zeros
            int zi = si, zj = sj;
            while (zi < i - 1 && a[zi] == '0') zi++;
            while (zj < j - 1 && b[zj] == '0') zj++;
            int ni = i - zi, nj = j - zj;
            if (ni != nj) return ni - nj;
            int c = memcmp(a + zi, b + zj, ni);
            if (c) return c;
            continue;
        }
        char ca = a[i], cb = b[j];
        if (nocase) { ca = (char) tolower((unsigned char) ca); cb = (char) tolower((unsigned char) cb); }
        if (ca != cb) return (unsigned char) ca - (unsigned char) cb;
        i++; j++;
    }
    return (la - i) - (lb - j);
}
static int collate_naturalcase(void*, int l1, const void* s1, int l2, const void* s2) { return natural_compare((const char*) s1, l1, (const char*) s2, l2, false); }
static int collate_naturalnocase(void*, int l1, const void* s1, int l2, const void* s2) { return natural_compare((const char*) s1, l1, (const char*) s2, l2, true); }
static int collate_ipaddress(void*, int l1, const void* s1, int l2, const void* s2)
{
    std::string a((const char*) s1, l1), b((const char*) s2, l2);
    unsigned ia[4], ib[4];
    bool va = sscanf(a.c_str(), "%u.%u.%u.%u", &ia[0], &ia[1], &ia[2], &ia[3]) == 4;
    bool vb = sscanf(b.c_str(), "%u.%u.%u.%u", &ib[0], &ib[1], &ib[2], &ib[3]) == 4;
    if (va && vb) {
        for (int k = 0; k < 4; k++) if (ia[k] != ib[k]) return (int) ia[k] - (int) ib[k];
        return 0;
    }
    if (va != vb) return va ? -1 : 1;
    return natural_compare(a.data(), l1, b.data(), l2, true);
}

void sql_init(lnav_app& app)
{
    sqlite3* db = nullptr;
    sqlite3_open(":memory:", &db);
    app.db = db;
    sqlite3_create_collation(db, "loglevel", SQLITE_UTF8, nullptr, collate_loglevel);
    sqlite3_create_collation(db, "naturalcase", SQLITE_UTF8, nullptr, collate_naturalcase);
    sqlite3_create_collation(db, "naturalnocase", SQLITE_UTF8, nullptr, collate_naturalnocase);
    sqlite3_create_collation(db, "ipaddress", SQLITE_UTF8, nullptr, collate_ipaddress);
    register_sql_functions(app, db);
    create_misc_tables(app, db);
    sqlite3_exec(db, STATIC_SCHEMA, nullptr, nullptr, nullptr);
    for (auto& hc : HTTP_CODES) {
        char* sql = sqlite3_mprintf("INSERT INTO http_status_codes VALUES (%d, %Q)", hc.code, hc.msg);
        sqlite3_exec(db, sql, nullptr, nullptr, nullptr);
        sqlite3_free(sql);
    }
    // log tables
    for (auto& fmt : formats().root_formats) {
        create_log_table(app, db, fmt, false);
    }
    create_log_table(app, db, nullptr, true);
}

