    for (double v : a->vals) { int idx = mx > 0 ? (int) std::round(v / mx * 8) : 0; if (idx < 0) idx = 0; if (idx > 8) idx = 8; out += bars[idx]; }
    a->~agg();
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
