static void fn_logfmt2json(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string line = arg_text(argv[0]);
    json::Value obj = json::Value::object();
    size_t p = 0, n = line.size();
    while (p < n) {
        while (p < n && line[p] == ' ') p++;
        if (p >= n) break;
        size_t ks = p; while (p < n && line[p] != '=' && line[p] != ' ') p++;
        std::string key = line.substr(ks, p - ks);
        if (p >= n || line[p] != '=') { obj.set(key, json::Value::boolean(true)); continue; }
        p++;
        std::string val;
        if (p < n && line[p] == '"') { p++; while (p < n && line[p] != '"') { if (line[p] == '\\' && p + 1 < n) p++; val += line[p]; p++; } if (p < n) p++; obj.set(key, json::Value::string(val)); }
        else { size_t vs = p; while (p < n && line[p] != ' ') p++; val = line.substr(vs, p - vs);
            char* e; long long iv = strtoll(val.c_str(), &e, 10); if (!val.empty() && *e == 0) obj.set(key, json::Value::integer(iv));
            else { double dv = strtod(val.c_str(), &e); if (!val.empty() && *e == 0) obj.set(key, json::Value::number(dv)); else if (val == "true" || val == "false") obj.set(key, json::Value::boolean(val == "true")); else obj.set(key, json::Value::string(val)); } }
    }
    std::string out = json::to_string(obj);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
