{
    (void) v;
    int argi = 1;
    bool into_json = false;
    for (int k = 0; k < info->nConstraint; k++) {
        auto& c = info->aConstraint[k];
        if (!c.usable || c.op != SQLITE_INDEX_CONSTRAINT_EQ) continue;
        // hidden columns: value, pattern (7,8) or (2,3) for json
        if (c.iColumn == 7 || c.iColumn == 2) { info->aConstraintUsage[k].argvIndex = 1; info->aConstraintUsage[k].omit = 1; }
        else if (c.iColumn == 8 || c.iColumn == 3) { info->aConstraintUsage[k].argvIndex = 2; info->aConstraintUsage[k].omit = 1; }
        else if (c.iColumn == 4 && into_json) { info->aConstraintUsage[k].argvIndex = 3; info->aConstraintUsage[k].omit = 1; }
    }
    (void) argi;
    info->estimatedCost = 10.0;
    return SQLITE_OK;
}
static int rc_open(sqlite3_vtab*, sqlite3_vtab_cursor** pp) { auto* c = new rc_cursor(); memset(&c->base, 0, sizeof(c->base)); *pp = &c->base; return SQLITE_OK; }
static int rc_close(sqlite3_vtab_cursor* c) { delete (rc_cursor*) c; return SQLITE_OK; }
static int rc_filter_impl(sqlite3_vtab_cursor* pc, int, const char*, int argc, sqlite3_value** argv, bool into_json)
{
    auto* c = (rc_cursor*) pc;
    c->rows.clear(); c->json_rows.clear(); c->pos = 0; c->into_json = into_json;
    if (argc < 2) return SQLITE_OK;
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) return SQLITE_OK;
    c->value = arg_text(argv[0]); c->pattern = arg_text(argv[1]);
    std::shared_ptr<Regex> re;
    try { re = std::make_shared<Regex>(c->pattern); } catch (regex_error& e) { pc->pVtab->zErrMsg = sqlite3_mprintf("Invalid regular expression: %s", e.what()); return SQLITE_ERROR; }
    size_t pos = 0; int64_t mi = 0;
    Regex::Match m;
    while (pos <= c->value.size() && re->match(c->value, m, pos)) {
        int cc = re->capture_count();
        if (into_json) {
            json::Value obj = json::Value::object();
            for (int g = 1; g <= cc; g++) {
                std::string key = (g < (int) re->names().size() && !re->names()[g].empty()) ? re->names()[g] : ("col_" + std::to_string(g - 1));
                if (!m.has(g)) { obj.set(key, json::Value::null()); continue; }
                std::string cap = m.str(g); char* e; long long iv = strtoll(cap.c_str(), &e, 10);
                if (!cap.empty() && *e == 0) obj.set(key, json::Value::integer(iv)); else { double dv = strtod(cap.c_str(), &e); if (!cap.empty() && *e == 0) obj.set(key, json::Value::number(dv)); else obj.set(key, json::Value::string(cap)); }
            }
            c->json_rows.push_back(json::to_string(obj));
            c->rows.push_back({mi, 0, "", cc, (int64_t) m.start(0), (int64_t) m.end(0), "", false});
        } else {
            for (int g = 0; g <= cc; g++) {
                rc_cursor::row r;
                r.match_index = mi; r.capture_index = g; r.name = g < (int) re->names().size() ? re->names()[g] : ""; r.count = cc + 1;
                if (m.has(g)) { r.start = (int64_t) m.start(g); r.stop = (int64_t) m.end(g); r.content = m.str(g); r.null_content = false; }
                else { r.start = -1; r.stop = -1; r.null_content = true; }
                c->rows.push_back(r);
            }
        }
        mi++;
        size_t e = m.end(0);
        if (e == m.start(0)) { pos = e + 1; } else pos = e;
    }
    return SQLITE_OK;
}
static int rc_filter(sqlite3_vtab_cursor* pc, int a, const char* b, int argc, sqlite3_value** argv) { return rc_filter_impl(pc, a, b, argc, argv, false); }
static int rcj_filter(sqlite3_vtab_cursor* pc, int a, const char* b, int argc, sqlite3_value** argv) { return rc_filter_impl(pc, a, b, argc, argv, true); }
static int rc_next(sqlite3_vtab_cursor* pc) { ((rc_cursor*) pc)->pos++; return SQLITE_OK; }
static int rc_eof(sqlite3_vtab_cursor* pc) { auto* c = (rc_cursor*) pc; return c->pos >= c->rows.size(); }
static int rc_column(sqlite3_vtab_cursor* pc, sqlite3_context* ctx, int col)
{
    auto* c = (rc_cursor*) pc; auto& r = c->rows[c->pos];
    if (c->into_json) {
        switch (col) { case 0: sqlite3_result_int64(ctx, r.match_index); break; case 1: sqlite3_result_text(ctx, c->json_rows[c->pos].c_str(), -1, SQLITE_TRANSIENT); sqlite3_result_subtype(ctx, 'J'); break; case 2: sqlite3_result_text(ctx, c->value.c_str(), -1, SQLITE_TRANSIENT); break; case 3: sqlite3_result_text(ctx, c->pattern.c_str(), -1, SQLITE_TRANSIENT); break; default: sqlite3_result_null(ctx); }
        return SQLITE_OK;
    }
    switch (col) {
    case 0: sqlite3_result_int64(ctx, r.match_index); break;
    case 1: sqlite3_result_int64(ctx, r.capture_index); break;
    case 2: if (r.name.empty()) sqlite3_result_null(ctx); else sqlite3_result_text(ctx, r.name.c_str(), -1, SQLITE_TRANSIENT); break;
    case 3: sqlite3_result_int64(ctx, r.count); break;
    case 4: sqlite3_result_int64(ctx, r.start); break;
    case 5: sqlite3_result_int64(ctx, r.stop); break;
    case 6: if (r.null_content) sqlite3_result_null(ctx); else sqlite3_result_text(ctx, r.content.c_str(), -1, SQLITE_TRANSIENT); break;
    case 7: sqlite3_result_text(ctx, c->value.c_str(), -1, SQLITE_TRANSIENT); break;
    case 8: sqlite3_result_text(ctx, c->pattern.c_str(), -1, SQLITE_TRANSIENT); break;
    default: sqlite3_result_null(ctx);
    }
    return SQLITE_OK;
}
static int rc_rowid(sqlite3_vtab_cursor* pc, sqlite3_int64* out) { *out = (sqlite3_int64) ((rc_cursor*) pc)->pos; return SQLITE_OK; }
static sqlite3_module rc_module = {0, rc_connect, rc_connect, rc_best_index, rc_disconnect, rc_disconnect, rc_open, rc_close, rc_filter, rc_next, rc_eof, rc_column, rc_rowid, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr};
static sqlite3_module rcj_module = {0, rc_connect, rc_connect, rc_best_index, rc_disconnect, rc_disconnect, rc_open, rc_close, rcj_filter, rc_next, rc_eof, rc_column, rc_rowid, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr};

// generate_series
struct gs_cursor { sqlite3_vtab_cursor base; int64_t cur = 0, start = 0, stop = 0, step = 1; bool eof = false; };
static int gs_connect(sqlite3* db, void*, int, const char* const*, sqlite3_vtab** pp, char**)
{
    int rc = sqlite3_declare_vtab(db, "CREATE TABLE x(value, start HIDDEN, stop HIDDEN, step HIDDEN)");
    if (rc != SQLITE_OK) return rc;
    auto* t = new rc_vtab(); memset(&t->base, 0, sizeof(t->base)); *pp = &t->base; return SQLITE_OK;
}
static int gs_best_index(sqlite3_vtab*, sqlite3_index_info* info)
{
    int mask = 0;
    for (int k = 0; k < info->nConstraint; k++) {
        auto& c = info->aConstraint[k];
        if (!c.usable || c.op != SQLITE_INDEX_CONSTRAINT_EQ) continue;
        if (c.iColumn >= 1 && c.iColumn <= 3) { info->aConstraintUsage[k].argvIndex = c.iColumn; info->aConstraintUsage[k].omit = 1; mask |= 1 << c.iColumn; }
    }
    info->idxNum = mask;
    info->estimatedCost = 10.0;
    return SQLITE_OK;
}
static int gs_open(sqlite3_vtab*, sqlite3_vtab_cursor** pp) { auto* c = new gs_cursor(); memset(&c->base, 0, sizeof(c->base)); *pp = &c->base; return SQLITE_OK; }
static int gs_close(sqlite3_vtab_cursor* c) { delete (gs_cursor*) c; return SQLITE_OK; }
static int gs_filter(sqlite3_vtab_cursor* pc, int idxNum, const char*, int argc, sqlite3_value** argv)
{
    auto* c = (gs_cursor*) pc;
    c->start = 0; c->stop = 0; c->step = 1;
    int ai = 0;
    if (idxNum & 2) c->start = sqlite3_value_int64(argv[ai++]);
    if (idxNum & 4) c->stop = sqlite3_value_int64(argv[ai++]); else c->stop = INT64_MAX;
    if (idxNum & 8) c->step = sqlite3_value_int64(argv[ai++]);
    if (c->step == 0) c->step = 1;
    (void) argc;
    c->cur = c->start;
    c->eof = c->step > 0 ? c->cur > c->stop : c->cur < c->stop;
    return SQLITE_OK;
}
static int gs_next(sqlite3_vtab_cursor* pc) { auto* c = (gs_cursor*) pc; c->cur += c->step; c->eof = c->step > 0 ? c->cur > c->stop : c->cur < c->stop; return SQLITE_OK; }
static int gs_eof(sqlite3_vtab_cursor* pc) { return ((gs_cursor*) pc)->eof; }
static int gs_column(sqlite3_vtab_cursor* pc, sqlite3_context* ctx, int col)
{
    auto* c = (gs_cursor*) pc;
    switch (col) { case 0: sqlite3_result_int64(ctx, c->cur); break; case 1: sqlite3_result_int64(ctx, c->start); break; case 2: sqlite3_result_int64(ctx, c->stop); break; case 3: sqlite3_result_int64(ctx, c->step); break; }
    return SQLITE_OK;
}
static int gs_rowid(sqlite3_vtab_cursor* pc, sqlite3_int64* out) { *out = ((gs_cursor*) pc)->cur; return SQLITE_OK; }
static sqlite3_module gs_module = {0, gs_connect, gs_connect, gs_best_index, rc_disconnect, rc_disconnect, gs_open, gs_close, gs_filter, gs_next, gs_eof, gs_column, gs_rowid, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr};

