static std::string arg_text(sqlite3_value* v)
{
    if (sqlite3_value_type(v) == SQLITE_NULL) return "";
    const unsigned char* s = sqlite3_value_text(v);
    int n = sqlite3_value_bytes(v);
    return s ? std::string((const char*) s, n) : std::string();
}

static std::shared_ptr<Regex> get_regex(sqlite3_context* ctx, const std::string& pat, bool& ok)
{
    static std::map<std::string, std::shared_ptr<Regex>> cache;
    auto it = cache.find(pat);
    if (it != cache.end()) { ok = true; return it->second; }
    try {
        auto re = std::make_shared<Regex>(pat);
        cache[pat] = re;
        ok = true;
        return re;
    } catch (regex_error& e) {
        std::string msg = "Invalid regular expression: " + std::string(e.what());
        sqlite3_result_error(ctx, msg.c_str(), -1);
        ok = false;
        return nullptr;
    }
}

static void fn_regexp(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    // regexp(pattern, str)
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    bool ok; auto re = get_regex(ctx, arg_text(argv[0]), ok); if (!ok) return;
    std::string s = arg_text(argv[1]);
    sqlite3_result_int(ctx, re->test(s) ? 1 : 0);
}

static void fn_regexp_match(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    bool ok; auto re = get_regex(ctx, arg_text(argv[0]), ok); if (!ok) return;
    std::string s = arg_text(argv[1]);
    Regex::Match m;
    if (!re->match(s, m)) { sqlite3_result_null(ctx); return; }
    int cc = re->capture_count();
    if (cc == 0) { sqlite3_result_error(ctx, "regular expression does not have any captures", -1); return; }
    if (cc == 1) {
        if (!m.has(1)) { sqlite3_result_null(ctx); return; }
        std::string cap = m.str(1);
        // try to produce a number if it looks like one
        char* endp = nullptr;
        long long iv = strtoll(cap.c_str(), &endp, 10);
        if (!cap.empty() && endp && *endp == '\0') { sqlite3_result_int64(ctx, iv); return; }
        double dv = strtod(cap.c_str(), &endp);
        if (!cap.empty() && endp && *endp == '\0') { sqlite3_result_double(ctx, dv); return; }
        sqlite3_result_text(ctx, cap.c_str(), -1, SQLITE_TRANSIENT);
        return;
    }
    json::Value obj = json::Value::object();
    const auto& names = re->names();
    for (int g = 1; g <= cc; g++) {
        std::string key = (g < (int) names.size() && !names[g].empty()) ? names[g] : ("col_" + std::to_string(g - 1));
        if (!m.has(g)) { obj.set(key, json::Value::null()); continue; }
        std::string cap = m.str(g);
        char* endp = nullptr;
        long long iv = strtoll(cap.c_str(), &endp, 10);
        if (!cap.empty() && endp && *endp == '\0') { obj.set(key, json::Value::integer(iv)); continue; }
        double dv = strtod(cap.c_str(), &endp);
        if (!cap.empty() && endp && *endp == '\0') { obj.set(key, json::Value::number(dv)); continue; }
        obj.set(key, json::Value::string(cap));
    }
    std::string out = json::to_string(obj);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}

static void fn_regexp_replace(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string s = arg_text(argv[0]);
    bool ok; auto re = get_regex(ctx, arg_text(argv[1]), ok); if (!ok) return;
    std::string repl = arg_text(argv[2]);
    std::string out = re->replace_all(s, repl);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
}

static void fn_startswith(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    sqlite3_result_int(ctx, starts_with(arg_text(argv[0]), arg_text(argv[1])) ? 1 : 0);
}
static void fn_endswith(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    sqlite3_result_int(ctx, ends_with(arg_text(argv[0]), arg_text(argv[1])) ? 1 : 0);
}
static void fn_basename(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string p = arg_text(argv[0]);
    std::string r = basename_of(p);
    if (p.empty()) r = ".";
    sqlite3_result_text(ctx, r.c_str(), -1, SQLITE_TRANSIENT);
}
static void fn_dirname(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string r = dirname_of(arg_text(argv[0]));
    sqlite3_result_text(ctx, r.c_str(), -1, SQLITE_TRANSIENT);
}
static void fn_joinpath(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    std::string out;
    for (int k = 0; k < argc; k++) {
        if (sqlite3_value_type(argv[k]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
        std::string p = arg_text(argv[k]);
        if (!p.empty() && p[0] == '/') out = p;
        else if (out.empty()) out = p;
        else { if (out.back() != '/') out += '/'; out += p; }
    }
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
}
static void fn_readlink(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
