static void fn_reverse(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string s = arg_text(argv[0]);
    // reverse by code points
    std::vector<std::string> cps;
    size_t i = 0;
    while (i < s.size()) {
        size_t start = i;
        unsigned char c = (unsigned char) s[i];
        int n = c < 0x80 ? 1 : (c & 0xE0) == 0xC0 ? 2 : (c & 0xF0) == 0xE0 ? 3 : (c & 0xF8) == 0xF0 ? 4 : 1;
        i += n; if (i > s.size()) i = s.size();
        cps.push_back(s.substr(start, i - start));
    }
    std::string r;
    for (auto it = cps.rbegin(); it != cps.rend(); ++it) r += *it;
    sqlite3_result_text(ctx, r.c_str(), -1, SQLITE_TRANSIENT);
}
