static void fn_timeslice(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string ts = arg_text(argv[0]);
    std::string slice = argc > 1 && sqlite3_value_type(argv[1]) != SQLITE_NULL ? arg_text(argv[1]) : "15m";
    date_time_scanner dts;
    exttm tm; struct timeval tv {0, 0};
    if (!dts.scan(ts.data(), ts.size(), nullptr, &tm, tv)) { std::string e = "Unable to parse time slice value: " + ts; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    // parse duration
    int64_t secs = 0;
    {
        size_t i = 0; int64_t total = 0;
        while (i < slice.size()) {
            while (i < slice.size() && isspace((unsigned char) slice[i])) i++;
            int64_t v = 0; bool got = false;
            while (i < slice.size() && isdigit((unsigned char) slice[i])) { v = v * 10 + (slice[i] - '0'); i++; got = true; }
            if (!got) break;
            while (i < slice.size() && isspace((unsigned char) slice[i])) i++;
            std::string unit;
            while (i < slice.size() && isalpha((unsigned char) slice[i])) { unit += slice[i]; i++; }
            if (unit.empty() || unit[0] == 's') total += v;
            else if (unit[0] == 'm') total += v * 60;
            else if (unit[0] == 'h') total += v * 3600;
            else if (unit[0] == 'd') total += v * 86400;
            else if (unit[0] == 'w') total += v * 604800;
            else { std::string e = "Unable to parse time slice value: " + slice; sqlite3_result_error(ctx, e.c_str(), -1); return; }
        }
        secs = total;
    }
    if (secs <= 0) { std::string e = "Unable to parse time slice value: " + slice; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    time_t t = tv.tv_sec - (tv.tv_sec % secs);
    struct timeval out {t, 0};
    std::string r = format_log_time(out);
    r = r.substr(0, 19) + ".000";
    sqlite3_result_text(ctx, r.c_str(), -1, SQLITE_TRANSIENT);
}
