    date_time_scanner dts;
    exttm tm1, tm2; struct timeval tv1 {0, 0}, tv2 {0, 0};
    if (!dts.scan(a.data(), a.size(), nullptr, &tm1, tv1)) { sqlite3_result_null(ctx); return; }
    date_time_scanner dts2;
    if (!dts2.scan(b.data(), b.size(), nullptr, &tm2, tv2)) { sqlite3_result_null(ctx); return; }
    double d = (double) (tv1.tv_sec - tv2.tv_sec) + (double) (tv1.tv_usec - tv2.tv_usec) / 1e6;
    sqlite3_result_double(ctx, d);
}
