    struct addrinfo hints {}, *res = nullptr;
    hints.ai_family = AF_UNSPEC;
    if (getaddrinfo(name.c_str(), nullptr, &hints, &res) != 0 || !res) { sqlite3_result_text(ctx, name.c_str(), -1, SQLITE_TRANSIENT); return; }
    char buf[INET6_ADDRSTRLEN] = {0};
    if (res->ai_family == AF_INET) inet_ntop(AF_INET, &((struct sockaddr_in*) res->ai_addr)->sin_addr, buf, sizeof(buf));
    else inet_ntop(AF_INET6, &((struct sockaddr_in6*) res->ai_addr)->sin6_addr, buf, sizeof(buf));
    freeaddrinfo(res);
    sqlite3_result_text(ctx, buf, -1, SQLITE_TRANSIENT);
}
