static void fn_jget(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string js = arg_text(argv[0]);
    std::string path = argc > 1 && sqlite3_value_type(argv[1]) != SQLITE_NULL ? arg_text(argv[1]) : "";
    json::Value v;
    try { v = json::parse(js); } catch (...) { std::string e = "Invalid JSON: " + js; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    const json::Value* cur = &v;
    if (!path.empty() && path != "/") {
        if (path[0] != '/') { std::string e = "JSON pointer must start with a '/'"; sqlite3_result_error(ctx, e.c_str(), -1); return; }
        auto parts = split(path.substr(1), '/');
        for (auto& p : parts) {
            std::string key = replace_all(replace_all(p, "~1", "/"), "~0", "~");
            if (cur->is_object()) { cur = cur->get(key); if (!cur) { if (argc > 2) { sqlite3_result_value(ctx, argv[2]); } else sqlite3_result_null(ctx); return; } }
            else if (cur->is_array()) { char* e; long idx = strtol(key.c_str(), &e, 10); if (*e || idx < 0 || (size_t) idx >= cur->size()) { if (argc > 2) sqlite3_result_value(ctx, argv[2]); else sqlite3_result_null(ctx); return; } cur = &(*cur)[idx]; }
            else { if (argc > 2) sqlite3_result_value(ctx, argv[2]); else sqlite3_result_null(ctx); return; }
        }
    }
    switch (cur->type) {
    case json::Value::Null: if (argc > 2) sqlite3_result_value(ctx, argv[2]); else sqlite3_result_null(ctx); break;
    case json::Value::Bool: sqlite3_result_int(ctx, cur->b ? 1 : 0); break;
    case json::Value::Int: sqlite3_result_int64(ctx, cur->i); break;
    case json::Value::Double: sqlite3_result_double(ctx, cur->d); break;
    case json::Value::String: sqlite3_result_text(ctx, cur->s.c_str(), -1, SQLITE_TRANSIENT); break;
    default: { std::string s = json::to_string(*cur); sqlite3_result_text(ctx, s.c_str(), -1, SQLITE_TRANSIENT); sqlite3_result_subtype(ctx, 'J'); break; }
    }
}
static void fn_json_concat(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    json::Value arr = json::Value::array();
    if (sqlite3_value_type(argv[0]) != SQLITE_NULL) {
        try { json::Value v = json::parse(arg_text(argv[0])); if (v.is_array()) arr = v; else arr.push(v); } catch (...) { arr.push(json::Value::string(arg_text(argv[0]))); }
    }
    for (int k = 1; k < argc; k++) {
        switch (sqlite3_value_type(argv[k])) {
        case SQLITE_NULL: arr.push(json::Value::null()); break;
        case SQLITE_INTEGER: arr.push(json::Value::integer(sqlite3_value_int64(argv[k]))); break;
        case SQLITE_FLOAT: arr.push(json::Value::number(sqlite3_value_double(argv[k]))); break;
        default: {
            std::string s = arg_text(argv[k]);
            if (sqlite3_value_subtype(argv[k]) == 'J') { try { arr.push(json::parse(s)); break; } catch (...) {} }
            arr.push(json::Value::string(s));
        }
        }
    }
    std::string out = json::to_string(arr);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
static void fn_json_contains(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_int(ctx, 0); return; }
    json::Value v;
    try { v = json::parse(arg_text(argv[0])); } catch (...) { sqlite3_result_error(ctx, "Invalid JSON", -1); return; }
    bool found = false;
    std::function<void(const json::Value&)> walk = [&](const json::Value& n) {
        if (found) return;
        switch (sqlite3_value_type(argv[1])) {
        case SQLITE_INTEGER: if (n.type == json::Value::Int && n.i == sqlite3_value_int64(argv[1])) found = true; if (n.type == json::Value::Double && n.d == (double) sqlite3_value_int64(argv[1])) found = true; break;
        case SQLITE_FLOAT: if (n.is_number() && n.num() == sqlite3_value_double(argv[1])) found = true; break;
        case SQLITE_TEXT: if (n.is_string() && n.s == arg_text(argv[1])) found = true; break;
        case SQLITE_NULL: if (n.is_null()) found = true; break;
        default: break;
        }
        if (n.is_array()) for (size_t k = 0; k < n.size(); k++) walk(n[k]);
        else if (n.is_object()) for (auto& kv : *n.obj) walk(kv.second);
    };
    walk(v);
    sqlite3_result_int(ctx, found ? 1 : 0);
}
static void fn_encode(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string s = arg_text(argv[0]);
    std::string alg = to_lower(arg_text(argv[1]));
    std::string out;
    if (alg == "base64") {
        static const char* tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        size_t i = 0;
        while (i + 2 < s.size()) { unsigned v = ((unsigned char) s[i] << 16) | ((unsigned char) s[i + 1] << 8) | (unsigned char) s[i + 2]; out += tbl[(v >> 18) & 63]; out += tbl[(v >> 12) & 63]; out += tbl[(v >> 6) & 63]; out += tbl[v & 63]; i += 3; }
        if (i + 1 == s.size()) { unsigned v = (unsigned char) s[i] << 16; out += tbl[(v >> 18) & 63]; out += tbl[(v >> 12) & 63]; out += "=="; }
        else if (i + 2 == s.size()) { unsigned v = ((unsigned char) s[i] << 16) | ((unsigned char) s[i + 1] << 8); out += tbl[(v >> 18) & 63]; out += tbl[(v >> 12) & 63]; out += tbl[(v >> 6) & 63]; out += '='; }
    } else if (alg == "hex") {
        char buf[4]; for (unsigned char c : s) { snprintf(buf, sizeof(buf), "%02x", c); out += buf; }
    } else if (alg == "uri") {
        for (unsigned char c : s) { if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') out += (char) c; else { char buf[4]; snprintf(buf, sizeof(buf), "%%%02X", c); out += buf; } }
    } else { std::string e = "Unknown encoding: " + alg; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
}
static void fn_decode(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string s = arg_text(argv[0]);
    std::string alg = to_lower(arg_text(argv[1]));
    std::string out;
    if (alg == "base64") {
        auto val = [](char c) -> int { if (c >= 'A' && c <= 'Z') return c - 'A'; if (c >= 'a' && c <= 'z') return c - 'a' + 26; if (c >= '0' && c <= '9') return c - '0' + 52; if (c == '+') return 62; if (c == '/') return 63; return -1; };
        unsigned acc = 0; int bits = 0;
        for (char c : s) { if (c == '=') break; int v = val(c); if (v < 0) continue; acc = (acc << 6) | v; bits += 6; if (bits >= 8) { bits -= 8; out += (char) ((acc >> bits) & 0xff); } }
        sqlite3_result_blob(ctx, out.data(), (int) out.size(), SQLITE_TRANSIENT);
        return;
    } else if (alg == "hex") {
        for (size_t i = 0; i + 1 < s.size(); i += 2) { out += (char) strtol(s.substr(i, 2).c_str(), nullptr, 16); }
        sqlite3_result_blob(ctx, out.data(), (int) out.size(), SQLITE_TRANSIENT);
        return;
    } else if (alg == "uri") {
        for (size_t i = 0; i < s.size(); i++) { if (s[i] == '%' && i + 2 < s.size()) { out += (char) strtol(s.substr(i + 1, 2).c_str(), nullptr, 16); i += 2; } else if (s[i] == '+') out += ' '; else out += s[i]; }
    } else { std::string e = "Unknown encoding: " + alg; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
}
static void fn_gzip(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
