static void fn_parse_url(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string url = arg_text(argv[0]);
    json::Value obj = json::Value::object();
    size_t p = url.find("://");
    if (p == std::string::npos) { std::string e = "invalid URL: " + url; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    obj.set("scheme", json::Value::string(url.substr(0, p)));
    std::string rest = url.substr(p + 3);
    size_t frag = rest.find('#');
    std::string fragment; if (frag != std::string::npos) { fragment = rest.substr(frag + 1); rest = rest.substr(0, frag); }
    size_t q = rest.find('?');
    std::string query; if (q != std::string::npos) { query = rest.substr(q + 1); rest = rest.substr(0, q); }
    size_t slash = rest.find('/');
    std::string authority = slash == std::string::npos ? rest : rest.substr(0, slash);
    std::string path = slash == std::string::npos ? "/" : rest.substr(slash);
    std::string user, pass, host, port;
    size_t at = authority.rfind('@');
    if (at != std::string::npos) { std::string ui = authority.substr(0, at); authority = authority.substr(at + 1); size_t c = ui.find(':'); if (c != std::string::npos) { user = ui.substr(0, c); pass = ui.substr(c + 1); } else user = ui; }
    size_t colon = authority.rfind(':');
    if (colon != std::string::npos && authority.find(']') == std::string::npos) { host = authority.substr(0, colon); port = authority.substr(colon + 1); } else host = authority;
    obj.set("username", user.empty() ? json::Value::null() : json::Value::string(user));
    obj.set("password", pass.empty() ? json::Value::null() : json::Value::string(pass));
    obj.set("host", host.empty() ? json::Value::null() : json::Value::string(host));
    obj.set("port", port.empty() ? json::Value::null() : json::Value::string(port));
    obj.set("path", json::Value::string(path));
    if (!query.empty()) {
        json::Value qo = json::Value::object();
        for (auto& kv : split(query, '&')) { size_t e = kv.find('='); if (e == std::string::npos) qo.set(kv, json::Value::null()); else qo.set(kv.substr(0, e), json::Value::string(kv.substr(e + 1))); }
        obj.set("query", qo);
    } else obj.set("query", json::Value::null());
    obj.set("fragment", fragment.empty() ? json::Value::null() : json::Value::string(fragment));
    std::string out = json::to_string(obj);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
static void fn_unparse_url(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    json::Value obj;
    try { obj = json::parse(arg_text(argv[0])); } catch (...) { sqlite3_result_error(ctx, "Invalid JSON", -1); return; }
    std::string out;
    auto gs = [&](const char* k) -> std::string { auto* v = obj.get(k); return v && v->is_string() ? v->s : ""; };
    out = gs("scheme") + "://";
    if (!gs("username").empty()) { out += gs("username"); if (!gs("password").empty()) out += ":" + gs("password"); out += "@"; }
    out += gs("host");
    if (!gs("port").empty()) out += ":" + gs("port");
    out += gs("path");
    auto* qv = obj.get("query");
    if (qv && qv->is_object() && qv->size()) { out += "?"; bool first = true; for (auto& kv : *qv->obj) { if (!first) out += "&"; first = false; out += kv.first; if (!kv.second.is_null()) out += "=" + (kv.second.is_string() ? kv.second.s : json::to_string(kv.second)); } }
    if (!gs("fragment").empty()) out += "#" + gs("fragment");
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
}
