    if (!a) { sqlite3_result_text(ctx, "", -1, SQLITE_STATIC); return; }
    static const char* bars[] = {" ", "\xe2\x96\x81", "\xe2\x96\x82", "\xe2\x96\x83", "\xe2\x96\x84", "\xe2\x96\x85", "\xe2\x96\x86", "\xe2\x96\x87", "\xe2\x96\x88"};
