// regexp_capture table-valued function
struct rc_vtab { sqlite3_vtab base; };
struct rc_cursor {
    sqlite3_vtab_cursor base;
    struct row { int64_t match_index, capture_index; std::string name; int64_t count, start, stop; std::string content; bool null_content; };
    std::vector<row> rows; size_t pos = 0; std::string value, pattern; bool into_json = false; std::vector<std::string> json_rows;
};
static int rc_connect(sqlite3* db, void* aux, int, const char* const*, sqlite3_vtab** pp, char**)
{
    bool into_json = aux != nullptr;
    int rc = sqlite3_declare_vtab(db, into_json ? "CREATE TABLE x(match_index INTEGER, content TEXT, value TEXT HIDDEN, pattern TEXT HIDDEN, flags TEXT HIDDEN)" :
        "CREATE TABLE x(match_index INTEGER, capture_index INTEGER, capture_name TEXT, capture_count INTEGER, range_start INTEGER, range_stop INTEGER, content TEXT, value TEXT HIDDEN, pattern TEXT HIDDEN)");
    if (rc != SQLITE_OK) return rc;
    auto* t = new rc_vtab(); memset(&t->base, 0, sizeof(t->base)); *pp = &t->base; return SQLITE_OK;
}
static int rc_disconnect(sqlite3_vtab* v) { delete (rc_vtab*) v; return SQLITE_OK; }
static int rc_best_index(sqlite3_vtab* v, sqlite3_index_info* info)
{
    (void) v;
    int argi = 1;
    bool into_json = false;
    for (int k = 0; k < info->nConstraint; k++) {
        auto& c = info->aConstraint[k];
        if (!c.usable || c.op != SQLITE_INDEX_CONSTRAINT_EQ) continue;
        // hidden columns: value, pattern (7,8) or (2,3) for json
        if (c.iColumn == 7 || c.iColumn == 2) { info->aConstraintUsage[k].argvIndex = 1; info->aConstraintUsage[k].omit = 1; }
        else if (c.iColumn == 8 || c.iColumn == 3) { info->aConstraintUsage[k].argvIndex = 2; info->aConstraintUsage[k].omit = 1; }
        else if (c.iColumn == 4 && into_json) { info->aConstraintUsage[k].argvIndex = 3; info->aConstraintUsage[k].omit = 1; }
    }
    (void) argi;
    info->estimatedCost = 10.0;
    return SQLITE_OK;
}
static int rc_open(sqlite3_vtab*, sqlite3_vtab_cursor** pp) { auto* c = new rc_cursor(); memset(&c->base, 0, sizeof(c->base)); *pp = &c->base; return SQLITE_OK; }
