static int rc_filter_impl(sqlite3_vtab_cursor* pc, int, const char*, int argc, sqlite3_value** argv, bool into_json)
{
    auto* c = (rc_cursor*) pc;
    c->rows.clear(); c->json_rows.clear(); c->pos = 0; c->into_json = into_json;
    if (argc < 2) return SQLITE_OK;
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) return SQLITE_OK;
    c->value = arg_text(argv[0]); c->pattern = arg_text(argv[1]);
    std::shared_ptr<Regex> re;
    try { re = std::make_shared<Regex>(c->pattern); } catch (regex_error& e) { pc->pVtab->zErrMsg = sqlite3_mprintf("Invalid regular expression: %s", e.what()); return SQLITE_ERROR; }
    size_t pos = 0; int64_t mi = 0;
    Regex::Match m;
    while (pos <= c->value.size() && re->match(c->value, m, pos)) {
        int cc = re->capture_count();
        if (into_json) {
            json::Value obj = json::Value::object();
            for (int g = 1; g <= cc; g++) {
                std::string key = (g < (int) re->names().size() && !re->names()[g].empty()) ? re->names()[g] : ("col_" + std::to_string(g - 1));
                if (!m.has(g)) { obj.set(key, json::Value::null()); continue; }
                std::string cap = m.str(g); char* e; long long iv = strtoll(cap.c_str(), &e, 10);
                if (!cap.empty() && *e == 0) obj.set(key, json::Value::integer(iv)); else { double dv = strtod(cap.c_str(), &e); if (!cap.empty() && *e == 0) obj.set(key, json::Value::number(dv)); else obj.set(key, json::Value::string(cap)); }
            }
            c->json_rows.push_back(json::to_string(obj));
            c->rows.push_back({mi, 0, "", cc, (int64_t) m.start(0), (int64_t) m.end(0), "", false});
        } else {
            for (int g = 0; g <= cc; g++) {
                rc_cursor::row r;
                r.match_index = mi; r.capture_index = g; r.name = g < (int) re->names().size() ? re->names()[g] : ""; r.count = cc + 1;
                if (m.has(g)) { r.start = (int64_t) m.start(g); r.stop = (int64_t) m.end(g); r.content = m.str(g); r.null_content = false; }
                else { r.start = -1; r.stop = -1; r.null_content = true; }
                c->rows.push_back(r);
            }
        }
        mi++;
        size_t e = m.end(0);
        if (e == m.start(0)) { pos = e + 1; } else pos = e;
    }
    return SQLITE_OK;
}
static int rc_filter(sqlite3_vtab_cursor* pc, int a, const char* b, int argc, sqlite3_value** argv) { return rc_filter_impl(pc, a, b, argc, argv, false); }
static int rcj_filter(sqlite3_vtab_cursor* pc, int a, const char* b, int argc, sqlite3_value** argv) { return rc_filter_impl(pc, a, b, argc, argv, true); }
static int rc_next(sqlite3_vtab_cursor* pc) { ((rc_cursor*) pc)->pos++; return SQLITE_OK; }
static int rc_eof(sqlite3_vtab_cursor* pc) { auto* c = (rc_cursor*) pc; return c->pos >= c->rows.size(); }
