extern const char* embedded_help_text();

// ---------------------------------------------------------------------------
// Help text extraction

static std::map<std::string, std::string>& help_table()
{
    static std::map<std::string, std::string> tbl;
    static bool loaded = false;
    if (loaded) return tbl;
    loaded = true;
    std::string txt = embedded_help_text();
    auto lines = split(txt, '\n');
    size_t start = 0;
    for (size_t k = 0; k < lines.size(); k++) if (lines[k] == "Command Reference") { start = k; break; }
    for (size_t k = start; k + 2 < lines.size(); k++) {
        if (!lines[k].empty() && lines[k][0] == ':' && starts_with(lines[k + 1], "\xe2\x95\x90")) {
            std::string usage = lines[k];
            std::string name = usage.substr(1, usage.find(' ') == std::string::npos ? std::string::npos : usage.find(' ') - 1);
            std::string desc;
            size_t j = k + 2;
            while (j < lines.size() && !lines[j].empty() && lines[j][0] == ' ') { if (!desc.empty()) desc += "\n"; desc += lines[j]; j++; }
            std::string help = usage + "\n" + lines[k + 1] + "\n" + desc;
            // Only the first description paragraph
            if (!tbl.count(name)) tbl[name] = help;
        }
    }
    return tbl;
}

std::string command_help(const std::string& name)
{
    auto& t = help_table();
    auto it = t.find(name);
    if (it == t.end()) return "";
    // indent description lines by two extra spaces (they already have 2)
    auto lines = split(it->second, '\n');
    std::string out;
    for (size_t k = 0; k < lines.size(); k++) {
        if (k == 0) out += lines[k];
        else if (k == 1) out += "\n" + lines[k];
        else out += "\n  " + lines[k];
    }
    return out;
}

