struct cmd_context {
    lnav_app& app;
    std::string source;
    int source_line;
    std::string cmdline;   // full command text including ':'
    std::string name;
    std::string args;      // rest after command name
    std::vector<std::string> argv;
    app_error err;
    bool has_error = false;
    std::string output;    // informational message (not printed in headless unless echo)
    void error(const std::string& msg, const std::string& reason = "") {
        has_error = true;
        err.msg = msg; err.reason = reason;
        err.snippet_source = source + ":" + std::to_string(source_line);
        err.snippet_text = cmdline;
        std::string h = command_help(name);
        if (!h.empty()) err.helps.push_back(h);
    }
};

static void report_error(cmd_context& c)
{
    print_error(c.err);
}

static bool parse_int(const std::string& s, int64_t& out)
{
    if (s.empty()) return false;
    char* e = nullptr;
    long long v = strtoll(s.c_str(), &e, 10);
    if (*e) return false;
    out = v;
    return true;
}

static size_t view_row_count(lnav_app& app)
{
    if (app.current_view == "log") return app.log_row_count();
    if (app.current_view == "text") return app.text_view_lines().size();
    if (app.current_view == "db") return app.last_result.valid ? app.last_result.rows.size() : 0;
    return 0;
}

static size_t& view_top(lnav_app& app)
{
    if (app.current_view == "text") return app.text_top;
    if (app.current_view == "db") return app.db_top;
    return app.log_top;
}

static std::vector<std::string> view_lines(lnav_app& app)
{
    std::vector<std::string> out;
    if (app.current_view == "log") {
        std::string s = app.render_log_view();
        if (!s.empty()) { if (s.back() == '\n') s.pop_back(); out = split(s, '\n'); }
    } else if (app.current_view == "text") {
        out = app.text_view_lines();
    } else if (app.current_view == "db") {
        std::string s = render_db_result(app);
        if (!s.empty()) { if (s.back() == '\n') s.pop_back(); out = split(s, '\n'); }
    }
    return out;
}

// Open an output destination: "-" is stdout, "/dev/stdout", or a file.
struct out_dest {
    FILE* fp = nullptr;
    bool is_stdout = false;
    bool ok = false;
    std::string error;
};

static out_dest open_dest(cmd_context& c, const std::string& path, bool append = false)
{
    out_dest d;
    if (path == "-" || path == "/dev/stdout") { d.fp = stdout; d.is_stdout = true; d.ok = true; c.app.produced_output = true; return d; }
    if (path == "/dev/stderr") { d.fp = stderr; d.is_stdout = true; d.ok = true; return d; }
    d.fp = fopen(path.c_str(), append ? "a" : "w");
    if (!d.fp) { d.error = strerror(errno); return d; }
    d.ok = true;
    return d;
}

static void close_dest(out_dest& d)
{
    if (d.fp && !d.is_stdout) fclose(d.fp);
    else if (d.fp) fflush(d.fp);
}

static std::vector<size_t> marked_rows(lnav_app& app)
{
    std::vector<size_t> rows;
    if (app.current_view == "log") {
        for (auto& ve : app.log_visible) {
            auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
            if (m.marked) rows.push_back(ve.row_start);
        }
    }
    return rows;
}

static std::string csv_quote(const std::string& s)
{
    bool need = s.find_first_of(",\"\n\r") != std::string::npos;
    if (!need) return s;
    std::string out = "\"";
    for (char ch : s) { if (ch == '"') out += "\"\""; else out += ch; }
    out += "\"";
    return out;
}

static json::Value cell_to_json(lnav_app::db_result& r, size_t ri, size_t ci)
{
    int t = r.row_types[ri][ci];
    switch (t) {
    case 1: return json::Value::integer(r.row_ints[ri][ci]);  // SQLITE_INTEGER
    case 2: return json::Value::number(r.row_nums[ri][ci]);
    case 3: {
        // text; if it has JSON subtype we can't know here, try to parse objects/arrays
        const std::string& s = r.rows[ri][ci];
        return json::Value::string(s);
    }
    case 4: return json::Value::string(r.rows[ri][ci]);
    default: return json::Value::null();
    }
}

static std::string table_line(const std::vector<std::string>& cells, const std::vector<size_t>& widths, const std::vector<bool>& right, const char* left_b, const char* sep, const char* right_b, bool bold)
{
    std::string out = left_b;
    for (size_t c = 0; c < cells.size(); c++) {
        if (c) out += sep;
        std::string cell = right[c] ? pad_left(cells[c], (int) widths[c]) : pad_right(cells[c], (int) widths[c]);
        if (bold) out += "\x1b[1m" + cell + "\x1b[0m"; else out += cell;
    }
    out += right_b;
    return out;
}

static bool cmd_write_generic(cmd_context& c, const std::string& kind)
{
    lnav_app& app = c.app;
    std::vector<std::string> args = c.argv;
    bool anonymize = false;
    if (!args.empty() && args[0] == "--anonymize") { anonymize = true; args.erase(args.begin()); }
    (void) anonymize;
    if (args.empty()) { c.error("expecting file name or '-' to write to the terminal"); return false; }
    std::string path = args[0];
    bool is_db = app.last_output_was_db && app.last_result.valid;
    if (kind == "csv" || kind == "json" || kind == "jsonlines" || kind == "table" || kind == "raw") {
        if (!is_db && kind != "raw") {
            // these operate on db view results
            if (!app.last_result.valid) { c.error("no query result to write, use ';' to execute a query"); return false; }
        }
    }
    if (kind == "to" || kind == "append") {
        auto rows = marked_rows(app);
        if (rows.empty() && !is_db) { c.error("no lines marked to write, use 'm' to mark lines"); return false; }
        auto d = open_dest(c, path, kind == "append");
        if (!d.ok) { c.error("unable to open file: " + path, d.error); return false; }
        if (is_db) { fputs(render_db_result(app).c_str(), d.fp); }
        else {
            auto lines = view_lines(app);
            for (auto& ve : app.log_visible) {
                auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
                if (!m.marked) continue;
                for (size_t k = 0; k < ve.row_count && ve.row_start + k < lines.size(); k++) { fputs(lines[ve.row_start + k].c_str(), d.fp); fputc('\n', d.fp); }
            }
        }
        close_dest(d);
        return true;
    }
    if (kind == "view" || kind == "screen") {
        auto d = open_dest(c, path);
        if (!d.ok) { c.error("unable to open file: " + path, d.error); return false; }
        if (is_db) fputs(render_db_result(app).c_str(), d.fp);
        else { for (auto& l : view_lines(app)) { fputs(l.c_str(), d.fp); fputc('\n', d.fp); } }
        close_dest(d);
        return true;
    }
    auto& r = app.last_result;
    if (kind == "raw") {
        auto d = open_dest(c, path);
        if (!d.ok) { c.error("unable to open file: " + path, d.error); return false; }
        if (is_db) {
            for (size_t ri = 0; ri < r.rows.size(); ri++) {
                std::string line;
                for (size_t ci = 0; ci < r.headers.size(); ci++) line += r.row_types[ri][ci] == 5 ? "<NULL>" : r.rows[ri][ci];
                fputs(line.c_str(), d.fp); fputc('\n', d.fp);
            }
        } else {
            auto rows = marked_rows(app);
            if (rows.empty()) { close_dest(d); c.error("no lines marked to write, use 'm' to mark lines"); return false; }
            for (auto& ve : app.log_visible) {
                auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
                if (!m.marked) continue;
                fputs(app.files[ve.file_idx]->message_text(m).c_str(), d.fp); fputc('\n', d.fp);
            }
        }
        close_dest(d);
        return true;
    }
    auto d = open_dest(c, path);
    if (!d.ok) { c.error("unable to open file: " + path, d.error); return false; }
    if (kind == "csv") {
        std::string line;
        for (size_t ci = 0; ci < r.headers.size(); ci++) { if (ci) line += ","; line += csv_quote(r.headers[ci]); }
        fputs(line.c_str(), d.fp); fputc('\n', d.fp);
        for (size_t ri = 0; ri < r.rows.size(); ri++) {
            line.clear();
            for (size_t ci = 0; ci < r.headers.size(); ci++) { if (ci) line += ","; line += r.row_types[ri][ci] == 5 ? "<NULL>" : csv_quote(r.rows[ri][ci]); }
            fputs(line.c_str(), d.fp); fputc('\n', d.fp);
        }
    } else if (kind == "json") {
        json::Value arr = json::Value::array();
        for (size_t ri = 0; ri < r.rows.size(); ri++) {
            json::Value obj = json::Value::object();
            for (size_t ci = 0; ci < r.headers.size(); ci++) obj.set(r.headers[ci], cell_to_json(r, ri, ci));
            arr.push(obj);
        }
        std::string out = json::to_string(arr, 4);
        fputs(out.c_str(), d.fp); fputc('\n', d.fp);
    } else if (kind == "jsonlines") {
        for (size_t ri = 0; ri < r.rows.size(); ri++) {
            json::Value obj = json::Value::object();
            for (size_t ci = 0; ci < r.headers.size(); ci++) obj.set(r.headers[ci], cell_to_json(r, ri, ci));
            std::string out = json::to_string(obj);
            fputs(out.c_str(), d.fp); fputc('\n', d.fp);
        }
    } else if (kind == "table") {
        size_t nc = r.headers.size();
        std::vector<size_t> widths(nc, 0);
        std::vector<bool> right(nc, false);
        std::vector<std::vector<std::string>> cells(r.rows.size(), std::vector<std::string>(nc));
        for (size_t ci = 0; ci < nc; ci++) {
            widths[ci] = utf8_width(r.headers[ci]);
            bool graphable = false;
            if (!r.rows.empty()) {
                int t = r.row_types[0][ci];
                if (t == 1 || t == 2) graphable = true;
                if (graphable && formats().key_names.count(r.headers[ci])) graphable = false;
            }
            if (graphable && widths[ci] < 10) widths[ci] = 10;
            for (size_t ri = 0; ri < r.rows.size(); ri++) {
                int t = r.row_types[ri][ci];
                std::string cell = t == 5 ? "<NULL>" : scrub_control_chars(r.rows[ri][ci]);
                if (t == 1 || t == 2) right[ci] = true;
                else if (t == 3 && !r.rows[ri][ci].empty() && isdigit((unsigned char) r.rows[ri][ci][0])) right[ci] = true;
                widths[ci] = std::max(widths[ci], (size_t) utf8_width(cell));
                cells[ri][ci] = cell;
            }
        }
        auto bar = [&](const char* l, const char* m, const char* rr, const char* fill) {
            std::string out = l;
            for (size_t ci = 0; ci < nc; ci++) { if (ci) out += m; for (size_t k = 0; k < widths[ci]; k++) out += fill; }
            out += rr; return out;
        };
        std::string out;
        out += bar("\xe2\x94\x8f", "\xe2\x94\xb3", "\xe2\x94\x93", "\xe2\x94\x81") + "\n";
        std::vector<std::string> hdrs;
        for (size_t ci = 0; ci < nc; ci++) hdrs.push_back(pad_center(r.headers[ci], (int) widths[ci]));
        std::vector<bool> noright(nc, false);
        out += table_line(hdrs, widths, noright, "\xe2\x94\x83", "\xe2\x94\x83", "\xe2\x94\x83", true) + "\n";
        out += bar("\xe2\x94\xa1", "\xe2\x95\x87", "\xe2\x94\xa9", "\xe2\x94\x81") + "\n";
        for (size_t ri = 0; ri < r.rows.size(); ri++) out += table_line(cells[ri], widths, right, "\xe2\x94\x82", "\xe2\x94\x82", "\xe2\x94\x82", false) + "\n";
        out += bar("\xe2\x94\x94", "\xe2\x94\xb4", "\xe2\x94\x98", "\xe2\x94\x81") + "\n";
        fputs(out.c_str(), d.fp);
    }
    close_dest(d);
    return true;
}

static bool add_filter(cmd_context& c, bool out)
{
    lnav_app& app = c.app;
    std::string pat = c.args;
    if (pat.empty()) { c.error("expecting a regular expression to filter " + std::string(out ? "out" : "in")); return false; }
    text_filter f;
    f.id = app.next_filter_id++;
    f.out = out;
    f.pattern = pat;
    try { f.re = std::make_shared<Regex>(pat, PCRE2_CASELESS * 0); }
    catch (regex_error& e) {
        c.error("invalid regular expression: " + std::string(e.what()));
        return false;
    }
    auto& filters = app.current_view == "text" ? app.text_filters : app.log_filters;
    for (auto& ef : filters) if (ef.pattern == pat && ef.out == out) { c.error("filter already exists -- " + pat); return false; }
    filters.push_back(f);
    app.apply_filters();
    return true;
}

static bool goto_location(cmd_context& c, const std::string& arg)
{
    lnav_app& app = c.app;
    size_t count = view_row_count(app);
    size_t& top = view_top(app);
    if (arg.empty()) { c.error("expecting line number/percentage, timestamp, or relative time"); return false; }
    if (arg[0] == '#') {
        c.error("invalid argument: " + arg, "expecting line number/percentage, timestamp, or relative time");
        return false;
    }
    if (arg.back() == '%') {
        int64_t pct;
        if (!parse_int(arg.substr(0, arg.size() - 1), pct)) { c.error("invalid argument: " + arg, "expecting line number/percentage, timestamp, or relative time"); return false; }
        if (count == 0) { top = 0; return true; }
        double frac = (double) pct / 100.0;
        size_t row = (size_t) ((double) count * frac);
        if (row >= count) row = count - 1;
        top = row;
        return true;
    }
    int64_t n;
    if (parse_int(arg, n)) {
        if (count == 0) { top = 0; return true; }
        int64_t row = n < 0 ? (int64_t) count + n : n;
        if (row < 0) row = 0;
        if ((size_t) row >= count) row = count - 1;
        top = (size_t) row;
        return true;
    }
    // timestamp
    date_time_scanner dts;
    exttm tm; struct timeval tv {0, 0};
    if (app.current_view == "log" && dts.scan(arg.data(), arg.size(), nullptr, &tm, tv)) {
        // relative to the current year if year not set
        if (!(tm.et_flags & exttm::ETF_YEAR_SET) && !app.log_visible.empty()) {
            // use year of the top line
            const view_entry* ve = app.entry_for_row(std::min(top, count - 1));
            if (ve) {
                auto& m = app.files[ve->file_idx]->messages[ve->msg_idx];
                struct tm bt; time_t bts = m.tv.tv_sec; gmtime_r(&bts, &bt);
                tm.et_tm.tm_year = bt.tm_year;
                if (!(tm.et_flags & exttm::ETF_MONTH_SET)) { tm.et_tm.tm_mon = bt.tm_mon; tm.et_tm.tm_mday = bt.tm_mday; }
                tv.tv_sec = tm2sec(&tm.et_tm);
            }
        }
        // find first row with time >= tv
        size_t row = count ? count - 1 : 0;
        for (auto& ve : app.log_visible) {
            auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
            if (m.tv.tv_sec > tv.tv_sec || (m.tv.tv_sec == tv.tv_sec && m.tv.tv_usec >= tv.tv_usec)) { row = ve.row_start; break; }
        }
        top = row;
        return true;
    }
    c.error("invalid argument: " + arg, "expecting line number/percentage, timestamp, or relative time");
    return false;
}

static bool exec_single(cmd_context& c);

static bool run_script_file(lnav_app& app, const std::string& path, cmd_context& c)
{
    bool ok;
    std::string content = read_file(path, ok);
    if (!ok) { c.error("unknown script -- " + path + " -- file not found"); return false; }
    auto lines = split(content, '\n');
    int lineno = 0;
    std::string pending;
    for (size_t k = 0; k < lines.size(); k++) {
        lineno++;
        std::string l = lines[k];
        if (l.empty() && pending.empty()) continue;
        if (!pending.empty()) {
            // continuation of multi-line SQL
            if (l.empty()) { execute_command_line(app, pending, path, lineno - 1); pending.clear(); continue; }
            pending += "\n" + l;
            continue;
        }
        if (l[0] == '#') continue;
        if (l[0] == ';') {
            // SQL may span lines until a blank line or next command prefix
            pending = l;
            continue;
        }
        execute_command_line(app, l, path, lineno);
    }
    if (!pending.empty()) execute_command_line(app, pending, path, lineno);
    return true;
}

static bool exec_single(cmd_context& c)
{
    lnav_app& app = c.app;
    const std::string& n = c.name;
    auto& argv = c.argv;
    auto need_args = [&](size_t k, const char* msg) -> bool { if (argv.size() < k) { c.error(msg); return false; } return true; };

    if (n == "echo") {
        bool nl = true;
        std::string msg = c.args;
        if (starts_with(msg, "-n ")) { nl = false; msg = msg.substr(3); }
        else if (msg == "-n") { nl = false; msg = ""; }
        fputs(msg.c_str(), stdout);
        if (nl) fputc('\n', stdout);
        fflush(stdout);
        app.produced_output = true;
        return true;
    }
    if (n == "goto") {
        if (argv.empty()) { c.error("expecting line number/percentage, timestamp, or relative time"); return false; }
        return goto_location(c, c.args);
    }
    if (n == "relative-goto") {
        if (argv.empty()) { c.error("expecting line number/percentage"); return false; }
        std::string a = argv[0];
        size_t count = view_row_count(app);
        size_t& top = view_top(app);
        int64_t v;
        bool pct = !a.empty() && a.back() == '%';
        if (!parse_int(pct ? a.substr(0, a.size() - 1) : a, v)) { c.error("invalid argument: " + a); return false; }
        int64_t delta = pct ? (int64_t) ((double) count * (double) v / 100.0) : v;
        int64_t row = (int64_t) top + delta;
        if (row < 0) row = 0;
        if (count && (size_t) row >= count) row = count - 1;
        top = (size_t) row;
        return true;
    }
    if (n == "filter-in") return add_filter(c, false);
    if (n == "filter-out") return add_filter(c, true);
    if (n == "delete-filter") {
        if (c.args.empty()) { c.error("expecting a filter to delete"); return false; }
        auto& filters = app.current_view == "text" ? app.text_filters : app.log_filters;
        for (size_t k = 0; k < filters.size(); k++) if (filters[k].pattern == c.args) { filters.erase(filters.begin() + k); app.apply_filters(); return true; }
        c.error("unknown filter -- " + c.args);
        return false;
    }
    if (n == "enable-filter" || n == "disable-filter") {
        if (c.args.empty()) { c.error("expecting a filter to " + std::string(n == "enable-filter" ? "enable" : "disable")); return false; }
        auto& filters = app.current_view == "text" ? app.text_filters : app.log_filters;
        for (auto& f : filters) if (f.pattern == c.args) { f.enabled = (n == "enable-filter"); app.apply_filters(); return true; }
        c.error("unknown filter -- " + c.args);
        return false;
    }
    if (n == "filter-expr") {
        if (c.args.empty()) { c.error("expecting an SQL expression"); return false; }
        // evaluate the expression per log message using the log table columns
        std::string expr = c.args;
        // validate
        {
            std::string sql = "SELECT 1 FROM all_logs WHERE " + expr + " LIMIT 0";
            sqlite3_stmt* stmt = nullptr;
            if (sqlite3_prepare_v2(app.db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
                c.error("invalid filter expression", sqlite3_errmsg(app.db));
                return false;
            }
            sqlite3_finalize(stmt);
        }
        app.filter_expr = expr;
        // apply: compute matching rows through SQL on all_logs
        std::set<int64_t> keep;
        {
            std::string sql = "SELECT log_line FROM all_logs WHERE " + expr;
            sqlite3_stmt* stmt = nullptr;
            // temporarily clear existing expr effect
            if (sqlite3_prepare_v2(app.db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
                while (sqlite3_step(stmt) == SQLITE_ROW) keep.insert(sqlite3_column_int64(stmt, 0));
                sqlite3_finalize(stmt);
            }
        }
        std::vector<view_entry> vis;
        size_t row = 0;
        for (auto& ve : app.log_visible) {
            if (!keep.count((int64_t) ve.row_start)) continue;
            view_entry v = ve; v.row_start = row; row += v.row_count; vis.push_back(v);
        }
        app.log_visible = vis;
        return true;
    }
    if (n == "clear-filter-expr") { app.filter_expr.clear(); app.apply_filters(); return true; }
    if (n == "toggle-filtering") { return true; }
    if (n == "set-min-log-level") {
        if (argv.empty()) { c.error("expecting log level name"); return false; }
        auto lvl = string2level(argv[0], true);
        if (lvl == LEVEL_UNKNOWN && to_lower(argv[0]) != "unknown") { c.error("unknown log level -- " + argv[0]); return false; }
        app.min_level = lvl;
        app.apply_filters();
        return true;
    }
    if (n == "mark") {
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) { auto& m = app.files[ve->file_idx]->messages[ve->msg_idx]; m.marked = !m.marked; }
        }
        return true;
    }
    if (n == "mark-expr") {
        if (c.args.empty()) { c.error("expecting an SQL expression"); return false; }
        std::string sql = "SELECT log_line FROM all_logs WHERE " + c.args;
        sqlite3_stmt* stmt = nullptr;
        if (sqlite3_prepare_v2(app.db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) { c.error("invalid mark expression", sqlite3_errmsg(app.db)); return false; }
        std::set<int64_t> rows;
        while (sqlite3_step(stmt) == SQLITE_ROW) rows.insert(sqlite3_column_int64(stmt, 0));
        sqlite3_finalize(stmt);
        app.mark_expr = c.args;
        for (auto& ve : app.log_visible) { auto& m = app.files[ve.file_idx]->messages[ve.msg_idx]; if (rows.count((int64_t) ve.row_start)) m.marked = true; }
        return true;
    }
    if (n == "clear-mark-expr") { app.mark_expr.clear(); return true; }
    if (n == "hide-unmarked-lines") { app.hide_unmarked = true; app.apply_filters(); return true; }
    if (n == "show-unmarked-lines") { app.hide_unmarked = false; app.apply_filters(); return true; }
    if (n == "next-mark" || n == "prev-mark") {
        std::string type = argv.empty() ? "user" : argv[0];
        size_t count = app.log_row_count();
        size_t cur = std::min(app.log_top, count ? count - 1 : 0);
        bool fwd = (n == "next-mark");
        std::vector<size_t> cands;
        for (auto& ve : app.log_visible) {
            auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
            bool hit = false;
            if (type == "user" || type == "mark") hit = m.marked;
            else if (type == "error") hit = m.level >= LEVEL_ERROR;
            else if (type == "warning") hit = m.level == LEVEL_WARNING;
            else if (type == "file") hit = (ve.row_start == 0) || (&ve != &app.log_visible.front() && (&ve)[-1].file_idx != ve.file_idx);
            else if (type == "search") hit = false;
            else if (type == "meta") hit = !m.comment.empty() || !m.tags.empty();
            if (hit) cands.push_back(ve.row_start);
        }
        if (fwd) { for (size_t r : cands) if (r > cur) { app.log_top = r; return true; } }
        else { for (auto it = cands.rbegin(); it != cands.rend(); ++it) if (*it < cur) { app.log_top = *it; return true; } }
        return true;
    }
    if (n == "switch-to-view" || n == "toggle-view") {
        if (argv.empty()) { c.error("expecting a view name"); return false; }
        static const char* views[] = {"log", "text", "help", "histogram", "db", "schema", "pretty", "spectro", "timeline", "gantt", nullptr};
        std::string v = argv[0];
        bool ok = false;
        for (int k = 0; views[k]; k++) if (v == views[k]) ok = true;
        if (!ok) { c.error("invalid view name -- " + v); return false; }
        if (n == "toggle-view" && app.current_view == v) {
            if (!app.view_stack.empty()) { app.current_view = app.view_stack.back(); app.view_stack.pop_back(); }
            return true;
        }
        if (app.current_view != v) { app.view_stack.push_back(app.current_view); app.current_view = v; }
        if (v == "db") app.last_output_was_db = app.last_result.valid;
        else app.last_output_was_db = false;
        return true;
    }
    if (n == "write-to") return cmd_write_generic(c, "to");
    if (n == "append-to") return cmd_write_generic(c, "append");
    if (n == "write-csv-to") return cmd_write_generic(c, "csv");
    if (n == "write-json-to") return cmd_write_generic(c, "json");
    if (n == "write-jsonlines-to") return cmd_write_generic(c, "jsonlines");
    if (n == "write-table-to") return cmd_write_generic(c, "table");
    if (n == "write-raw-to") return cmd_write_generic(c, "raw");
    if (n == "write-view-to") return cmd_write_generic(c, "view");
    if (n == "write-screen-to") return cmd_write_generic(c, "screen");
    if (n == "pipe-to" || n == "pipe-line-to") {
        if (c.args.empty()) { c.error("expecting command to execute"); return false; }
        std::string input;
        if (n == "pipe-line-to") {
            auto lines = view_lines(app);
            size_t count = lines.size();
            if (count) input = lines[std::min(view_top(app), count - 1)] + "\n";
        } else {
            auto lines = view_lines(app);
            if (app.last_output_was_db && app.last_result.valid) input = render_db_result(app);
            else for (auto& ve : app.log_visible) { auto& m = app.files[ve.file_idx]->messages[ve.msg_idx]; if (m.marked) for (size_t k = 0; k < ve.row_count; k++) input += lines[ve.row_start + k] + "\n"; }
            if (input.empty()) { c.error("no lines marked to write, use 'm' to mark lines"); return false; }
        }
        int inpipe[2];
        if (pipe(inpipe) != 0) { c.error("unable to create pipe"); return false; }
        pid_t pid = fork();
        if (pid == 0) {
            dup2(inpipe[0], 0); close(inpipe[0]); close(inpipe[1]);
            execl("/bin/sh", "sh", "-c", c.args.c_str(), (char*) nullptr);
            _exit(127);
        }
        close(inpipe[0]);
        size_t off = 0;
        while (off < input.size()) { ssize_t w = write(inpipe[1], input.data() + off, input.size() - off); if (w <= 0) break; off += w; }
        close(inpipe[1]);
        int status; waitpid(pid, &status, 0);
        app.produced_output = true;
        return true;
    }
    if (n == "comment") {
        if (c.args.empty()) { c.error("expecting some comment text"); return false; }
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) app.files[ve->file_idx]->messages[ve->msg_idx].comment = c.args;
        }
        return true;
    }
    if (n == "clear-comment") {
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) app.files[ve->file_idx]->messages[ve->msg_idx].comment.clear();
        }
        return true;
    }
    if (n == "tag" || n == "untag") {
        if (argv.empty()) { c.error("expecting one or more tags"); return false; }
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) {
                auto& m = app.files[ve->file_idx]->messages[ve->msg_idx];
                for (auto& t : argv) {
                    std::string tag = starts_with(t, "#") ? t : "#" + t;
                    if (n == "tag") { if (std::find(m.tags.begin(), m.tags.end(), tag) == m.tags.end()) m.tags.push_back(tag); }
                    else m.tags.erase(std::remove(m.tags.begin(), m.tags.end(), tag), m.tags.end());
                }
                std::sort(m.tags.begin(), m.tags.end());
            }
        }
        return true;
    }
    if (n == "delete-tags") {
        if (argv.empty()) { c.error("expecting one or more tags to delete"); return false; }
        for (auto& lf : app.files) for (auto& m : lf->messages) for (auto& t : argv) { std::string tag = starts_with(t, "#") ? t : "#" + t; m.tags.erase(std::remove(m.tags.begin(), m.tags.end(), tag), m.tags.end()); }
        return true;
    }
    if (n == "partition-name") {
        if (c.args.empty()) { c.error("expecting partition name"); return false; }
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) app.files[ve->file_idx]->messages[ve->msg_idx].partition = c.args;
        }
        return true;
    }
    if (n == "clear-partition") {
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) app.files[ve->file_idx]->messages[ve->msg_idx].partition.clear();
        }
        return true;
    }
    if (n == "hide-fields" || n == "show-fields") {
        if (argv.empty()) { c.error("expecting a log message field name"); return false; }
        for (auto& f : argv) { if (n == "hide-fields") app.hidden_fields.insert(f); else app.hidden_fields.erase(f); }
        return true;
    }
    if (n == "hide-file" || n == "show-file" || n == "show-only-this-file") {
        bool show = (n == "show-file");
        if (n == "show-only-this-file") {
            if (!app.log_visible.empty()) {
                const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
                if (ve) { int fi = ve->file_idx; for (size_t k = 0; k < app.files.size(); k++) app.files[k]->visible = ((int) k == fi); }
            }
            app.rebuild_log_view();
            return true;
        }
        if (argv.empty()) {
            if (!app.log_visible.empty()) {
                const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
                if (ve) app.files[ve->file_idx]->visible = show;
            }
        } else {
            for (auto& pat : argv) {
                bool any = false;
                for (auto& lf : app.files) {
                    if (lf->path == pat || basename_of(lf->path) == pat || fnmatch(pat.c_str(), lf->path.c_str(), 0) == 0) { lf->visible = show; any = true; }
                }
                if (!any) { c.error("unknown file -- " + pat); return false; }
            }
        }
        app.rebuild_log_view();
        return true;
    }
    if (n == "hide-lines-before" || n == "hide-lines-after" || n == "show-lines-before-and-after") {
        if (n == "show-lines-before-and-after") { app.apply_filters(); return true; }
        if (argv.empty()) { c.error("expecting a line number or timestamp"); return false; }
        std::string a = c.args;
        struct timeval tv {0, 0};
        int64_t ln;
        if (parse_int(a, ln)) {
            const view_entry* ve = app.entry_for_row((size_t) std::max<int64_t>(0, ln));
            if (!ve) { c.error("invalid line number -- " + a); return false; }
            tv = app.files[ve->file_idx]->messages[ve->msg_idx].tv;
        } else {
            date_time_scanner dts; exttm tm;
            if (!dts.scan(a.data(), a.size(), nullptr, &tm, tv)) { c.error("invalid time: " + a); return false; }
        }
        std::vector<view_entry> vis; size_t row = 0;
        for (auto& ve : app.log_visible) {
            auto& m = app.files[ve.file_idx]->messages[ve.msg_idx];
            bool before = m.tv.tv_sec < tv.tv_sec || (m.tv.tv_sec == tv.tv_sec && m.tv.tv_usec < tv.tv_usec);
            bool after = m.tv.tv_sec > tv.tv_sec || (m.tv.tv_sec == tv.tv_sec && m.tv.tv_usec > tv.tv_usec);
            if (n == "hide-lines-before" && before) continue;
            if (n == "hide-lines-after" && after) continue;
            view_entry v = ve; v.row_start = row; row += v.row_count; vis.push_back(v);
        }
        app.log_visible = vis;
        return true;
    }
    if (n == "highlight") {
        if (c.args.empty()) { c.error("expecting a regular expression to highlight"); return false; }
        try { Regex re(c.args); } catch (regex_error& e) { c.error("invalid regular expression: " + std::string(e.what())); return false; }
        return true;
    }
    if (n == "clear-highlight") { return true; }
    if (n == "open") {
        if (argv.empty()) { c.error("expecting file name to open"); return false; }
        for (auto& p : argv) {
            auto lf = std::make_unique<logfile>();
            lf->path = p; lf->filename = p;
            std::string e;
            if (!lf->load(e)) { c.error("cannot stat file: " + p + " -- " + e); return false; }
            lf->detect_and_index();
            app.files.push_back(std::move(lf));
        }
        app.rebuild_log_view();
        if (app.current_view == "text" && app.has_logs()) {}
        return true;
    }
    if (n == "close") {
        if (app.files.empty()) { c.error("no log files loaded"); return false; }
        if (app.current_view == "log" && !app.log_visible.empty()) {
            const view_entry* ve = app.entry_for_row(std::min(app.log_top, app.log_row_count() - 1));
            if (ve) { app.files.erase(app.files.begin() + ve->file_idx); app.rebuild_log_view(); }
        } else if (app.current_view == "text") {
            for (size_t k = 0; k < app.files.size(); k++) if (app.files[k]->is_text()) { app.files.erase(app.files.begin() + k); break; }
        }
        return true;
    }
    if (n == "quit") { return true; }
    if (n == "sh") {
        if (c.args.empty()) { c.error("expecting a shell command"); return false; }
        fflush(stdout);
        int rc = system(c.args.c_str());
        (void) rc;
        app.produced_output = true;
        return true;
    }
    if (n == "cd") {
        if (argv.empty()) { c.error("expecting a directory"); return false; }
        if (chdir(argv[0].c_str()) != 0) { c.error("unable to change directory: " + argv[0], strerror(errno)); return false; }
        return true;
    }
    if (n == "eval") {
        if (c.args.empty()) { c.error("expecting a command or query to evaluate"); return false; }
        std::string cmd = c.args;
        // expand $VAR
        std::string out;
        for (size_t k = 0; k < cmd.size(); k++) {
            if (cmd[k] == '$' && k + 1 < cmd.size() && (isalpha((unsigned char) cmd[k + 1]) || cmd[k + 1] == '_' || cmd[k + 1] == '{')) {
                size_t j = k + 1; std::string var;
                if (cmd[j] == '{') { size_t e = cmd.find('}', j); var = cmd.substr(j + 1, e - j - 1); j = e + 1; }
                else { while (j < cmd.size() && (isalnum((unsigned char) cmd[j]) || cmd[j] == '_')) j++; var = cmd.substr(k + 1, j - k - 1); }
                const char* v = getenv(var.c_str());
                out += v ? v : "";
                k = j - 1;
            } else out += cmd[k];
        }
        if (out.empty() || (out[0] != ':' && out[0] != ';' && out[0] != '|' && out[0] != '/')) { c.error("expecting a command or query to evaluate", "the evaluated expression must start with ':', ';', '|', or '/'"); return false; }
        execute_command_line(app, out, c.source, c.source_line);
        return true;
    }
    if (n == "unix-time") {
        if (argv.empty()) { c.error("expecting a unix time value"); return false; }
        int64_t v;
        if (!parse_int(argv[0], v)) { c.error("invalid unix time -- " + argv[0]); return false; }
        time_t t = (time_t) v; struct tm tmv; gmtime_r(&t, &tmv);
        char buf[128]; strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y  %z %Z", &tmv);
        c.output = std::string(buf) + " -- " + std::to_string(v);
        return true;
    }
    if (n == "current-time") {
        time_t t = time(nullptr); struct tm tmv; gmtime_r(&t, &tmv);
        char buf[128]; strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y  %z %Z", &tmv);
        c.output = std::string(buf) + " -- " + std::to_string((long long) t);
        return true;
    }
    if (n == "redirect-to") {
        if (argv.empty()) { return true; }
        FILE* f = freopen(argv[0].c_str(), "w", stdout);
        (void) f;
        return true;
    }
    if (n == "rebuild" || n == "redraw" || n == "reset-session" || n == "save-session" || n == "load-session" || n == "session" || n == "clear-all-sticky-headers" || n == "toggle-sticky-header" ||
        n == "enable-word-wrap" || n == "disable-word-wrap" || n == "set-text-view-mode" || n == "zoom-to" || n == "spectrogram" || n == "prompt" || n == "config" || n == "reset-config" ||
