bool execute_command_line(lnav_app& app, const std::string& cmdline, const std::string& source, int source_line)
{
    if (cmdline.empty()) return true;
    char prefix = cmdline[0];
    std::string body = cmdline.substr(1);
    if (prefix == ';') {
        app_error err;
        std::string sql = body;
        if (!sql_execute(app, sql, err, true)) {
            err.snippet_source = source + ":" + std::to_string(source_line);
            err.snippet_text = trim(sql);
            print_error(err);
            return false;
        }
        if (app.last_result.valid) {
            app.last_output_was_db = true;
            if (!app.opts.quiet && app.last_result.valid) {
                // headless: results are printed at the end (or immediately when followed by more commands)
            }
        }
        return true;
    }
    if (prefix == '|') {
        cmd_context c{app, source, source_line, cmdline, "", "", {}, {}, false, ""};
        std::string path = trim(body);
        std::vector<std::string> parts = split_ws(path);
        std::string script = parts.empty() ? "" : parts[0];
        // search the given path directly
        bool ok;
        std::string content = read_file(script, ok);
        if (!ok) {
            c.err.msg = "unknown script -- " + script + " -- file not found";
            c.err.snippet_source = source + ":" + std::to_string(source_line);
            c.err.snippet_text = cmdline;
            print_error(c.err);
            return false;
        }
        run_script_file(app, script, c);
        return true;
    }
    if (prefix == '/') {
        // search: no-op in headless
        return true;
    }
    if (prefix != ':') return true;
    std::string rest = body;
    size_t sp = rest.find_first_of(" \t");
    cmd_context c{app, source, source_line, cmdline, "", "", {}, {}, false, ""};
    c.name = sp == std::string::npos ? rest : rest.substr(0, sp);
    c.args = sp == std::string::npos ? "" : trim(rest.substr(sp + 1));
    c.argv = split_ws(c.args);
    if (c.name.empty()) return true;
    bool ok = exec_single(c);
    if (!ok && c.has_error) report_error(c);
    return ok;
}

int run_commands(lnav_app& app)
{
    int idx = 0;
    for (auto& cmd : app.opts.commands) {
        idx++;
        if (!cmd.empty() && cmd[0] == ';' && app.last_output_was_db && app.last_result.valid && !app.opts.quiet) {
            // a previous query result would be lost: print it first
            fputs(render_db_result(app).c_str(), stdout);
            app.produced_output = true;
        }
        execute_command_line(app, cmd, "command-option", idx);
    }
    return 0;
}
