            zlib.h) need_pkgs="$need_pkgs zlib1g-dev";;
            fmt/format.h) need_pkgs="$need_pkgs libfmt-dev";;
        esac
    fi
done
if [ -n "$need_pkgs" ]; then
    if command -v apt-get >/dev/null 2>&1; then
        (sudo apt-get install -y $need_pkgs || apt-get install -y $need_pkgs) >/dev/null 2>&1 || true
    fi
fi

