static bool format_matches_sample(log_format& b, const std::string& line)
{
    auto* ext = dynamic_cast<external_log_format*>(&b);
    if (!ext) return false;
    if (ext->is_json) {
        json::Value obj;
        if (!ext->parse_json_line(line, obj)) return false;
