void format_registry::finalize_order()
{
    // alphabetical list of external formats
    std::vector<std::shared_ptr<log_format>> alpha;
    for (auto& kv : by_name) {
        if (kv.second->internal) continue;
        alpha.push_back(kv.second);
    }
    std::sort(alpha.begin(), alpha.end(), [](const std::shared_ptr<log_format>& a, const std::shared_ptr<log_format>& b) { return a->name < b->name; });
    for (auto& f : alpha) f->collisions.clear();
    for (auto& a : alpha) {
        for (auto& sample : a->sample_lines) {
            // only the first line of multi-line samples
            std::string first = sample;
            size_t nl = first.find('\\n');
            if (nl != std::string::npos) first = first.substr(0, nl);
            for (auto& b : alpha) {
                if (a == b) continue;
                if (format_matches_sample(*b, first)) b->collisions.insert(a->name);
            }
        }
    }
    std::vector<std::shared_ptr<log_format>> ordered;
    while (!alpha.empty()) {
        std::vector<std::string> popped;
        for (auto it = alpha.begin(); it != alpha.end();) {
            if ((*it)->collisions.empty()) {
                popped.push_back((*it)->name);
                ordered.push_back(*it);
                it = alpha.erase(it);
            } else {
                ++it;
            }
        }
        if (popped.empty() && !alpha.empty()) {
            bool broke = false;
            for (auto& f : alpha) {
                if (f->builtin) continue;
                f->collisions.clear();
                broke = true;
                break;
            }
            if (!broke) alpha.front()->collisions.clear();
            continue;
        }
        for (auto& f : alpha) for (auto& p : popped) f->collisions.erase(p);
    }
    root_formats.clear();
    auto bro = std::make_shared<null_log_format>("bro", "Bro Network Security Monitor");
    auto w3c = std::make_shared<null_log_format>("w3c_log", "W3C Extended Log File Format");
    auto logfmt = std::make_shared<logfmt_log_format>();
    auto piper = std::make_shared<piper_log_format>();
