static json::Value value_to_json(sqlite3_value* v)
{
    switch (sqlite3_value_type(v)) {
    case SQLITE_NULL: return json::Value::null();
    case SQLITE_INTEGER: return json::Value::integer(sqlite3_value_int64(v));
    case SQLITE_FLOAT: return json::Value::number(sqlite3_value_double(v));
    default: {
        std::string s = arg_text(v);
        if (sqlite3_value_subtype(v) == 'J') { try { return json::parse(s); } catch (...) {} }
        return json::Value::string(s);
    }
    }
}
static void fn_json_group_array_scalar(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    json::Value arr = json::Value::array();
    for (int k = 0; k < argc; k++) arr.push(value_to_json(argv[k]));
    std::string out = json::to_string(arr);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
static void fn_json_group_object_scalar(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    json::Value obj = json::Value::object();
    for (int k = 0; k + 1 < argc; k += 2) obj.set(arg_text(argv[k]), value_to_json(argv[k + 1]));
    std::string out = json::to_string(obj);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
struct json_agg_ctx { json::Value* v; };
static void fn_json_group_array_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
