    if (!a) return;
    if (!a->v) { a->v = new json::Value(json::Value::array()); }
    for (int k = 0; k < argc; k++) a->v->push(value_to_json(argv[k]));
}
static void fn_json_group_array_final(sqlite3_context* ctx)
{
    auto* a = (json_agg_ctx*) sqlite3_aggregate_context(ctx, 0);
    json::Value arr = json::Value::array();
    if (a && a->v) { arr = *a->v; delete a->v; a->v = nullptr; }
    std::string out = json::to_string(arr);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
