{
    std::string out;
    for (size_t i = 0; i < s.size(); i++) { if (s[i] == '%' && i + 2 < s.size() && isxdigit((unsigned char) s[i + 1]) && isxdigit((unsigned char) s[i + 2])) { out += (char) strtol(s.substr(i + 1, 2).c_str(), nullptr, 16); i += 2; } else if (s[i] == '+') out += ' '; else out += s[i]; }
    return out;
}
static void fn_parse_url(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string url = arg_text(argv[0]);
    json::Value obj = json::Value::object();
    size_t p = url.find("://");
    if (p == std::string::npos) { std::string e = "invalid URL: " + url; sqlite3_result_error(ctx, e.c_str(), -1); return; }
    obj.set("scheme", json::Value::string(url.substr(0, p)));
    std::string rest = url.substr(p + 3);
    size_t frag = rest.find('#');
    std::string fragment; bool has_frag = false; if (frag != std::string::npos) { fragment = rest.substr(frag + 1); rest = rest.substr(0, frag); has_frag = true; }
    size_t q = rest.find('?');
    std::string query; bool has_query = false; if (q != std::string::npos) { query = rest.substr(q + 1); rest = rest.substr(0, q); has_query = true; }
    size_t slash = rest.find('/');
    std::string authority = slash == std::string::npos ? rest : rest.substr(0, slash);
    std::string path = slash == std::string::npos ? "/" : rest.substr(slash);
    std::string user, pass, host, port;
    bool has_user = false, has_pass = false;
    size_t at = authority.rfind('@');
    if (at != std::string::npos) { std::string ui = authority.substr(0, at); authority = authority.substr(at + 1); size_t c = ui.find(':'); if (c != std::string::npos) { user = ui.substr(0, c); pass = ui.substr(c + 1); has_pass = true; } else user = ui; has_user = true; }
    if (!authority.empty() && authority[0] == '[') {
        size_t close = authority.find(']');
        host = authority.substr(0, close == std::string::npos ? std::string::npos : close + 1);
        if (close != std::string::npos && close + 1 < authority.size() && authority[close + 1] == ':') port = authority.substr(close + 2);
    } else {
        size_t colon = authority.rfind(':');
        if (colon != std::string::npos) { host = authority.substr(0, colon); port = authority.substr(colon + 1); } else host = authority;
    }
    obj.set("username", has_user ? json::Value::string(url_decode(user)) : json::Value::null());
    obj.set("password", has_pass ? json::Value::string(url_decode(pass)) : json::Value::null());
    obj.set("host", host.empty() ? json::Value::null() : json::Value::string(host));
    obj.set("port", port.empty() ? json::Value::null() : json::Value::string(port));
    obj.set("path", json::Value::string(url_decode(path)));
    if (has_query) {
        obj.set("query", json::Value::string(query));
        json::Value qo = json::Value::object();
        for (auto& kv : split(query, '&')) { if (kv.empty()) continue; size_t e = kv.find('='); if (e == std::string::npos) qo.set(url_decode(kv), json::Value::null()); else qo.set(url_decode(kv.substr(0, e)), json::Value::string(url_decode(kv.substr(e + 1)))); }
        obj.set("parameters", qo);
    } else { obj.set("query", json::Value::null()); obj.set("parameters", json::Value::null()); }
    obj.set("fragment", has_frag ? json::Value::string(url_decode(fragment)) : json::Value::null());
    std::string out = json::to_string(obj);
    sqlite3_result_text(ctx, out.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_result_subtype(ctx, 'J');
}
