new_fuzzy='''static bool fts_fuzzy_match_recursive(const char* pattern, const char* str, int& outScore, const char* strBegin, const uint8_t* srcMatches, uint8_t* matches, int maxMatches, int nextMatch, int& recursionCount, int recursionLimit)
{
    ++recursionCount;
    if (recursionCount >= recursionLimit) return false;
    if (*pattern == '\\0' || *str == '\\0') return false;
    bool recursiveMatch = false;
    uint8_t bestRecursiveMatches[256];
    int bestRecursiveScore = 0;
    bool first_match = true;
    while (*pattern != '\\0' && *str != '\\0') {
        if (tolower((unsigned char) *pattern) == tolower((unsigned char) *str)) {
            if (nextMatch >= maxMatches) return false;
            if (first_match && srcMatches) { memcpy(matches, srcMatches, nextMatch); first_match = false; }
            uint8_t recursiveMatches[256];
            int recursiveScore;
            if (fts_fuzzy_match_recursive(pattern, str + 1, recursiveScore, strBegin, matches, recursiveMatches, sizeof(recursiveMatches), nextMatch, recursionCount, recursionLimit)) {
                if (!recursiveMatch || recursiveScore > bestRecursiveScore) { memcpy(bestRecursiveMatches, recursiveMatches, 256); bestRecursiveScore = recursiveScore; }
                recursiveMatch = true;
            }
            matches[nextMatch++] = (uint8_t) (str - strBegin);
            ++pattern;
        }
        ++str;
    }
    bool matched = *pattern == '\\0';
    if (matched) {
        const int sequential_bonus = 15, separator_bonus = 30, camel_bonus = 30, first_letter_bonus = 15;
        const int leading_letter_penalty = -5, max_leading_letter_penalty = -15, unmatched_letter_penalty = -1;
        while (*str != '\\0') ++str;
        outScore = 100;
        int penalty = leading_letter_penalty * matches[0];
        if (penalty < max_leading_letter_penalty) penalty = max_leading_letter_penalty;
        outScore += penalty;
        int unmatched = (int) (str - strBegin) - nextMatch;
        outScore += unmatched_letter_penalty * unmatched;
        for (int i = 0; i < nextMatch; ++i) {
            uint8_t currIdx = matches[i];
            if (i > 0) { uint8_t prevIdx = matches[i - 1]; if (currIdx == (prevIdx + 1)) outScore += sequential_bonus; }
            if (currIdx > 0) {
                char neighbor = strBegin[currIdx - 1];
                char curr = strBegin[currIdx];
                if (islower((unsigned char) neighbor) && isupper((unsigned char) curr)) outScore += camel_bonus;
                bool neighborSeparator = neighbor == '_' || neighbor == ' ' || neighbor == '-' || neighbor == '/' || neighbor == '.';
                if (neighborSeparator) outScore += separator_bonus;
            } else {
                outScore += first_letter_bonus;
            }
        }
    }
    if (recursiveMatch && (!matched || bestRecursiveScore > outScore)) { memcpy(matches, bestRecursiveMatches, maxMatches); outScore = bestRecursiveScore; return true; }
    return matched;
}
static void fn_fuzzy_match(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL || sqlite3_value_type(argv[1]) == SQLITE_NULL) { sqlite3_result_null(ctx); return; }
    std::string pat = arg_text(argv[0]), s = arg_text(argv[1]);
    uint8_t matches[256];
    int score = 0, rec = 0;
    if (fts_fuzzy_match_recursive(pat.c_str(), s.c_str(), score, s.c_str(), nullptr, matches, sizeof(matches), 0, rec, 10)) sqlite3_result_int(ctx, score);
    else sqlite3_result_int(ctx, 0);
}
