{
    static const char* units[] = {"B", "KB", "MB", "GB", "TB", "PB", "EB"};
    bool neg = v < 0;
    if (neg) v = -v;
    double d = (double) v;
    int u = 0;
    while (d >= 1000.0 && u < 6) { d /= 1000.0; u++; }
    char buf[64];
    if (u == 0) snprintf(buf, sizeof(buf), "%s%lldB", neg ? "-" : "", (long long) v);
    else snprintf(buf, sizeof(buf), "%s%.1f%s", neg ? "-" : "", d, units[u]);
    return buf;
}

std::string humanize_duration(double secs)
{
    bool neg = secs < 0;
    if (neg) secs = -secs;
    int64_t usecs = (int64_t) (secs * 1000000.0 + 0.5);
    int64_t total = usecs / 1000000;
    int64_t msecs = (usecs % 1000000) / 1000;
    int64_t days = total / 86400; total %= 86400;
    int64_t hours = total / 3600; total %= 3600;
    int64_t mins = total / 60; total %= 60;
    std::string out;
    char buf[32];
    if (neg) out += "-";
    if (days > 0) { snprintf(buf, sizeof(buf), "%lldd", (long long) days); out += buf; }
    if (hours > 0 || days > 0) { snprintf(buf, sizeof(buf), days > 0 ? "%02lldh" : "%lldh", (long long) hours); out += buf; }
    if (mins > 0 || hours > 0 || days > 0) { snprintf(buf, sizeof(buf), (hours > 0 || days > 0) ? "%02lldm" : "%lldm", (long long) mins); out += buf; }
    if (days > 0 || hours > 0 || mins > 0) {
        snprintf(buf, sizeof(buf), "%02llds", (long long) total); out += buf;
    } else if (total > 0 || msecs == 0) {
        snprintf(buf, sizeof(buf), "%llds", (long long) total); out += buf;
    }
    if (msecs > 0 && days == 0 && hours == 0 && mins == 0) { snprintf(buf, sizeof(buf), total > 0 ? "%03lldms" : "%lldms", (long long) msecs); out += buf; }
    return out;
}

